INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('42387ea3-5884-4a2e-9575-b7d84d653a39'::uuid,'01990b5b-e2ef-7ee0-b3ff-11cb2e2113a8'::uuid,'Talons','Action','None','Talons. Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Slashing damage, or 9 (3d4 + 2) Slashing damage if the aarakocra moved 30+ feet straight toward the target immediately before the hit.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('5f391d31-13f1-4e6f-8d6b-dcc3248bf42c'::uuid,'01990b5b-e2ef-7ee0-b3ff-11cb2e2113a8'::uuid,'Wind Javelin','Action','None','Wind Javelin. Melee or Ranged Attack Roll: +4, reach 5 ft. or range 30/120 ft. Hit: 5 (1d6 + 2) Piercing damage plus 2 (1d4) Thunder damage. Hit or Miss: The javelin magically returns to the aarakocra''s hand immediately after a ranged attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('14d38ffc-3130-4026-a301-f7135749d8ef'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'Consume Memories','Action','None','Intelligence Saving Throw: DC 16, one creature within 30 feet that is Charmed or Grappled by the aboleth. Failure: 10 (3d6) Psychic damage. Success: Half damage. Failure or Success: The aboleth gains the target''s memories if the target is a Humanoid and is reduced to 0 Hit Points by this action.',NULL,NULL,'d6',3,'Psychic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3c9a0be0-9462-4d71-93d8-6eaae0328d49'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'Multiattack','Action','None','The aboleth makes two Tentacle attacks and uses either Consume Memories or Dominate Mind if available.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('513be73f-8dd6-4770-9ce9-bd03eb2584e3'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'Tentacle','Action','Melee','Melee Attack Roll: +9, reach 15 ft. Hit: 12 (2d6 + 5) Bludgeoning damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from one of four tentacles.',9,5,'d6',2,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('bc86f7e6-b970-4cbb-88f0-63390fec2d1a'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'Lash','Legendary','Melee','The aboleth makes one Tentacle attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('eb5e9751-32c1-4f76-b69e-008653a644d3'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'Psychic Drain','Legendary','None','If the aboleth has at least one creature Charmed or Grappled, it uses Consume Memories and regains 5 (1d10) Hit Points.',NULL,NULL,'d10',1,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ed9e1bf4-67a0-419a-b96e-72cb8d03e723'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'Dominate Mind','Action','None','Wisdom Saving Throw: DC 16, one creature the aboleth can see within 30 feet. Failure: The target has the Charmed condition until the aboleth dies or is on a different plane of existence from the target. While Charmed, the target acts as an ally to the aboleth and is under its control while within 60 feet of it. In addition, the aboleth and the target can communicate telepathically with each other over any distance. The target repeats the save whenever it takes damage as well as after every 24 hours it spends at least 1 mile away from the aboleth, ending the effect on itself on a success.',NULL,NULL,NULL,NULL,NULL,2,false,NULL,NULL,NULL,NULL,NULL),
	 ('43b2f5a2-f398-4386-8fc4-354590bab09c'::uuid,'01990b5c-aee7-7898-a2f6-48c3874a04d2'::uuid,'Acid Breath (Recharge 5–6)','Action','None','Acid Breath (Recharge 5–6). Dexterity Saving Throw: DC 18, each creature in a 60-foot-long, 5-foot-wide Line. Failure: 54 (12d8) Acid damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('499e4426-cb8b-4153-a1c2-34b0f73c1c8f'::uuid,'01990b5c-aee7-7898-a2f6-48c3874a04d2'::uuid,'Multiattack','Action','None','Multiattack. The dragon makes three Rend attacks. It can replace one attack with a use of Spellcasting to cast Melf''s Acid Arrow (level 3 version).',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('6ca7165d-6abc-4fc8-881c-1abdc7483812'::uuid,'01990b5c-aee7-7898-a2f6-48c3874a04d2'::uuid,'Spellcasting','Action','None','Spellcasting. The dragon casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 17, +9 to hit with spell attacks):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7003073f-6c25-4639-8f9f-188d63a0ac41'::uuid,'01990b5c-aee7-7898-a2f6-48c3874a04d2'::uuid,'Frightful Presence','Legendary','None','Frightful Presence. The dragon uses Spellcasting to cast Fear. The dragon can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('713f99f2-c6c4-461d-ab2f-7d6474e1d388'::uuid,'01990b5c-aee7-7898-a2f6-48c3874a04d2'::uuid,'Pounce','Legendary','None','Pounce. The dragon moves up to half its Speed, and it makes one Rend attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('723ee386-aa3e-410b-8d77-c75213047893'::uuid,'01990b5c-aee7-7898-a2f6-48c3874a04d2'::uuid,'Cloud of Insects','Legendary','None','Cloud of Insects. Dexterity Saving Throw: DC 17, one creature the dragon can see within 120 feet. Failure: 22 (4d10) Poison damage, and the target has Disadvantage on saving throws to maintain Concentration until the end of its next turn. Failure or Success: The dragon can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('bc6e682c-2d20-4f9c-92d3-2924368abc81'::uuid,'01990b5c-aee7-7898-a2f6-48c3874a04d2'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +11, reach 10 ft. Hit: 13 (2d6 + 6) Slashing damage plus 4 (1d8) Acid damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0b2e59c3-3815-4ed2-94e1-a94504344c9b'::uuid,'01990b5c-e19f-7df2-84c2-95757a34cecc'::uuid,'Tail Swipe','Legendary','Melee','The dragon makes one Rend attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('0e935284-3d17-4a76-b2da-9888fff6952c'::uuid,'01990b5c-e19f-7df2-84c2-95757a34cecc'::uuid,'Spellcasting','Action','None','Spellcasting. The dragon casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 18):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('132f962b-bc9e-49c5-a3e7-99192b25de1a'::uuid,'01990b5c-e19f-7df2-84c2-95757a34cecc'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +12, reach 10 ft. Hit: 16 (2d8 + 7) Slashing damage plus 5 (1d10) Lightning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('40785ae5-d03d-4431-9d07-1c5e5c048bdb'::uuid,'01990b5c-e19f-7df2-84c2-95757a34cecc'::uuid,'Cloaked Flight','Legendary','None','The dragon uses Spellcasting to cast Invisibility on itself, and it can fly up to half its Fly Speed. The dragon can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('51c13fd0-cae9-4f97-a200-1b19c1aac09b'::uuid,'01990b5c-e19f-7df2-84c2-95757a34cecc'::uuid,'Lightning Breath (Recharge 5–6)','Action','None','Lightning Breath (Recharge 5–6). Dexterity Saving Throw: DC 19, each creature in a 90-foot-long, 5-foot-wide Line. Failure: 60 (11d10) Lightning damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
