	 ('cc0fbe8e-a581-475c-93b2-d95e44a2030b'::uuid,'01990b5c-e19f-7df2-84c2-95757a34cecc'::uuid,'Multiattack','Action','None','Multiattack. The dragon makes three Rend attacks. It can replace one attack with a use of Spellcasting to cast Shatter.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('13e66900-19ad-45b6-bd98-4d9f31a08e96'::uuid,'01990b5d-2220-7fcb-8a9e-62ac929409b1'::uuid,'Scorching Sands','Legendary','None','Dexterity Saving Throw: DC 16, one creature the dragon can see within 120 feet. Failure: 27 (6d8) Fire damage, and the target''s Speed is halved until the end of its next turn. Failure or Success: The dragon can''t take this action again until the start of its next turn.',NULL,NULL,'d8',6,'Fire',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('326c69ca-dbce-435b-824c-c7f2c47385e6'::uuid,'01990b5d-2220-7fcb-8a9e-62ac929409b1'::uuid,'Blazing Light','Legendary','Ranged','The dragon uses Spellcasting to cast Scorching Ray.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('32f22a19-33d1-4f8e-a973-f89a61d50fc8'::uuid,'01990b5d-2220-7fcb-8a9e-62ac929409b1'::uuid,'Fire Breath (Recharge 5–6)','Action','None','Fire Breath (Recharge 5–6). Dexterity Saving Throw: DC 18, each creature in a 60-foot-long, 5-foot-wide Line. Failure: 45 (10d8) Fire damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8d985208-ef83-4b43-ae5c-f4a216143616'::uuid,'01990b5d-2220-7fcb-8a9e-62ac929409b1'::uuid,'Sleep Breath','Action','None','Sleep Breath. Constitution Saving Throw: DC 18, each creature in a 60-foot Cone. Failure: The target has the Incapacitated condition until the end of its next turn, at which point it repeats the save. Second Failure: The target has the Unconscious condition for 10 minutes. This effect ends for the target if it takes damage or a creature within 5 feet of it takes an action to wake it.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a83d4e3d-75bf-4181-b3d8-602e83e81f7e'::uuid,'01990b5d-2220-7fcb-8a9e-62ac929409b1'::uuid,'Pounce','Legendary','Melee','The dragon moves up to half its Speed, and it makes one Rend attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b48f9bb1-b66f-47f3-bf7f-64e1c45536f9'::uuid,'01990b5d-2220-7fcb-8a9e-62ac929409b1'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +11, reach 10 ft. Hit: 17 (2d10 + 6) Slashing damage plus 4 (1d8) Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('bd7cff42-a254-4cad-8199-82b553ba4599'::uuid,'01990b5d-2220-7fcb-8a9e-62ac929409b1'::uuid,'Multiattack','Action','None','Multiattack. The dragon makes three Rend attacks. It can replace one attack with a use of (A) Sleep Breath or (B) Spellcasting to cast Scorching Ray.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
