	 ('b516177e-0d7a-417e-8e01-ac2dbc3308f6'::uuid,'01990b5d-5e2d-7693-a477-4073b9a46907'::uuid,'Lightning Breath (Recharge 5–6)','Action','None','Lightning Breath (Recharge 5–6). Dexterity Saving Throw: DC 19, each creature in a 90-foot-long, 5-foot-wide Line. Failure: 55 (10d10) Lightning damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
