	 ('729db53d-fe2d-4fdd-a261-8c12a265dfda'::uuid,'01990b7d-8464-7423-bf35-301eb7b90e44'::uuid,'Lightning Breath (Recharge 5–6)','Action','None','Lightning Breath (Recharge 5–6). Dexterity Saving Throw: DC 23, each creature in a 120-foot-long, 10-foot-wide Line. Failure: 82 (15d10) Lightning damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
