	 ('a7445332-dd9c-4cc6-be43-3b7371f6e833'::uuid,'01990b7d-8464-7423-bf35-301eb7b90e44'::uuid,'Spellcasting','Action','None','Spellcasting. The dragon casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 22, +14 to hit with spell attacks):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('aef953d1-b82f-4a9c-b8f9-6317dba17c9a'::uuid,'01990b7d-8464-7423-bf35-301eb7b90e44'::uuid,'Guiding Light','Legendary','Ranged','The dragon uses Spellcasting to cast Guiding Bolt (level 2 version).',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c35f7983-ea38-462a-b20e-0ca3fb55be91'::uuid,'01990b7d-8464-7423-bf35-301eb7b90e44'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +16, reach 15 ft. Hit: 18 (2d8 + 9) Slashing damage plus 9 (2d8) Lightning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
