	 ('2a562ee3-97e6-4330-829e-69455d909953'::uuid,'01990b7e-e2db-7f94-980d-c3d816ea0774'::uuid,'Smother','Action','None','Smother. Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Bludgeoning damage. If the target is a Medium or smaller creature, the rug can give it the Grappled condition (escape DC 13) instead of dealing damage. Until the grapple ends, the target has the Blinded and Restrained conditions, is suffocating, and takes 10 (2d6 + 3) Bludgeoning damage at the start of each of its turns. The rug can smother only one creature at a time. While grappling the target, the rug can''t take this action, the rug halves the damage it takes (round down), and the target takes the same amount of damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('547c0ca0-fa77-419a-866a-4e76f8a09941'::uuid,'01990b7e-f212-77ac-9ca0-e7b03f007090'::uuid,'Acid Spray (Recharge 6)','Action','None','Acid Spray (Recharge 6). Dexterity Saving Throw: DC 12, each creature in a 30-foot-long, 5-foot-wide Line. Failure: 14 (4d6) Acid damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('dc4a2c08-0ac1-49d0-8c79-0786ae9e6e32'::uuid,'01990b7e-f212-77ac-9ca0-e7b03f007090'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +5 (with Advantage if the target is Grappled by the ankheg), reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage plus 3 (1d6) Acid damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 13).',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f3e22dc2-a399-426c-a53a-a1fceb89dd57'::uuid,'01990b7e-fd2e-777f-a941-0958504f3336'::uuid,'Tail','Action','Melee','Melee Attack Roll: +6, reach 10 ft. Hit: 9 (1d10 + 4) Bludgeoning damage. If the target is a Huge or smaller creature, it has the Prone condition.',6,4,'d10',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL);
