	 ('28475efa-fa61-4379-a59d-28e348b21039'::uuid,'01990b7f-6041-7fe4-bcce-41ed203b0eb5'::uuid,'Spellcasting','Action','None','Spellcasting. The archmage casts one of the following spells, using Intelligence as the spellcasting ability (spell save DC 17):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('3736884f-8033-41f3-a331-2ff19acd1968'::uuid,'01990b7f-6041-7fe4-bcce-41ed203b0eb5'::uuid,'Multiattack','Action','None','Multiattack. The archmage makes four Arcane Burst attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
