	 ('d06089d8-79a7-40fa-9867-bcde2399dae1'::uuid,'01990b7f-6041-7fe4-bcce-41ed203b0eb5'::uuid,'Arcane Burst','Action','None','Arcane Burst. Melee or Ranged Attack Roll: +9, reach 5 ft. or range 150 ft. Hit: 27 (4d10 + 5) Force damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('686a75d2-8289-4c54-b8ae-9a03af9ce424'::uuid,'01990b7f-8f4f-7a28-a8c0-f48e5aec8e59'::uuid,'Holy Word (Recharge 4–6)','Action','None','Holy Word (Recharge 4–6). Wisdom Saving Throw: DC 17, each enemy in a 20-foot Emanation originating from the archpriest. Failure: 21 (6d6) Radiant damage, and the target has the Stunned condition until the end of the archpriest''s next turn. Success: Half damage only.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7f339e20-b75f-43be-bc78-77e521fe7f3b'::uuid,'01990b7f-8f4f-7a28-a8c0-f48e5aec8e59'::uuid,'Spellcasting','Action','None','Spellcasting. The archpriest casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 17):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('bb1d05d7-9261-4672-9e8c-e1198581b634'::uuid,'01990b7f-8f4f-7a28-a8c0-f48e5aec8e59'::uuid,'Multiattack','Action','None','Multiattack. The archpriest makes three Radiant Burst attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ee87c3cd-79a5-4a4a-ac7d-64c96f4b552e'::uuid,'01990b7f-8f4f-7a28-a8c0-f48e5aec8e59'::uuid,'Radiant Burst','Action','None','Radiant Burst. Melee or Ranged Attack Roll: +9, reach 5 ft. or range 60 ft. Hit: 27 (4d10 + 5) Radiant damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('960f218f-eefd-441d-b5c6-84ef76ae0b72'::uuid,'01990b7f-b32a-72f3-8697-6b09e2c1253f'::uuid,'Shortsword','Action','Melee','Melee Attack Roll: +7, reach 5 ft. Hit: 7 (1d6 + 4) Piercing damage plus 17 (5d6) Poison damage, and the target has the Poisoned condition until the start of the assassin''s next turn.',7,4,'d6',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ad2a6c8d-5c62-4586-b36b-ac5d95e456e9'::uuid,'01990b7f-b32a-72f3-8697-6b09e2c1253f'::uuid,'Light Crossbow','Action','Ranged','Ranged Attack Roll: +7, range 80/320 ft. Hit: 8 (1d8 + 4) Piercing damage plus 21 (6d6) Poison damage.',7,4,'d8',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b8b6ec82-527d-44b5-8343-22b7a64155a0'::uuid,'01990b7f-b32a-72f3-8697-6b09e2c1253f'::uuid,'Multiattack','Action','None','The assassin makes three attacks, using Shortsword or Light Crossbow in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('69c7b535-580c-4659-8fc8-60898ab22614'::uuid,'01990b7f-bafc-7ccc-95ae-e252304c63c8'::uuid,'Rake','Action','None','Rake. Melee Attack Roll: +1, reach 5 ft. Hit: 1 Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
