	 ('70e5a3f7-3dbf-415f-8a2a-4c966ca0365b'::uuid,'01990b80-2cfa-7ed3-a8d5-c6aad63c171e'::uuid,'Flame Whip','Action','None','Flame Whip. Melee Attack Roll: +14, reach 30 ft. Hit: 18 (3d6 + 8) Force damage plus 17 (5d6) Fire damage. If the target is a Huge or smaller creature, the balor pulls the target up to 25 feet straight toward itself, and the target has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
