	 ('593856be-7cf6-4639-9632-e4d4bbb170ea'::uuid,'01990b80-36d6-7672-97ef-b05408248832'::uuid,'Scimitar','Action','None','Scimitar. Melee Attack Roll: +3, reach 5 ft. Hit: 4 (1d6 + 1) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('cc425f01-3142-4de2-aee7-c82075b6c7bb'::uuid,'01990b80-36d6-7672-97ef-b05408248832'::uuid,'Light Crossbow','Action','None','Light Crossbow. Ranged Attack Roll: +3, range 80/320 ft. Hit: 5 (1d8 + 1) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
