	 ('86f40539-d35e-443b-8fb4-a311a9528306'::uuid,'01990b80-4e48-7e0a-b4f7-f36d9a12e863'::uuid,'Pistol','Action','None','Pistol. Ranged Attack Roll: +5, range 30/90 ft. Hit: 8 (1d10 + 3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ab91a823-0333-4610-9373-c750640c5420'::uuid,'01990b80-4e48-7e0a-b4f7-f36d9a12e863'::uuid,'Parry','Reaction','None','The bandit adds 2 to its AC against the triggering attack, possibly causing it to miss.',NULL,NULL,NULL,NULL,NULL,NULL,false,'The bandit is hit by a melee attack roll while holding a weapon.',NULL,NULL,NULL,NULL),
	 ('d82e1d11-3d5b-4a30-9209-71a6155ac597'::uuid,'01990b80-4e48-7e0a-b4f7-f36d9a12e863'::uuid,'Multiattack','Action','None','Multiattack. The bandit makes two attacks, using Scimitar and Pistol in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e95c31b4-c585-48f8-b135-64af1f6e92bb'::uuid,'01990b80-4e48-7e0a-b4f7-f36d9a12e863'::uuid,'Scimitar','Action','None','Scimitar. Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('54ae1a68-a293-4964-a8df-7fd7cbcb2457'::uuid,'01990b80-8bc7-7fe9-9808-3b9fc06815b0'::uuid,'Tail','Action','None','Tail. Melee Attack Roll: +6, reach 10 ft. Hit: 14 (2d10 + 3) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('56a03151-65aa-432e-82f7-f9a4295674f2'::uuid,'01990b80-8bc7-7fe9-9808-3b9fc06815b0'::uuid,'Multiattack','Action','None','Multiattack. The devil makes one Claws attack and one Tail attack, or it makes two Hurl Flame attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('77b11ec4-5d9c-4c45-bd98-343b8b636a45'::uuid,'01990b80-8bc7-7fe9-9808-3b9fc06815b0'::uuid,'Hurl Flame','Action','None','Hurl Flame. Ranged Attack Roll: +5, range 150 ft. Hit: 17 (5d6) Fire damage. If the target is a flammable object that isn''t being worn or carried, it starts burning.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('dd0e68fb-2194-4464-82b0-578697e4ea9e'::uuid,'01990b80-8bc7-7fe9-9808-3b9fc06815b0'::uuid,'Claws','Action','None','Claws. Melee Attack Roll: +6, reach 5 ft. Hit: 10 (2d6 + 3) Piercing damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 13) from both claws.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('91c50dfa-8dcb-42e0-8c95-5118ea6d2994'::uuid,'01990b80-aa28-7272-9d4e-d8191165d6d9'::uuid,'Petrifying Gaze','Bonus','None','Constitution Saving Throw: DC 12, each creature in a 30-foot Cone. If the basilisk sees its reflection in the Cone, the basilisk must make this save. First Failure: The target has the Restrained condition and repeats the save at the end of its next turn if it is still Restrained, ending the effect on itself on a success. Second Failure: The target has the Petrified condition instead of the Restrained condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'Recharge 4–6',NULL,NULL,NULL,NULL),
	 ('9d230439-0bd4-4264-8ebf-398c4eae3c7f'::uuid,'01990b80-aa28-7272-9d4e-d8191165d6d9'::uuid,'Bite','Action','Melee','Hit: 10 (2d6 + 3) Piercing damage plus 7 (2d6) Poison damage.',5,NULL,'d6',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('cfeaffc7-c669-4275-b57d-21ba51b73221'::uuid,'01990b80-b1f0-7b8b-ab88-b3b78569a562'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 1 Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0ba7e343-e3bc-433b-bbc9-a75ce51323a0'::uuid,'01990b80-d2ba-74f7-ad01-dc60d8a4be6f'::uuid,'Multiattack','Action','None','Multiattack. The devil makes one Beard attack and one Infernal Glaive attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('9d61283c-3a6f-4263-bdaa-36bd88925b8f'::uuid,'01990b80-d2ba-74f7-ad01-dc60d8a4be6f'::uuid,'Infernal Glaive','Action','None','Infernal Glaive. Melee Attack Roll: +5, reach 10 ft. Hit: 8 (1d10 + 3) Slashing damage. If the target is a creature and doesn''t already have an infernal wound, it is subjected to the following effect. Constitution Saving Throw: DC 12. Failure: The target receives an infernal wound. While wounded, the target loses 5 (1d10) Hit Points at the start of each of its turns. The wound closes after 1 minute, after a spell restores Hit Points to the target, or after the target or a creature within 5 feet of it takes an action to stanch the wound, doing so by succeeding on a DC 12 Wisdom (Medicine) check.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d458b673-1017-4ef8-bd40-60018bf48f82'::uuid,'01990b80-d2ba-74f7-ad01-dc60d8a4be6f'::uuid,'Beard','Action','None','Beard. Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Piercing damage, and the target has the Poisoned condition until the start of the devil''s next turn. Until this poison ends, the target can''t regain Hit Points.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('14614bdd-f036-481e-be31-5d934cb12cfa'::uuid,'01990b80-f7ef-7df9-a111-03f3fcccb61e'::uuid,'Swallow','Bonus','None','Dexterity Saving Throw: DC 18, one Large or smaller creature Grappled by the behir (the behir can have only one creature swallowed at a time). Failure: The behir swallows the target, which is no longer Grappled. While swallowed, a creature has the Blinded and Restrained conditions, has Total Cover against attacks and other effects outside the behir, and takes 21 (6d6) Acid damage at the start of each of the behir''s turns. If the behir takes 30 damage or more on a single turn from the swallowed creature, the behir must succeed on a DC 14 Constitution saving throw at the end of that turn or regurgitate the creature, which falls in a space within 10 feet of the behir and has the Prone condition. If the behir dies, a swallowed creature is no longer Restrained and can escape from the corpse by using 15 feet of movement, exiting Prone.',NULL,NULL,'d6',6,'Acid',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ad039aff-618b-4b9c-924c-ebcd86a6f767'::uuid,'01990b80-f7ef-7df9-a111-03f3fcccb61e'::uuid,'Multiattack','Action','None','Multiattack. The behir makes one Bite attack and uses Constrict.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('b1a18d03-c73a-4457-b4ed-6d7f59810d2c'::uuid,'01990b80-f7ef-7df9-a111-03f3fcccb61e'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +10, reach 10 ft. Hit: 19 (2d12 + 6) Piercing damage plus 11 (2d10) Lightning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('b62356d9-4c19-45b6-b9e9-411231abbeab'::uuid,'01990b80-f7ef-7df9-a111-03f3fcccb61e'::uuid,'Constrict','Action','None','Constrict. Strength Saving Throw: DC 18, one Large or smaller creature the behir can see within 5 feet. Failure: 28 (5d8 + 6) Bludgeoning damage. The target has the Grappled condition (escape DC 16), and it has the Restrained condition until the grapple ends.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f0b703c0-fcef-48bf-b440-cab45b220a60'::uuid,'01990b80-f7ef-7df9-a111-03f3fcccb61e'::uuid,'Lightning Breath (Recharge 5–6)','Action','None','Lightning Breath (Recharge 5–6). Dexterity Saving Throw: DC 16, each creature in a 90-foot-long, 5-foot-wide Line. Failure: 66 (12d10) Lightning damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('83bf87a4-ea54-4903-b93b-fbf7f6332e87'::uuid,'01990b81-1afd-7699-82ba-9e57cb3d6bc2'::uuid,'Greataxe','Action','Melee','Hit: 9 (1d12 + 3) Slashing damage.',5,3,'d12',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('33ce1e12-7840-4198-a66f-66dfe945bdab'::uuid,'01990b81-3834-7351-a4b2-d0d4594d4ddd'::uuid,'Multiattack','Action','None','Multiattack. The berserker makes three attacks, using Greataxe or Javelin in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('839159eb-36bc-4956-b432-9dd73e469894'::uuid,'01990b81-3834-7351-a4b2-d0d4594d4ddd'::uuid,'Greataxe','Action','None','Greataxe. Melee Attack Roll: +7, reach 5 ft. Hit: 10 (1d12 + 4) Slashing damage, plus 10 (3d6) Thunder damage to the target or another creature within 5 feet of the target.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('b7a0cb5c-8a2d-4306-8f08-de6367d5818d'::uuid,'01990b81-3834-7351-a4b2-d0d4594d4ddd'::uuid,'Javelin','Action','None','Javelin. Melee or Ranged Attack Roll: +7, reach 5 ft. or range 30/120 ft. Hit: 18 (4d6 + 4) Piercing damage, and the target''s Speed decreases by 5 feet until the start of the berserker''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d002af41-8eae-4874-bf6b-dbf37212afa8'::uuid,'01990b81-3834-7351-a4b2-d0d4594d4ddd'::uuid,'Frenzied Rush','Bonus','None','Each ally within 30 feet of the berserker can take a Reaction to move up to half the ally''s Speed without provoking Opportunity Attacks. The berserker can also move up to half its Speed without provoking Opportunity Attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b953fc8b-5407-4101-a342-600a8cc60f04'::uuid,'01990b81-496c-79b3-ad05-7dac646a28cc'::uuid,'Rend','Action','Melee','Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Slashing damage.',4,2,'d6',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ca1e772b-2daa-4a86-84a4-7f0177b89ccc'::uuid,'01990b81-496c-79b3-ad05-7dac646a28cc'::uuid,'Multiattack','Action','None','The bear makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('bc01fc7e-d0a0-4edb-9f8a-a0fa859c593c'::uuid,'01990b81-5e6c-787c-bf13-6a2af60608ec'::uuid,'Rend','Action','Melee','Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Slashing damage plus 2 (1d4) Acid damage.',4,NULL,'d6',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('d180e7ea-5676-497e-9a34-e6bc6b49fde8'::uuid,'01990b81-5e6c-787c-bf13-6a2af60608ec'::uuid,'Multiattack','Action','None','The dragon makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('e3c6004f-a844-472d-80d0-e340efa64702'::uuid,'01990b81-5e6c-787c-bf13-6a2af60608ec'::uuid,'Acid Breath','Action','Ranged','Dexterity Saving Throw: DC 11, each creature in a 15-foot-long, 5-foot-wide Line. Failure: 22 (5d8) Acid damage. Success: Half damage.',NULL,NULL,'d8',5,'Acid',5,false,NULL,NULL,NULL,NULL,NULL),
	 ('3b203bbf-a8b8-4eae-ac29-468de55034c0'::uuid,'01990b81-7e06-74b1-b275-591731ca6231'::uuid,'Dissolving Pseudopod','Action','Melee','Hit: 17 (4d6 + 3) Acid damage. Nonmagical armor worn by the target takes a -1 penalty to the AC it offers. The armor is destroyed if the penalty reduces its AC to 10. The penalty can be removed by casting the Mending spell on the armor.',5,3,'d6',4,'Acid',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('af49d353-d14c-42f5-8df6-70bfb616e363'::uuid,'01990b81-7e06-74b1-b275-591731ca6231'::uuid,'Split','Reaction','None','While the pudding is Large or Medium and has 10+ Hit Points, it becomes Bloodied or is subjected to Lightning or Slashing damage. The pudding splits into two new Black Puddings. Each new pudding is one size smaller than the original pudding and acts on its Initiative. The original pudding''s Hit Points are divided evenly between the new puddings (round down).',NULL,NULL,NULL,NULL,NULL,NULL,false,'While the pudding is Large or Medium and has 10+ Hit Points, it becomes Bloodied or is subjected to Lightning or Slashing damage.',NULL,NULL,NULL,NULL),
	 ('937b37b3-9a7e-4617-a6f1-8ea77c6ca147'::uuid,'01990b81-a0e0-7eaa-be54-be5c1227c639'::uuid,'Teleport','Bonus','None','The dog teleports up to 40 feet to an unoccupied space it can see.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('acc01fcd-f0a1-4f10-8c0d-f3be4275dbf2'::uuid,'01990b81-a0e0-7eaa-be54-be5c1227c639'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4+3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('78bf51af-35d0-4bfd-9551-d5a1a7dc555f'::uuid,'01990b81-b7b7-75d3-992f-3d3e3db3b941'::uuid,'Beak','Action','None','Beak. Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Piercing damage, or 6 (1d8 + 2) Piercing damage if the target is Bloodied.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('083aecbf-f60f-409a-a65a-e3d3355aee40'::uuid,'01990b81-d989-7917-ad31-ace6e98e01c7'::uuid,'Rend','Action','Melee','Melee Attack Roll: +5, reach 5 ft. Hit: 8 (1d10 + 3) Slashing damage plus 3 (1d6) Lightning damage.',5,NULL,'d10',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('116cf810-bd27-40f1-a121-a1bcc0e926e9'::uuid,'01990b81-d989-7917-ad31-ace6e98e01c7'::uuid,'Multiattack','Action','None','The dragon makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('4b5d4238-c798-4077-b250-501cf76a835b'::uuid,'01990b81-d989-7917-ad31-ace6e98e01c7'::uuid,'Lightning Breath','Action','Ranged','Dexterity Saving Throw: DC 12, each creature in a 30-foot-long, 5-foot-wide Line. Failure: 21 (6d6) Lightning damage. Success: Half damage.',NULL,NULL,'d6',6,'Lightning',5,false,'Recharge 5-6',NULL,NULL,NULL,NULL),
	 ('618f1c49-eba5-46f2-b042-1179bfc85262'::uuid,'01990b81-fa5c-76ef-ab6d-78c02d7160d5'::uuid,'Gore','Action','None','Gore. Melee Attack Roll: +3, reach 5 ft. Hit: 4 (1d6 + 1) Piercing damage. If the target is a Medium or smaller creature and the boar moved 20+ feet straight toward it immediately before the hit, the target takes an extra 3 (1d6) Piercing damage and has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('5156352f-9ffa-49b4-9ad7-2bf3d9d74e92'::uuid,'01990b82-1b34-7f2d-921a-c00875c4f558'::uuid,'Claw','Action','Melee','Melee Attack Roll: +8, reach 10 ft. Hit: 13 (2d8 + 4) Slashing damage.',8,4,'d8',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('6456576e-c6c2-4ab1-9940-3b6c7eeeabfb'::uuid,'01990b82-1b34-7f2d-921a-c00875c4f558'::uuid,'Multiattack','Action','None','The devil makes two Claw attacks and one Infernal Sting attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('7bd3c618-8d6b-416e-a313-c23e7477d141'::uuid,'01990b82-1b34-7f2d-921a-c00875c4f558'::uuid,'Infernal Sting','Action','Melee','Melee Attack Roll: +8, reach 10 ft. Hit: 15 (2d10 + 4) Piercing damage plus 18 (4d8) Poison damage, and the target has the Poisoned condition until the start of the devil''s next turn. While Poisoned, the target can''t regain Hit Points.',8,4,'d10',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('61775d5e-543b-4d16-b55d-39294d63caf6'::uuid,'01990b82-49b7-7a41-9342-7c290648592e'::uuid,'Sleep Breath','Action','None','Sleep Breath. Constitution Saving Throw: DC 11, each creature in a 15-foot Cone. Failure: The target has the Incapacitated condition until the end of its next turn, at which point it repeats the save. Second Failure: The target has the Unconscious condition for 1 minute. This effect ends for the target if it takes damage or a creature within 5 feet of it takes an action to wake it.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('826f2d6c-b4ca-4598-8f4b-ee0cd4beb56c'::uuid,'01990b82-49b7-7a41-9342-7c290648592e'::uuid,'Fire Breath (Recharge 5–6)','Action','None','Fire Breath (Recharge 5–6). Dexterity Saving Throw: DC 11, each creature in a 20-foot-long, 5-foot-wide Line. Failure: 14 (4d6) Fire damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c5e59028-22fd-427a-944a-913acce62f52'::uuid,'01990b82-49b7-7a41-9342-7c290648592e'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +4, reach 5 ft. Hit: 7 (1d10 + 2) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('912fadee-fb82-4a1b-8768-53f057d6bc64'::uuid,'01990b82-78a4-78a2-bbf7-923daeb741c7'::uuid,'Repulsion Breath','Action','None','Repulsion Breath. Strength Saving Throw: DC 12, each creature in a 30-foot Cone. Failure: The target is pushed up to 30 feet straight away from the dragon and has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('b6d78e0c-a70b-48fd-8703-05ac2baf196c'::uuid,'01990b82-78a4-78a2-bbf7-923daeb741c7'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +5, reach 5 ft. Hit: 8 (1d10 + 3) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('cf0106be-3351-4a26-91e8-47cc57690135'::uuid,'01990b82-78a4-78a2-bbf7-923daeb741c7'::uuid,'Multiattack','Action','None','Multiattack. The dragon makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('39b5fda5-33c1-4d35-82eb-ae38f6739c19'::uuid,'01990b83-d0dc-7a41-86a8-fc87ac2de215'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +7, reach 5 ft. Hit: 7 (1d6 + 4) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e9adbb79-dd80-468c-85e5-05283e212c69'::uuid,'01990b82-78a4-78a2-bbf7-923daeb741c7'::uuid,'Lightning Breath (Recharge 5–6) Dexterity Saving T...','Action','None','Lightning Breath (Recharge 5–6) Dexterity Saving Throw: DC 12, each creature in a 40-foot-long, 5-foot-wide Line. Failure: 16 (3d10) Lightning damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('516d27ae-1b54-4b74-a927-d2a855400f54'::uuid,'01990b82-8e61-76f6-a20e-a4ad60db2c5b'::uuid,'Claw','Action','Melee','Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4 + 3) Slashing damage. If the target is a Large or smaller creature, it has the Prone condition.',5,3,'d4',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL);
