	 ('773e7241-fafb-4009-88fb-a5fba80bb7e5'::uuid,'01990b82-8e61-76f6-a20e-a4ad60db2c5b'::uuid,'Bite','Action','Melee','Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Piercing damage.',5,3,'d8',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
