	 ('6888dbe3-e922-40b5-b4ba-9a8f4c74a179'::uuid,'01990b82-b1fe-7d5a-bf6c-402ce07b35c1'::uuid,'Javelin','Action','None','Javelin. Melee or Ranged Attack Roll: +5, reach 10 ft. or range 30/120 ft. Hit: 13 (3d6 + 3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('9b4c9530-dab5-49e3-85aa-bf8b938801f0'::uuid,'01990b82-b1fe-7d5a-bf6c-402ce07b35c1'::uuid,'Multiattack','Action','None','Multiattack. The bugbear makes two Javelin or Morningstar attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('9fc2b9e8-c649-43f1-ab58-80b3120fb918'::uuid,'01990b82-b1fe-7d5a-bf6c-402ce07b35c1'::uuid,'Quick Grapple','Bonus','None','Dexterity Saving Throw: DC 13, one Medium or smaller creature the bugbear can see within 10 feet. Failure: The target has the Grappled condition (escape DC 13).',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a976066d-b34e-4017-945c-54e81175de12'::uuid,'01990b82-b1fe-7d5a-bf6c-402ce07b35c1'::uuid,'Morningstar','Action','None','Morningstar. Melee Attack Roll: +5 (with Advantage if the target is Grappled by the bugbear), reach 10 ft. Hit: 12 (2d8 + 3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('975bbab2-c35b-4030-b7c3-48a16fc940fb'::uuid,'01990b82-c7d6-7162-a5b7-480ec0195fa1'::uuid,'Grab','Action','None','Grab. Melee Attack Roll: +4, reach 10 ft. Hit: 9 (2d6 + 2) Bludgeoning damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 12).',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c4b324cb-cc6d-4615-8f00-cd762f0c63e2'::uuid,'01990b82-c7d6-7162-a5b7-480ec0195fa1'::uuid,'Light Hammer','Action','None','Light Hammer. Melee or Ranged Attack Roll: +4 (with Advantage if the target is Grappled by the bugbear), reach 10 ft. or range 20/60 ft. Hit: 9 (3d4 + 2) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('235f2365-6bfa-4c75-9b14-18f877a7a83a'::uuid,'01990b82-dddb-79c5-acc6-1d9d0ab13c9a'::uuid,'Multiattack','Action','None','The bulette makes two Bite attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('2bb5d0ff-cb42-4748-ab63-71141f95d20d'::uuid,'01990b82-dddb-79c5-acc6-1d9d0ab13c9a'::uuid,'Leap','Bonus','None','The bulette jumps up to 30 feet by spending 10 feet of movement.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('97684077-3b00-441e-953e-ed151d493b8c'::uuid,'01990b82-dddb-79c5-acc6-1d9d0ab13c9a'::uuid,'Bite','Action','Melee','Melee Attack Roll: +7, reach 5 ft. Hit: 17 (2d12 + 4) Piercing damage.',7,4,'d12',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b89a640e-1145-4c18-8ebf-b19bd186f157'::uuid,'01990b82-dddb-79c5-acc6-1d9d0ab13c9a'::uuid,'Deadly Leap','Action','None','The bulette spends 5 feet of movement to jump to a space within 15 feet that contains one or more Large or smaller creatures. Dexterity Saving Throw: DC 15, each creature in the bulette''s destination space. Failure: 19 (3d12) Bludgeoning damage, and the target has the Prone condition. Success: Half damage, and the target is pushed 5 feet straight away from the bulette.',NULL,NULL,'d12',3,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('090d51f6-69cf-4d23-91cf-db03743a5866'::uuid,'01990b83-0353-7b20-9d38-01e134faa474'::uuid,'Spellcasting','Action','None','The bullywug casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 13, +5 to hit with spell attacks).',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('84376959-98cc-4793-843c-b989d5e35af4'::uuid,'01990b83-0353-7b20-9d38-01e134faa474'::uuid,'Multiattack','Action','None','The bullywug makes two Bog Staff attacks. It can replace any attack with a use of Spellcasting to cast Ray of Sickness.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('850e04ae-2871-424b-8fd5-51bcaa222a62'::uuid,'01990b83-0353-7b20-9d38-01e134faa474'::uuid,'Leap','Bonus','None','The bullywug jumps up to 30 feet by spending 10 feet of movement.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('eed61fd4-d566-44b3-b39c-084e7945a1d8'::uuid,'01990b83-0353-7b20-9d38-01e134faa474'::uuid,'Bog Staff','Action','Melee','Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Bludgeoning damage plus 10 (3d6) Poison damage.',5,3,'d8',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('12954020-2d69-405f-8308-a963a14238c6'::uuid,'01990b83-1f9a-7427-808a-c5984549892c'::uuid,'Insectile Rapier','Action','Melee','Hit: 6 (1d8 + 2) Piercing damage plus 2 (1d4) Poison damage.',4,NULL,'d8',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('2f4cab4a-0417-49cd-816e-5dcfb10ddbe7'::uuid,'01990b83-1f9a-7427-808a-c5984549892c'::uuid,'Leap','Bonus','None','The bullywug jumps up to 30 feet by spending 10 feet of movement.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('953aefb4-b916-499b-9827-eab828768f7b'::uuid,'01990b83-25f0-7700-b4bf-d8cb9d82a9f4'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('06c09332-f57e-447e-a65f-c84be8558618'::uuid,'01990b83-42cf-7519-b33f-ea568b9da725'::uuid,'Paralyzing Tentacles','Action','None','Constitution Saving Throw: DC 12, one creature the carrion crawler can see within 10 feet. Failure: The target has the Poisoned condition and repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically. While Poisoned, the target has the Paralyzed condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('329c77ae-5d7f-4815-b799-a934d1352cf2'::uuid,'01990b83-42cf-7519-b33f-ea568b9da725'::uuid,'Bite','Action','Melee','Melee Attack Roll: +4, reach 5 ft. Hit: 7 (2d4 + 2) Piercing damage plus 3 (1d6) Poison damage.',4,NULL,'d4',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('cc5bac43-27e3-4a42-8a97-42a8d5a05ea0'::uuid,'01990b83-42cf-7519-b33f-ea568b9da725'::uuid,'Multiattack','Action','None','The carrion crawler uses Paralyzing Tentacles and makes one Bite attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('363b9727-f005-4fb4-917b-9fd0ba4c3956'::uuid,'01990b83-54c1-7ab2-b12a-e573bf143a17'::uuid,'Scratch','Action','None','Scratch. Melee Attack Roll: +4, reach 5 ft. Hit: 1 Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2ff659f7-bd64-4313-9d30-9097ad4e053f'::uuid,'01990b83-7712-7dc9-a91b-76b02e3db3b7'::uuid,'Longbow','Action','None','Longbow. Ranged Attack Roll: +4, range 150/600 ft. Hit: 6 (1d8 + 2) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7ba4c3cc-2e18-46e8-9156-9ab6c4d6d17c'::uuid,'01990b83-7712-7dc9-a91b-76b02e3db3b7'::uuid,'Pike','Action','None','Pike. Melee Attack Roll: +6, reach 10 ft. Hit: 9 (1d10 + 4) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a279d85b-2ad4-4172-9521-ebc0e32175bf'::uuid,'01990b83-7712-7dc9-a91b-76b02e3db3b7'::uuid,'Trampling Charge','Bonus','Melee','The centaur moves up to its Speed without provoking Opportunity Attacks and can move through the spaces of Medium or smaller creatures. Each creature whose space the centaur enters is targeted once by the following effect. Strength Saving Throw: DC 14. Failure: 7 (1d6 + 4) Bludgeoning damage, and the target has the Prone condition.',NULL,4,'d6',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('daeda7a4-84d5-4fae-b7c1-615bd841ab07'::uuid,'01990b83-7712-7dc9-a91b-76b02e3db3b7'::uuid,'Multiattack','Action','None','Multiattack. The centaur makes two attacks, using Pike or Longbow in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('4cb34d4f-5e53-45b7-a263-f638d99829e0'::uuid,'01990b83-a488-7fca-a5dc-87c3fd0c8b43'::uuid,'Unnerving Gaze','Reaction','None','Trigger: A creature the devil can see starts its turn within 30 feet of the devil and can see the devil. Response—Wisdom Saving Throw: DC 15, the triggering creature. Failure: The target has the Frightened condition until the end of its turn. Success: The target is immune to this devil''s Unnerving Gaze for 24 hours.',NULL,NULL,NULL,NULL,NULL,NULL,false,'A creature the devil can see starts its turn within 30 feet of the devil and can see the devil',NULL,NULL,NULL,NULL),
	 ('671659a2-c75c-4070-adf5-6f6ee3aab702'::uuid,'01990b83-a488-7fca-a5dc-87c3fd0c8b43'::uuid,'Chain','Action','Melee','Melee Attack Roll: +7, reach 10 ft. Hit: 11 (2d6 + 4) Slashing damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from one of two chains, and it has the Restrained condition until the grapple ends.',7,4,'d6',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ca20340a-ff32-49c3-b749-48baf3efd4fb'::uuid,'01990b83-a488-7fca-a5dc-87c3fd0c8b43'::uuid,'Conjure Infernal Chain','Action','None','The devil conjures a fiery chain to bind a creature. Dexterity Saving Throw: DC 15, one creature the devil can see within 60 feet. Failure: 9 (2d4 + 4) Fire damage, and the target has the Restrained condition until the end of the devil''s next turn, at which point the chain disappears. If the target is Large or smaller, the devil moves the target up to 30 feet straight toward itself. Success: The chain disappears.',NULL,4,'d4',2,'Fire',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('5e06c107-c776-4af3-b948-fbf4b166900b'::uuid,'01990b83-d0dc-7a41-86a8-fc87ac2de215'::uuid,'Multiattack','Action','None','Multiattack. The chimera makes one Ram attack, one Bite attack, and one Claw attack. It can replace the Claw attack with a use of Fire Breath if available.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8a89bce3-922a-4387-8bb6-a3c2a6955650'::uuid,'01990b83-d0dc-7a41-86a8-fc87ac2de215'::uuid,'Fire Breath (Recharge 5–6)','Action','None','Fire Breath (Recharge 5–6). Dexterity Saving Throw: DC 15, each creature in a 15-foot Cone. Failure: 31 (7d8) Fire damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('bd6165c6-5d08-49c8-a62b-47c288a30e8e'::uuid,'01990b83-d0dc-7a41-86a8-fc87ac2de215'::uuid,'Ram','Action','None','Ram. Melee Attack Roll: +7, reach 5 ft. Hit: 10 (1d12 + 4) Bludgeoning damage. If the target is a Medium or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('edcdb1f4-1b39-4d21-ae6d-36a806fb2546'::uuid,'01990b83-d0dc-7a41-86a8-fc87ac2de215'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +7, reach 5 ft. Hit: 11 (2d6 + 4) Piercing damage, or 18 (4d6 + 4) Piercing damage if the chimera had Advantage on the attack roll.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0a6cdb35-4ee0-4b58-93ed-b192d51b3d5a'::uuid,'01990b83-e93c-7189-964e-49e522ccbc94'::uuid,'Multiattack','Action','None','The chuul makes two Pincer attacks and uses Paralyzing Tentacles.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('333758cd-cd00-4a8a-b8c0-42c67d4365ec'::uuid,'01990b83-e93c-7189-964e-49e522ccbc94'::uuid,'Paralyzing Tentacles','Action','None','Failure: The target has the Poisoned condition and repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically. While Poisoned, the target has the Paralyzed condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('aa9300b4-60ab-44fb-a2bc-23fab0108617'::uuid,'01990b83-e93c-7189-964e-49e522ccbc94'::uuid,'Pincer','Action','Melee','Hit: 9 (1d10 + 4) Bludgeoning damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from one of two pincers.',6,4,'d10',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('0257ca8f-1f3b-4b1a-b513-f7d5c9197043'::uuid,'01990b84-11da-783f-8008-0d2a54a2f35f'::uuid,'Multiattack','Action','Melee','The golem makes two Slam attacks, or it makes three Slam attacks if it used Hasten this turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('0849a85f-1224-4d37-bed1-9a539c76f99f'::uuid,'01990b84-11da-783f-8008-0d2a54a2f35f'::uuid,'Hasten','Bonus','None','The golem takes the Dash and Disengage actions.',NULL,NULL,NULL,NULL,NULL,NULL,false,'Recharge 5-6',NULL,NULL,NULL,NULL),
	 ('764b5613-e681-4c13-a4bb-679fd8179e9d'::uuid,'01990b84-11da-783f-8008-0d2a54a2f35f'::uuid,'Slam','Action','Melee','Melee Attack Roll: +9, reach 5 ft. Hit: 10 (1d10 + 5) Bludgeoning damage plus 6 (1d12) Acid damage, and the target''s Hit Point maximum decreases by an amount equal to the Acid damage taken.',9,NULL,'d10',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('37f7c9b4-d5c2-46c3-a986-eae5071b954f'::uuid,'01990b84-4e29-7bd4-a153-266dabb756b2'::uuid,'Multiattack','Action','None','Multiattack. The cloaker makes one Attach attack and two Tail attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('60fee0c6-acb0-4593-9498-bf0c4faa3f0c'::uuid,'01990b84-4e29-7bd4-a153-266dabb756b2'::uuid,'Phantasms','Bonus','None','The cloaker casts the Mirror Image spell, requiring no spell components and using Wisdom as the spellcasting ability. The spell ends early if the cloaker starts or ends its turn in Bright Light.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('8e1e2836-c057-411a-858e-ca942dde0b10'::uuid,'01990b84-4e29-7bd4-a153-266dabb756b2'::uuid,'Tail','Action','None','Tail. Melee Attack Roll: +6, reach 10 ft. Hit: 8 (1d10 + 3) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a4904005-2bb0-42ed-8c40-aea1d424e923'::uuid,'01990b84-4e29-7bd4-a153-266dabb756b2'::uuid,'Moan','Bonus','None','Wisdom Saving Throw: DC 13, each creature in a 60-foot Emanation originating from the cloaker. Failure: The target has the Frightened condition until the end of the cloaker''s next turn. Success: The target is immune to this cloaker''s Moan for the next 24 hours.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('f5ea33fb-7b58-4f88-8ebe-fbf49307478e'::uuid,'01990b84-4e29-7bd4-a153-266dabb756b2'::uuid,'Attach','Action','None','Attach. Melee Attack Roll: +6, reach 5 ft. Hit: 13 (3d6 + 3) Piercing damage. If the target is a Large or smaller creature, the cloaker attaches to it. While the cloaker is attached, the target has the Blinded condition, and the cloaker can''t make Attach attacks against other targets. In addition, the cloaker halves the damage it takes (round down), and the target takes the same amount of damage. The cloaker can detach itself by spending 5 feet of movement. The target or a creature within 5 feet of it can take an action to try to detach the cloaker, doing so by succeeding on a DC 14 Strength (Athletics) check.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('042f290e-53c6-4d59-8989-882b15c311c7'::uuid,'01990b84-7797-7678-b9a6-b04709e7ab40'::uuid,'Thundercloud','Action','None','Thundercloud. Ranged Attack Roll: +12, range 240 ft. Hit: 18 (3d6 + 8) Thunder damage, and the target has the Incapacitated condition until the end of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0f4093a3-2e3a-4a5a-81ec-072e3840ee50'::uuid,'01990b84-7797-7678-b9a6-b04709e7ab40'::uuid,'Multiattack','Action','None','Multiattack. The giant makes two attacks, using Thunderous Mace or Thundercloud in any combination. It can replace one attack with a use of Spellcasting to cast Fog Cloud.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('23697c3b-2bb6-46c9-9051-bad1b5563193'::uuid,'01990b84-7797-7678-b9a6-b04709e7ab40'::uuid,'Thunderous Mace','Action','None','Thunderous Mace. Melee Attack Roll: +12, reach 10 ft. Hit: 21 (3d8 + 8) Bludgeoning damage plus 7 (2d6) Thunder damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('4080d4c2-14ef-4946-b491-d9ed62983ffd'::uuid,'01990b84-7797-7678-b9a6-b04709e7ab40'::uuid,'Spellcasting','Action','None','Spellcasting. The giant casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 15):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a5f0c5e2-3ddf-4228-9e31-b1dc25cfef10'::uuid,'01990b84-7797-7678-b9a6-b04709e7ab40'::uuid,'Misty Step','Bonus','None','The giant casts the Misty Step spell, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('4a96ec3e-6f90-4064-9add-5ae4bbdcbe2c'::uuid,'01990b84-8463-7f43-bef1-1f8e74a0543c'::uuid,'Petrifying Bite','Action','Melee','Hit: 3 (1d4 + 1) Piercing damage. If the target is a creature, it is subjected to the following effect. Constitution Saving Throw: DC 11. First Failure: The target has the Restrained condition. The target repeats the save at the end of its next turn if it is still Restrained, ending the effect on itself on a success. Second Failure: The target has the Petrified condition, instead of the Restrained condition, for 24 hours.',3,1,'d4',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a4878c6d-5911-4125-ae08-73c2c38288eb'::uuid,'01990b84-a6be-7413-a6de-e6cd8a77693a'::uuid,'Club','Action','Melee','Hit: 2 (1d4) Bludgeoning damage.',2,NULL,'d4',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('8b9ecbc9-1a5c-4216-a3de-3cb1216c7631'::uuid,'01990b84-b0ff-7381-9f99-f52e92ce162e'::uuid,'Constrict','Action','None','Failure: 7 (3d4) Bludgeoning damage, and the target has the Grappled condition (escape DC 12).',NULL,NULL,'d4',3,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ede0d36e-30da-43ed-b134-1ff327d27f2f'::uuid,'01990b84-b0ff-7381-9f99-f52e92ce162e'::uuid,'Bite','Action','Melee','Hit: 6 (1d8 + 2) Piercing damage.',4,2,'d8',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('052137c6-e883-481a-8d7d-6f594c1a6f95'::uuid,'01990b84-c470-7507-962a-acef2dc8301e'::uuid,'Slowing Breath','Action','None','Slowing Breath. Constitution Saving Throw: DC 11, each creature in a 15-foot Cone. Failure: The target can''t take Reactions; its Speed is halved; and it can take either an action or a Bonus Action on its turn, not both. This effect lasts until the end of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('281fa18c-6523-4bd3-8085-bbb0ffc2131e'::uuid,'01990b84-c470-7507-962a-acef2dc8301e'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +4, reach 5 ft. Hit: 7 (1d10 + 2) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8cc7571c-fc39-46c1-96ca-e81d8855d4c8'::uuid,'01990b84-c470-7507-962a-acef2dc8301e'::uuid,'Acid Breath (Recharge 5–6)','Action','None','Acid Breath (Recharge 5–6). Dexterity Saving Throw: DC 11, each creature in a 20-foot-long, 5-foot-wide Line. Failure: 18 (4d8) Acid damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('19277c96-3227-456d-81cb-cc264329ca24'::uuid,'01990b84-e8d3-7a19-905f-f794fd139b8d'::uuid,'Constrict','Action','None','Failure: 8 (1d6 + 5) Bludgeoning damage. The target has the Grappled condition (escape DC 13), and it has the Restrained condition until the grapple ends.',NULL,NULL,'d6',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('26b2f0cc-0a43-46ee-b053-5e68b9302ea3'::uuid,'01990b84-e8d3-7a19-905f-f794fd139b8d'::uuid,'Divine Aid','Bonus','None','The couatl casts Bless, Lesser Restoration, or Sanctuary, requiring no spell components and using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,2,false,NULL,NULL,NULL,NULL,NULL),
	 ('c16f9cea-9175-451b-ad18-d325b7a7bdf1'::uuid,'01990b84-e8d3-7a19-905f-f794fd139b8d'::uuid,'Bite','Action','Melee','Hit: 11 (1d12 + 5) Piercing damage, and the target has the Poisoned condition until the end of the couatl''s next turn.',7,5,'d12',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL);
