	 ('ed281a90-8a2c-461b-86e3-89494c37a6f1'::uuid,'01990b84-e8d3-7a19-905f-f794fd139b8d'::uuid,'Spellcasting','Action','None','The couatl casts one of the following spells, requiring no spell components and using Wisdom as the spellcasting ability (spell save DC 15):',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('44808886-46e6-4d67-8a71-7af804df5c35'::uuid,'01990b84-f750-704b-b607-e7db69ae8bfa'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +2, reach 5 ft. Hit: 1 Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('49897254-a5d4-4b2c-86fa-112a17b81593'::uuid,'01990b85-0977-7b28-b494-93290ebc9fa1'::uuid,'Slam','Action','None','Slam. Melee Attack Roll: +3, reach 5 ft. Hit: 2 Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('07d66833-a7ac-4b35-b014-0aa2419975a0'::uuid,'01990b85-1c56-7205-85c3-47035b70aed4'::uuid,'Bite','Action','Melee','Hit: 6 (1d8 + 2) Piercing damage. If the target is Medium or smaller, it has the Grappled condition (escape DC 12). While Grappled, the target has the Restrained condition.',4,2,'d8',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c0c64bbe-5c1f-4252-9ff5-0bdf7e32d8d5'::uuid,'01990b85-28ee-746c-ae0c-eff53bb2b3c5'::uuid,'Ritual Sickle','Action','None','Ritual Sickle. Melee Attack Roll: +3, reach 5 ft. Hit: 3 (1d4 + 1) Slashing damage plus 1 Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('722e59f2-1756-4e41-9735-e074b472ec9a'::uuid,'01990b85-40b8-7145-84ca-901c2c250ca5'::uuid,'Spellcasting','Action','None','The cultist casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 12, +4 to hit with spell attacks).',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('fe3087fe-96ef-490e-892c-8a94557fd913'::uuid,'01990b85-40b8-7145-84ca-901c2c250ca5'::uuid,'Spiritual Weapon','Bonus','None','The cultist casts the Spiritual Weapon spell, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,2,false,NULL,NULL,NULL,NULL,NULL),
	 ('ff82fc7e-d014-486c-a01a-373a1b640bd9'::uuid,'01990b85-40b8-7145-84ca-901c2c250ca5'::uuid,'Pact Blade','Action','Melee','Hit: 6 (1d8 + 2) Slashing damage plus 7 (2d6) Necrotic damage.',4,NULL,'d8',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3fb0eb1e-0c07-4f19-b2e4-5170d97cfceb'::uuid,'01990b85-63f2-708b-a711-cef326d626f8'::uuid,'Darkness Aura (1/Day)','Action','None','Magical Darkness fills a 15-foot Emanation originating from the darkmantle. This effect lasts while the darkmantle maintains Concentration on it, up to 10 minutes. Darkvision can''t penetrate this area, and no light can illuminate it.',NULL,NULL,NULL,NULL,NULL,1,false,NULL,NULL,NULL,NULL,NULL),
	 ('f191d3d5-b673-4abd-b4d8-7f9b0837ae23'::uuid,'01990b85-63f2-708b-a711-cef326d626f8'::uuid,'Crush','Action','Melee','Hit: 6 (1d6 + 3) Bludgeoning damage, and the darkmantle attaches to the target. If the target is a Medium or smaller creature and the darkmantle had Advantage on the attack roll, it covers the target, which has the Blinded condition and is suffocating while the darkmantle is attached in this way. While attached to a target, the darkmantle can attack only the target but has Advantage on its attack rolls. Its Speed becomes 0, it can''t benefit from any bonus to its Speed, and it moves with the target. A creature can take an action to try to detach the darkmantle from itself, doing so with a successful DC 13 Strength (Athletics) check. On its turn, the darkmantle can detach itself by using 5 feet of movement.',5,3,'d6',1,'Bludgeoning',NULL,false,NULL,'the darkmantle had Advantage on the attack roll',NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('59eca2a1-35ed-45af-8326-961a48fd050a'::uuid,'01990b85-824e-79d6-b460-221330517ae2'::uuid,'Spirit Wail','Bonus','None','Wisdom Saving Throw: DC 14, each creature in a 20-foot Emanation originating from the cultist. Failure: 14 (4d6) Psychic damage, and the target has the Frightened condition until the end of its next turn. Success: Half damage only.',NULL,NULL,'d6',4,'Psychic',5,false,'Recharge 5-6',NULL,NULL,NULL,NULL),
	 ('69ff1ac3-da70-4fe7-9fa8-5d510b32342b'::uuid,'01990b85-824e-79d6-b460-221330517ae2'::uuid,'Dread Scythe','Action','None','Dread Scythe. Melee Attack Roll: +7, reach 10 ft. Hit: 9 (1d10 + 4) Slashing damage plus 11 (2d10) Necrotic damage, and the target can''t regain Hit Points until the end of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('83e8fdf1-3805-47dd-ae50-aae2da278b2b'::uuid,'01990b85-824e-79d6-b460-221330517ae2'::uuid,'Deathly Ray','Action','None','Deathly Ray. Ranged Attack Roll: +6, range 120 ft. Hit: 22 (4d10) Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a06a6fe9-b07c-4bdb-95b7-f8ffd422aff1'::uuid,'01990b85-824e-79d6-b460-221330517ae2'::uuid,'Spellcasting','Action','None','Spellcasting. The cultist casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 14):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a14efabd-4b4d-442b-a1d5-4c0bf199f4d7'::uuid,'01990b85-824e-79d6-b460-221330517ae2'::uuid,'Multiattack','Action','None','Multiattack. The cultist makes three attacks, using Dread Scythe or Deathly Ray in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0280ec4c-0661-4f2f-90fa-5bc909278b3e'::uuid,'01990b85-8f8f-7eae-b5fa-bcd5245bdef2'::uuid,'Multiattack','Action','None','The death dog makes two Bite attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3a127956-1352-4672-a58a-666c6d71d62f'::uuid,'01990b85-8f8f-7eae-b5fa-bcd5245bdef2'::uuid,'Bite','Action','Melee','Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Piercing damage. If the target is a creature, it is subjected to the following effect. Constitution Saving Throw: DC 12. First Failure: The target has the Poisoned condition. While Poisoned, the target''s Hit Point maximum doesn''t return to normal when finishing a Long Rest, and it repeats the save every 24 hours that elapse, ending the effect on itself on a success. Subsequent Failures: The Poisoned target''s Hit Point maximum decreases by 5 (1d10).',4,2,'d4',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('98cbf274-05ef-4974-94fd-f191f8dcd320'::uuid,'01990b85-c435-7d99-9eae-82cbfc6fc221'::uuid,'Ram','Action','None','Ram. Melee Attack Roll: +2, reach 5 ft. Hit: 2 (1d4) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0928f97b-17e9-47fa-bd65-69d0f2db3990'::uuid,'01990b85-f49c-72ad-b0ae-1763b0203178'::uuid,'Divine Aid','Bonus','None','The deva casts Cure Wounds, Lesser Restoration, or Remove Curse, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,2,false,NULL,NULL,NULL,NULL,NULL),
	 ('0f800ebd-8eab-46ad-ab6f-470026e4311d'::uuid,'01990b85-f49c-72ad-b0ae-1763b0203178'::uuid,'Holy Mace','Action','Melee','Melee Attack Roll: +8, reach 5 ft. Hit: 7 (1d6 + 4) Bludgeoning damage plus 18 (4d8) Radiant damage.',8,4,'d6',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('252ce1da-7e13-4a38-99ba-b954aceee90b'::uuid,'01990b85-f49c-72ad-b0ae-1763b0203178'::uuid,'Spellcasting','Action','None','The deva casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 17):',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5e0816fb-eae4-434b-8e60-48587041ec82'::uuid,'01990b85-f49c-72ad-b0ae-1763b0203178'::uuid,'Multiattack','Action','Melee','The deva makes two Holy Mace attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('cf87d6ed-8ce6-42e6-a1f6-d473c7ecb2f6'::uuid,'01990b86-05c3-7455-ac1c-9c646a8d4bec'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +5, reach 5 ft. Hit: 8 (1d10 + 3) Piercing damage. If the target is a Large or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a0366624-8a30-4b1a-af55-91d24d6ffc00'::uuid,'01990b86-24c4-7135-b0fb-44bba7d015fe'::uuid,'Tentacle','Action','None','Tentacle. Melee Attack Roll: +6, reach 10 feet. Hit: 11 (2d6 + 4) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ace02d2e-c77a-4ebc-8833-31564b49f970'::uuid,'01990b86-24c4-7135-b0fb-44bba7d015fe'::uuid,'Multiattack','Action','None','Multiattack. The displacer beast makes one Rend attack and one Tentacle attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ef895a34-7edd-484e-86f3-49db57927899'::uuid,'01990b86-24c4-7135-b0fb-44bba7d015fe'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +6, reach 5 feet. Hit: 9 (1d10 + 4) Slashing damage. If target is a Large or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('266e4ac1-8606-4879-9445-3a413303b31d'::uuid,'01990b86-4a7a-785c-b525-bc7cb0a0ffab'::uuid,'Storm Bolt','Action','None','Storm Bolt. Ranged Attack Roll: +9, range 120 feet. Hit: 13 (3d8) Thunder damage. If the target is a Large or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('3e942641-7467-45ac-9d57-1683622358df'::uuid,'01990b86-4a7a-785c-b525-bc7cb0a0ffab'::uuid,'Create Whirlwind','Action','None','Create Whirlwind. The djinni conjures a whirlwind at a point it can see within 120 feet. The whirlwind fills a 20-foot-radius, 60-foot-high Cylinder centered on that point. The whirlwind lasts until the djinni''s Concentration on it ends. The djinni can move the whirlwind up to 20 feet at the start of each of its turns. Whenever the whirlwind enters a creature''s space or a creature enters the whirlwind, that creature is subjected to the following effect. Strength Saving Throw: DC 17 (a creature makes this save only once per turn, and the djinni is unaffected). Failure: While in the whirlwind, the target has the Restrained condition and moves with the whirlwind. At the start of each of its turns, the Restrained target takes 21 (6d6) Thunder damage. At the end of each of its turns, the target repeats the save, ending the effect on itself on a success.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('409e4d1b-f5e4-49db-9e0b-0a591ea99d9d'::uuid,'01990b86-4a7a-785c-b525-bc7cb0a0ffab'::uuid,'Multiattack','Action','None','Multiattack. The djinni makes three attacks, using Storm Blade or Storm Bolt in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('78fe8a0b-2b11-47d8-8e37-56cff358a84b'::uuid,'01990b86-4a7a-785c-b525-bc7cb0a0ffab'::uuid,'Storm Blade','Action','None','Storm Blade. Melee Attack Roll: +9, reach 5 feet. Hit: 12 (2d6 + 5) Slashing damage plus 7 (2d6) Lightning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('bd010eaa-0004-43fd-a7f9-3f889568f35f'::uuid,'01990b86-4a7a-785c-b525-bc7cb0a0ffab'::uuid,'Spellcasting','Action','None','Spellcasting. The djinni casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 17):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0fb917e9-3bfa-40a7-bbd4-e08903fa1c9c'::uuid,'01990b86-6ce9-7538-8b44-4c52bf74942d'::uuid,'Shape-Shift','Bonus','None','The doppelganger shape-shifts into a Medium or Small Humanoid, or it returns to its true form. Its game statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3547b228-e905-4a5d-8fa2-864270d0bac4'::uuid,'01990b86-6ce9-7538-8b44-4c52bf74942d'::uuid,'Unsettling Visage','Action','None','Wisdom Saving Throw: DC 12, each creature in a 15-foot Emanation originating from the doppelganger that can see the doppelganger. Failure: The target has the Frightened condition and repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.',NULL,NULL,NULL,NULL,NULL,6,false,NULL,NULL,NULL,NULL,NULL),
	 ('4b21eb25-88cd-4030-be08-214dd8916ab7'::uuid,'01990b86-6ce9-7538-8b44-4c52bf74942d'::uuid,'Slam','Action','Melee','Melee Attack Roll: +6 (with Advantage during the first round of each combat), reach 5 ft. Hit: 11 (2d6 + 4) Bludgeoning damage.',6,4,'d6',2,'Bludgeoning',NULL,false,NULL,'during the first round of each combat',NULL,NULL,NULL),
	 ('8dee08d6-e398-436b-85e1-8e6d2b6f0848'::uuid,'01990b86-6ce9-7538-8b44-4c52bf74942d'::uuid,'Read Thoughts','Action','None','The doppelganger casts Detect Thoughts, requiring no spell components and using Charisma as the spellcasting ability (spell save DC 12).',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('de85a72e-cd5d-457a-80bf-9abd6038eafa'::uuid,'01990b86-6ce9-7538-8b44-4c52bf74942d'::uuid,'Multiattack','Action','None','The doppelganger makes two Slam attacks and uses Unsettling Visage if available.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('076eae06-13b0-466d-af21-aca1aa1f3efb'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Terrifying Presence','Legendary','None','Wisdom Saving Throw: DC 19, each creature in a 30-foot Emanation originating from the dracolich. Failure: 11 (2d10) Psychic damage, and the target has the Frightened condition until the end of its next turn. Failure or Success: The dracolich can''t take this action again until the start of its next turn.',NULL,NULL,'d10',2,'Psychic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('428a5f28-3aad-4cd0-88cf-195cf30f663b'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Multiattack','Action','None','Multiattack. The dracolich makes three Rend attacks. It can replace one attack with a use of Spellcasting to cast Ray of Sickness (level 2 version).',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c1c93164-01d4-4d47-85af-1794c9eb5f71'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Spellcasting','Action','None','Spellcasting. The dracolich casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 19, +11 to hit with spell attacks):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d0f935a6-63be-41eb-bbaa-1f5f36de3480'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Sickening Ray','Legendary','Ranged','The dracolich uses Spellcasting to cast Ray of Sickness (level 2 version). The dracolich can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('e5887ec7-f210-4634-bfab-ccae6bbbe6a5'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +13, reach 10 ft. Hit: 18 (2d10 + 7) Slashing damage plus 4 (1d8) Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('eefb4f2b-1691-4984-9d09-af5c09a6985d'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Pounce','Legendary','Melee','The dracolich moves up to half its Speed, and it makes one Rend attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ef5b32b1-41db-46f9-8933-adb9c6b278d6'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Necrotic Breath (Recharge 5–6)','Action','None','Necrotic Breath (Recharge 5–6). Constitution Saving Throw: DC 20, each creature in a 60-foot Cone. Failure: 52 (8d12) Necrotic damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('4495471f-2fa2-4031-8ca6-f2575683055f'::uuid,'01990b86-baec-751a-b388-3457ac1a2f3c'::uuid,'Hooves','Action','Melee','Hit: 6 (1d4 + 4) Bludgeoning damage.',6,4,'d4',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('4eb6c5b7-68e9-4327-82d4-75d631a0631b'::uuid,'01990b86-d580-7cac-ad52-cb96572ae4c7'::uuid,'Multiattack','Action','None','Multiattack. The dragon makes three Bite attacks. It can replace one attack with a Tail attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('955c5524-0d6e-497a-8ced-c9e1807526ec'::uuid,'01990b86-d580-7cac-ad52-cb96572ae4c7'::uuid,'Tail','Action','None','Tail. Melee Attack Roll: +13, reach 15 ft. Hit: 18 (2d10 + 7) Bludgeoning damage. If the target is a Huge or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('983daa04-f92d-4426-9f73-6e2d2b591028'::uuid,'01990b86-d580-7cac-ad52-cb96572ae4c7'::uuid,'Steam Breath (Recharge 5–6)','Action','None','Steam Breath (Recharge 5–6). Constitution Saving Throw: DC 19, each creature in a 60-foot Cone. Failure: 56 (16d6) Fire damage. Success: Half damage. Failure or Success: Being underwater doesn''t grant Resistance to this Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e5f8fa7b-abdc-4887-9399-b399cf207990'::uuid,'01990b86-d580-7cac-ad52-cb96572ae4c7'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +13, reach 15 ft. Hit: 23 (3d10 + 7) Piercing damage plus 7 (2d6) Fire damage. Being underwater doesn''t grant Resistance to this Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0fe402ef-ce26-4953-a256-bea0869cee58'::uuid,'01990b86-e2c8-7aca-9f42-29d2e13b16e4'::uuid,'Rend','Action','Melee','Melee Attack Roll: +3, reach 5 ft. Hit: 4 (1d6 + 1) Slashing damage.',3,1,'d6',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('787e7ddb-aa46-4426-8bde-c7a0e131c3bd'::uuid,'01990b86-e2c8-7aca-9f42-29d2e13b16e4'::uuid,'Fetid Cloud','Action','None','Constitution Saving Throw: DC 11, each creature in a 10-foot Emanation originating from the dretch. Failure: The target has the Poisoned condition until the end of its next turn. While Poisoned, the creature can take either an action or a Bonus Action on its turn, not both, and it can''t take Reactions.',NULL,NULL,NULL,NULL,NULL,1,false,NULL,NULL,NULL,NULL,NULL);
