	 ('00dbf278-45e9-4e6e-b03c-ba9ea7907785'::uuid,'01990b87-0835-7ab6-b720-c36feed0a1b6'::uuid,'Magic of the Spider Queen','Bonus','None','The drider casts Darkness, Faerie Fire, or Web, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 14).',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
