	 ('b296eb96-dce5-44be-bac8-8ab711d677bd'::uuid,'01990b87-1c3b-77ac-ad69-00351743c641'::uuid,'Multiattack','Action','None','Multiattack. The druid makes two attacks, using Vine Staff or Verdant Wisp in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0942b346-0f36-48ea-8624-a1415076ada6'::uuid,'01990b87-4af2-7c1c-84bf-6484a78b1613'::uuid,'Thorn Burst','Action','None','Thorn Burst. Ranged Attack Roll: +6, range 60 ft. Hit: 7 (1d6 + 4) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('179c512a-d3bb-455d-aaa2-b29815f274a1'::uuid,'01990b87-4af2-7c1c-84bf-6484a78b1613'::uuid,'Multiattack','Action','None','Multiattack. The dryad makes one Vine Lash or Thorn Burst attack, and it can use Spellcasting to cast Charm Monster.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
