	 ('898fee6c-61f7-4806-a766-dab1ec2f0967'::uuid,'01990b87-6767-794b-a18d-241931c6b713'::uuid,'Sleep','Action','None','The mephit casts the Sleep spell, requiring no spell components and using Charisma as the spellcasting ability (spell save DC 10).',NULL,NULL,NULL,NULL,NULL,1,false,NULL,NULL,NULL,NULL,NULL),
	 ('fa1a8956-6ac6-414c-9cf0-2c7f81d92a7b'::uuid,'01990b87-6767-794b-a18d-241931c6b713'::uuid,'Blinding Breath','Action','None','Failure: The target has the Blinded condition until the end of the mephit''s next turn.',NULL,NULL,NULL,NULL,NULL,6,false,NULL,NULL,NULL,NULL,NULL),
