	 ('1394d28b-788e-4bae-821f-142dbb817eeb'::uuid,'01990b87-8e0b-7f19-ad80-21a95b744504'::uuid,'Slam','Action','None','Slam. Melee Attack Roll: +8, reach 10 ft. Hit: 14 (2d8 + 5) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
