	 ('199a6b17-455a-4bac-b23a-7a58a2a7b191'::uuid,'01990b87-b9cc-7d5f-b567-769c5919692e'::uuid,'Heated Blade','Action','None','Heated Blade. Melee Attack Roll: +10, reach 5 ft. Hit: 13 (2d6 + 6) Slashing damage plus 13 (2d12) Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('885762ce-e0b8-4295-83c0-732f47e5fd85'::uuid,'01990b87-b9cc-7d5f-b567-769c5919692e'::uuid,'Hurl Flame','Action','None','Hurl Flame. Ranged Attack Roll: +8, range 120 ft. Hit: 24 (7d6) Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
