	 ('84c0d6b6-8b57-4985-8413-b397e56fc184'::uuid,'01990b87-ea92-773a-b5fc-85622295d11b'::uuid,'Elemental Claw','Action','None','Elemental Claw. Ranged Attack Roll: +7, range 120 ft. Hit: 22 (4d10) damage of a type chosen by the cultist: Acid, Cold, Fire, Lightning, or Thunder. If the target is a Medium or smaller creature, the cultist moves the target up to 10 feet straight toward or away from itself.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d267488d-0517-423e-ac85-f95a32761461'::uuid,'01990b87-ea92-773a-b5fc-85622295d11b'::uuid,'Multiattack','Action','None','Multiattack. The cultist makes three attacks, using Elemental Flail or Elemental Claw in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('eac9a91f-2b0b-451f-b539-325994e5cb0c'::uuid,'01990b87-ea92-773a-b5fc-85622295d11b'::uuid,'Elemental Absorption','Reaction','None','Trigger: The cultist takes Acid, Cold, Fire, Lightning, or Thunder damage. Response: The cultist gives itself Resistance to that instance of damage and gains 10 Temporary Hit Points.',NULL,NULL,NULL,NULL,NULL,1,false,'The cultist takes Acid, Cold, Fire, Lightning, or Thunder damage.',NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('14d4899c-82f4-45f2-aae5-70816fdc97e9'::uuid,'01990b87-fb2c-7d05-a534-a523438590ed'::uuid,'Trample','Bonus','None','Trample. Dexterity Saving Throw: DC 16, one creature within 5 feet that has the Prone condition. Failure: 17 (2d10 + 6) Bludgeoning damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8dc49c37-2a00-476b-a0cf-be96bc58b911'::uuid,'01990b87-fb2c-7d05-a534-a523438590ed'::uuid,'Multiattack','Action','None','The elephant makes two Gore attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('dd13124f-36c6-4882-8e07-c27b30740e16'::uuid,'01990b87-fb2c-7d05-a534-a523438590ed'::uuid,'Gore','Action','Melee','Melee Attack Roll: +8, reach 5 ft. Hit: 15 (2d8 + 6) Piercing damage. If the target is a Huge or smaller creature and the elephant moved 20+ feet straight toward it immediately before the hit, the target has the Prone condition.',8,6,'d8',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('efc996de-04dd-431a-a1f1-197b4a07051b'::uuid,'01990b88-0695-7c32-8632-b3e6866e0e39'::uuid,'Ram','Action','Melee','Hit: 6 (1d6 + 3) Bludgeoning damage. If the elk moved at least 20 feet straight toward the target immediately before the hit, the target takes an extra 3 (1d6) Bludgeoning damage and, if it is Huge or smaller, has the Prone condition.',5,3,'d6',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('06578479-b6ca-4704-bbf0-7158de76752e'::uuid,'01990b88-3b22-7f80-9ecd-18b80e07b3dd'::uuid,'Shockwave of Glory','Legendary','None','Constitution Saving Throw: DC 23, each creature in a 30-foot Emanation originating from the empyrean. Failure: 27 (6d8) Force damage, and the target has the Prone condition. Success: Half damage only. Failure or Success: The empyrean can''t take this action again until the start of its next turn.',NULL,NULL,'d8',6,'Force',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('18683a5b-627d-433c-9feb-0e1525b9b4af'::uuid,'01990b88-3b22-7f80-9ecd-18b80e07b3dd'::uuid,'Divine Ray','Action','None','Divine Ray. Ranged Attack Roll: +15, range 600 ft. Hit: 35 (6d8+8) Necrotic or Radiant damage (empyrean''s choice).',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('22f6c473-8de9-4400-acf4-00a45d3612bb'::uuid,'01990b88-3b22-7f80-9ecd-18b80e07b3dd'::uuid,'Multiattack','Action','None','Multiattack. The empyrean makes two attacks, using Sacred Weapon or Divine Ray in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a3923339-7c57-4b51-9271-a06622b85199'::uuid,'01990b88-3b22-7f80-9ecd-18b80e07b3dd'::uuid,'Sacred Weapon','Action','None','Sacred Weapon. Melee Attack Roll: +17, reach 10 ft. Hit: 31 (6d6+10) Force damage, and the target has the Stunned condition until the start of the empyrean''s next turn. The target can choose not to be Stunned, in which case it takes an extra 21 Force damage that bypasses Resistance or Immunity.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ba553aaf-ad5b-48b9-8f36-d7fb1df4f8b6'::uuid,'01990b88-3b22-7f80-9ecd-18b80e07b3dd'::uuid,'Spellcasting','Action','None','Spellcasting. The empyrean casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 23):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ca1da6bd-9b49-4c02-96fd-f39cd50918dd'::uuid,'01990b88-3b22-7f80-9ecd-18b80e07b3dd'::uuid,'Smite','Legendary','None','The empyrean makes one Divine Ray attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('fb762c2b-6cce-4d8a-a047-44c973d24c0e'::uuid,'01990b88-3b22-7f80-9ecd-18b80e07b3dd'::uuid,'Bolster','Legendary','None','The empyrean gains 10 Temporary Hit Points, and the empyrean and each ally within 30 feet of it gain Advantage on D20 Tests until the end of the empyrean''s next turn. The empyrean can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('193504bc-dc90-403b-b469-efb89766e78c'::uuid,'01990b88-5c57-7d6c-ab15-6ca99e6111fa'::uuid,'Healing Word','Bonus','None','The empyrean casts Healing Word, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,1,false,NULL,NULL,NULL,NULL,NULL),
	 ('19c1b87c-d2f8-4985-88a2-53205c6217ed'::uuid,'01990b88-5c57-7d6c-ab15-6ca99e6111fa'::uuid,'Spellcasting','Action','None','Spellcasting. The empyrean casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f2022db9-987c-487b-95d7-24836fd27cff'::uuid,'01990b92-f546-7a21-bba5-d5097eb1eacb'::uuid,'Misty Step','Bonus','None','The mage casts Misty Step, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,3,false,NULL,NULL,NULL,NULL,NULL),
	 ('332ce6cd-9f1e-42ff-9642-4b6b1b36ace9'::uuid,'01990b88-5c57-7d6c-ab15-6ca99e6111fa'::uuid,'Otherworldly Strike','Action','None','Otherworldly Strike. Melee or Ranged Attack Roll: +5. reach 5 ft. or range 30 ft. Hit: 7 (1d8+3) Necrotic or Radiant damage (empyrean''s choice).',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('3bbbf6d5-0f39-4fb0-a73d-e0a0857c2b77'::uuid,'01990b88-8404-7707-8fe6-ed71698b280e'::uuid,'Multiattack','Action','None','The erinyes makes three Withering Sword attacks and can use Entangling Rope.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('73ed7efe-4d2f-423d-a526-c1b44e4fc6ba'::uuid,'01990b88-8404-7707-8fe6-ed71698b280e'::uuid,'Parry','Reaction','None','The erinyes adds 4 to its AC against the triggering attack, possibly causing it to miss.',NULL,NULL,NULL,NULL,NULL,NULL,false,'The erinyes is hit by a melee attack roll while holding a weapon.',NULL,NULL,NULL,NULL),
	 ('b0930afc-580e-42c7-aefc-bba273e71f17'::uuid,'01990b88-8404-7707-8fe6-ed71698b280e'::uuid,'Entangling Rope','Action','None','Strength Saving Throw: DC 16, one creature the erinyes can see within 120 feet. Failure: 14 (4d6) Force damage, and the target has the Restrained condition until the rope is destroyed, the erinyes uses a Bonus Action to release the target, or the erinyes uses Entangling Rope again.',NULL,NULL,'d6',4,'Force',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('f3482e97-2e33-4bde-bc62-38d6c6e0ba97'::uuid,'01990b88-8404-7707-8fe6-ed71698b280e'::uuid,'Withering Sword','Action','Melee','Melee Attack Roll: +8, reach 5 ft. Hit: 13 (2d8 + 4) Slashing damage plus 11 (2d10) Necrotic damage.',8,4,'d8',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('1247540d-5f8b-43b6-a351-91ac136e26db'::uuid,'01990b88-aa7b-7878-91c3-24e32b50f8e9'::uuid,'Reel','Bonus','None','The ettercap pulls one creature within 30 feet of itself that is Restrained by its Web Strand up to 25 feet straight toward itself.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('1b5abe5c-3182-4339-92c7-74d639d6b7eb'::uuid,'01990b88-aa7b-7878-91c3-24e32b50f8e9'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage plus 2 (1d4) Poison damage, and the target has the Poisoned condition until the start of the ettercap''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('33b2d688-6a98-44ef-9531-8b39c16064a2'::uuid,'01990b88-aa7b-7878-91c3-24e32b50f8e9'::uuid,'Web Strand (Recharge 5–6)','Action','None','Web Strand (Recharge 5–6). Dexterity Saving Throw: DC 12, one Large or smaller creature the ettercap can see within 30 feet. Failure: The target has the Restrained condition until the web is destroyed (AC 10; HP 5; Vulnerability to Fire damage; Immunity to Bludgeoning, Poison, and Psychic damage).',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('75ad46b2-6dd1-4aa0-a53c-a0ca87400a82'::uuid,'01990b88-aa7b-7878-91c3-24e32b50f8e9'::uuid,'Multiattack','Action','None','Multiattack. The ettercap makes one Bite attack and one Claw attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('76331253-9969-427c-91df-658f9ac184ad'::uuid,'01990b88-aa7b-7878-91c3-24e32b50f8e9'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +4, reach 5 ft. Hit: 7 (2d4 + 2) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7a547bfc-a460-4af4-a59e-e6623ae4079d'::uuid,'01990b88-beee-70e3-9a11-35ce058d68be'::uuid,'Battleaxe','Action','None','Battleaxe. Melee Attack Roll: +7, reach 5 ft. Hit: 14 (2d8 + 5) Slashing damage. If the target is a Large or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('87a9ce85-6df6-481d-bf01-db252bc7da77'::uuid,'01990b88-beee-70e3-9a11-35ce058d68be'::uuid,'Morningstar','Action','None','Morningstar. Melee Attack Roll: +7, reach 5 ft. Hit: 14 (2d8 + 5) Piercing damage, and the target has Disadvantage on the next attack roll it makes before the end of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('edc5c2fe-6a5a-40f6-9aff-c2e534faab3a'::uuid,'01990b88-beee-70e3-9a11-35ce058d68be'::uuid,'Multiattack','Action','None','Multiattack. The ettin makes one Battleaxe attack and one Morningstar attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a89d9660-1889-4a35-995f-bc6375047c99'::uuid,'01990b88-eaff-7fce-88c0-89be6fc5901a'::uuid,'Pact Axe','Action','Melee','Melee Attack Roll: +7, reach 5 ft. Hit: 10 (1d12 + 4) Slashing damage plus 13 (3d8) Fire damage.',7,4,'d12',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c4237d3d-33a1-43d7-a4a1-2a585ab6c4ab'::uuid,'01990b88-eaff-7fce-88c0-89be6fc5901a'::uuid,'Hellish Rebuke','Reaction','None','The cultist casts Hellish Rebuke in response to that spell''s trigger, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,NULL,false,'in response to that spell''s trigger',NULL,NULL,NULL,NULL),
	 ('dceb4ec4-32a3-4c35-b085-d49016da34f6'::uuid,'01990b88-eaff-7fce-88c0-89be6fc5901a'::uuid,'Spellcasting','Action','None','The cultist casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 15, +7 to hit with spell attacks):',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
