	 ('f1ea6afe-ef1e-4e99-8279-adb81caa9548'::uuid,'01990b88-eaff-7fce-88c0-89be6fc5901a'::uuid,'Multiattack','Action','Melee','The cultist makes three Pact Axe attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
