	 ('5f4846ce-f2fb-4f69-ac18-8414d518a2b6'::uuid,'01990b89-0b5c-7bff-8495-099b3ceb1e8a'::uuid,'Multiattack','Action','None','Multiattack. The elemental makes two Burn attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('01775f22-25f7-434f-9448-deac0ecea564'::uuid,'01990b89-2302-704e-afed-c32fecdbfbd9'::uuid,'Flame Sword','Action','None','Flame Sword. Melee Attack Roll: +11, reach 10 ft. Hit: 21 (4d6 + 7) Slashing damage plus 10 (3d6) Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('4202c19b-96bd-44ab-a95b-47583fdeb24b'::uuid,'01990b89-2302-704e-afed-c32fecdbfbd9'::uuid,'Multiattack','Action','None','Multiattack. The giant makes two attacks, using Flame Sword or Hammer Throw in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('956aba83-db44-44d1-81e4-0aadeee44b55'::uuid,'01990b89-2302-704e-afed-c32fecdbfbd9'::uuid,'Hammer Throw','Action','None','Hammer Throw. Ranged Attack Roll: +11, range 60/240 ft. Hit: 23 (3d10 + 7) Bludgeoning damage plus 4 (1d8) Fire damage, and the target is pushed up to 15 feet straight away from the giant and has Disadvantage on the next attack roll it makes before the end of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8fef8f79-dfea-431e-80cb-b052d6af731c'::uuid,'01990b89-4e73-72ac-aa87-ff8511543a7b'::uuid,'Multiattack','Action','None','Multiattack. The skeleton makes two attacks, using Flame Scepter or Hurl Flame in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ab89491b-d9a6-4343-af20-ad7c72fb1ad4'::uuid,'01990b89-4e73-72ac-aa87-ff8511543a7b'::uuid,'Flame Scepter','Action','None','Flame Scepter. Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Bludgeoning damage plus 3 (1d6) Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ea20196a-0bf7-4970-900e-c9c6882d9495'::uuid,'01990b89-4e73-72ac-aa87-ff8511543a7b'::uuid,'Hurl Flame','Action','None','Hurl Flame. Ranged Attack Roll: +4, range 60 ft. Hit: 7 (1d10 + 2) Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('6fa2a432-1305-4c25-8656-10f19874ae2e'::uuid,'01990b89-7002-7e74-ba06-44c5687a3ddd'::uuid,'Multiattack','Action','None','Multiattack. The golem makes two Slam attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('d84678ef-ff2a-4f62-9c4a-279b9a717a2c'::uuid,'01990b89-7002-7e74-ba06-44c5687a3ddd'::uuid,'Slam','Action','None','Slam. Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8 + 4) Bludgeoning damage plus 4 (1d8) Lightning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('6cf23dd4-8cf5-43dc-8bec-49643e3c8fa7'::uuid,'01990b89-905c-7d0e-bf9b-a16b8172a90b'::uuid,'Stench Spray (1/Day)','Action','None','Stench Spray (1/Day). Dexterity Saving Throw: DC 10, one creature the flumph can see within 15 feet. Failure: The target is coated in a foul-smelling liquid, exudes a stench for 1d4 hours, and has the Poisoned condition while the stench lasts. Other creatures have the Poisoned condition while in a 5-foot Emanation originating from the coated target. The target can remove the stench on itself if it bathes during a Short or Long Rest.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e14b6a29-a6e2-433d-ae96-325bd667db3f'::uuid,'01990b89-905c-7d0e-bf9b-a16b8172a90b'::uuid,'Tentacle','Action','None','Tentacle. Melee Attack Roll: +4, reach 5 feet. Hit: 4 (1d4 + 2) Acid damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c90e3d40-073a-4d32-9931-7ffe2105bc16'::uuid,'01990b89-9e14-7a98-9021-d30e64a024d3'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 1 Piercing damage plus 5 (2d4) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a3941a76-d830-4029-b221-fb713a05a89f'::uuid,'01990b89-afcc-7f8b-bffd-68c0b2bbd4fd'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +3, reach 5 ft. Hit: 1 Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('4b7b8820-73f0-48e8-b4c7-715254f2797a'::uuid,'01990b89-cc02-773b-8e7d-ec0fac681ce4'::uuid,'Frost Axe','Action','Melee','Melee Attack Roll: +9, reach 10 ft. Hit: 19 (2d12 + 6) Slashing damage plus 9 (2d8) Cold damage.',9,6,'d12',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('6b3512fd-3862-4155-b874-546256d3083b'::uuid,'01990b89-cc02-773b-8e7d-ec0fac681ce4'::uuid,'Great Bow','Action','Ranged','Ranged Attack Roll: +9, range 150/600 ft. Hit: 17 (2d10 + 6) Piercing damage plus 7 (2d6) Cold damage, and the target''s Speed decreases by 10 feet until the end of its next turn.',9,6,'d10',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('bea7090d-7a3d-4c81-98bd-5b6e3449784d'::uuid,'01990b89-cc02-773b-8e7d-ec0fac681ce4'::uuid,'Multiattack','Action','None','The giant makes two attacks, using Frost Axe or Great Bow in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('d8600a04-b3ea-4d9e-8bd4-588c415c0ca3'::uuid,'01990b89-cc02-773b-8e7d-ec0fac681ce4'::uuid,'War Cry','Bonus','None','The giant or one creature of its choice that can see or hear it gains 16 (2d10 + 5) Temporary Hit Points and has Advantage on attack rolls until the start of the giant''s next turn.',NULL,NULL,'d10',2,NULL,1,false,NULL,NULL,NULL,NULL,NULL),
	 ('3ab19208-3e67-4c2a-b85e-ae8520f2744c'::uuid,'01990b89-e1e8-7d85-a572-f717ecbf551e'::uuid,'Claw','Action','Melee','Melee Attack Roll: +4, reach 5 ft. Hit: 7 (2d4+2) Slashing damage.',4,2,'d4',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('77e02010-e2e7-4a91-97a9-9f54f5e8f325'::uuid,'01990b89-e1e8-7d85-a572-f717ecbf551e'::uuid,'Multiattack','Action','None','The gargoyle makes two Claw attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('4f4899c6-744c-47eb-92d2-da1e4ccad930'::uuid,'01990b8a-0abd-725b-835e-43eefe91db05'::uuid,'Engulf','Action','None','The cube moves up to its Speed without provoking Opportunity Attacks. The cube can move through the spaces of Large or smaller creatures if it has room inside itself to contain them (see the Ooze Cube trait). Dexterity Saving Throw: DC 12, each creature whose space the cube enters for the first time during this move. Failure: 10 (3d6) Acid damage, and the target is engulfed. An engulfed target is suffocating, can''t cast spells with a Verbal component, has the Restrained condition, and takes 10 (3d6) Acid damage at the start of each of the cube''s turns. When the cube moves, the engulfed target moves with it. An engulfed target can try to escape by taking an action to make a DC 12 Strength (Athletics) check. On a successful check, the target escapes and enters the nearest unoccupied space. Success: Half damage, and the target moves to an unoccupied space within 5 feet of the cube. If there is no unoccupied space, the target fails the save instead.',NULL,NULL,'d6',3,'Acid',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5748452f-04f9-42d6-9920-cad5219e42d4'::uuid,'01990b8a-0abd-725b-835e-43eefe91db05'::uuid,'Pseudopod','Action','Melee','Melee Attack. Hit: 12 (3d6+2) Acid damage.',4,2,'d6',3,'Acid',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5643ea55-7a01-4e08-bd65-ce48874213a3'::uuid,'01990b8a-25f7-7f90-82ef-56c581b854da'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage. If the target is a non-Undead creature, it is subjected to the following effect. Constitution Saving Throw: DC 10. Failure: The target has the Paralyzed condition until the end of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7a2652b2-0285-4e46-9955-3be9e16e1208'::uuid,'01990b8a-25f7-7f90-82ef-56c581b854da'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Piercing damage plus 9 (2d8) Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('1bbc7ddb-9f73-4ba1-8872-2020b0ddd831'::uuid,'01990b8a-5613-7d52-980e-7b704db2fa2a'::uuid,'Horrific Visage','Action','None','Wisdom Saving Throw: DC 13, each creature in a 60-foot Cone that can see the ghost and isn''t an Undead. Failure: 10 (2d6 + 3) Psychic damage, and the target has the Frightened condition until the start of the ghost''s next turn. Success: The target is immune to this ghost''s Horrific Visage for 24 hours.',NULL,NULL,'d6',2,'Psychic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3fb23b9e-ec31-4509-bb9f-33058a244885'::uuid,'01990b8a-5613-7d52-980e-7b704db2fa2a'::uuid,'Withering Touch','Action','Melee','Melee Attack Roll: +5, reach 5 ft. Hit: 19 (3d10 + 3) Necrotic damage.',5,3,'d10',3,'Necrotic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5cb4e136-1d37-4a23-846f-07944a771388'::uuid,'01990b8a-5613-7d52-980e-7b704db2fa2a'::uuid,'Etherealness','Action','None','The ghost casts the Etherealness spell, requiring no spell components and using Charisma as the spellcasting ability. The ghost is visible on the Material Plane while on the Border Ethereal and vice versa, but it can''t affect or be affected by anything on the other plane.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c6241eb5-2a6a-417b-930e-731c92bfb519'::uuid,'01990b8a-5613-7d52-980e-7b704db2fa2a'::uuid,'Multiattack','Action','None','The ghost makes two Withering Touch attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('dac26c18-d790-4e18-b215-0fad0ebc11b6'::uuid,'01990b8a-5613-7d52-980e-7b704db2fa2a'::uuid,'Possession','Action','None','Charisma Saving Throw: DC 13, one Humanoid the ghost can see within 5 feet. Failure: The target is possessed by the ghost; the ghost disappears, and the target has the Incapacitated condition and loses control of its body. The ghost now controls the body, but the target retains awareness. The ghost can''t be targeted by any attack, spell, or other effect, except ones that specifically target Undead. The ghost''s game statistics are the same, except it uses the possessed target''s Speed, as well as the target''s Strength, Dexterity, and Constitution modifiers. The possession lasts until the body drops to 0 Hit Points or the ghost leaves as a Bonus Action. When the possession ends, the ghost appears in an unoccupied space within 5 feet of the target, and the target is immune to this ghost''s Possession for 24 hours. Success: The target is immune to this ghost''s Possession for 24 hours.',NULL,NULL,NULL,NULL,NULL,6,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('2194154f-955d-495e-8b5e-85737659f867'::uuid,'01990b8a-731a-7d82-a6a2-244770136aeb'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Slashing damage. If the target is a creature that isn''t an Undead or elf, it is subjected to the following effect. Constitution Saving Throw: DC 10. Failure: The target has the Paralyzed condition until the end of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d13d5001-571b-4e06-9a39-7d8e8fcef33f'::uuid,'01990b8a-731a-7d82-a6a2-244770136aeb'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage plus 3 (1d6) Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('faf9bd0a-5403-4176-9a99-b1129b900db8'::uuid,'01990b8a-731a-7d82-a6a2-244770136aeb'::uuid,'Multiattack','Action','None','Multiattack. The ghoul makes two Bite attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('031045cc-8420-4cbc-9580-f50e9b9d088c'::uuid,'01990b8a-8d35-72d8-9650-d5dacb0691f5'::uuid,'Boulder Toss (Recharge 6)','Action','None','Boulder Toss (Recharge 6). The ape hurls a boulder at a point it can see within 90 feet. Dexterity Saving Throw: DC 17, each creature in a 5-foot-radius Sphere centered on that point. Failure: 24 (7d6) Bludgeoning damage. If the target is a Large or smaller creature, it has the Prone condition. Success: Half damage only.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8f0fbe82-aae5-4e4a-a763-7c2a771556b0'::uuid,'01990b8a-8d35-72d8-9650-d5dacb0691f5'::uuid,'Fist','Action','None','Fist. Melee Attack Roll: +9, reach 10 ft. Hit: 22 (3d10 + 6) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a25c0c6a-7cd6-416e-bb89-48013cec4359'::uuid,'01990b8a-8d35-72d8-9650-d5dacb0691f5'::uuid,'Multiattack','Action','None','Multiattack. The ape makes two Fist attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e7064e6f-4317-4ee4-80bd-75e64ffd048a'::uuid,'01990b8a-8d35-72d8-9650-d5dacb0691f5'::uuid,'Leap','Bonus','None','The ape jumps up to 30 feet by spending 10 feet of movement.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('9238fdbd-a9e3-4450-bf56-4d0128ef60f6'::uuid,'01990b8a-95e8-74f1-9696-fdacb3c1bef3'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +3, reach 5 ft. Hit: 6 (2d4 + 1) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('393f4124-696c-4851-8856-111846dafa41'::uuid,'01990b8a-9b78-71e3-9665-c9bd8e175c6f'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('beb4d5c2-1fe3-49e9-9b2d-0daf88644cea'::uuid,'01990b8a-b210-78bb-bae8-1c38b3fba28e'::uuid,'Gore','Action','None','Gore. Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Piercing damage. If the target is a Large or smaller creature and the boar moved 20+ feet straight toward it immediately before the hit, the target takes an extra 7 (2d6) Piercing damage and has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
