	 ('488374a1-d049-458b-8b70-6618b3e048a4'::uuid,'01990b8a-d417-74a0-9ea5-c548485ccaa1'::uuid,'Constrict','Action','None','Strength Saving Throw: DC 14, one Large or smaller creature the snake can see within 10 feet. Failure: 13 (2d8 + 4) Bludgeoning damage, and the target has the Grappled condition (escape DC 14).',NULL,4,'d8',2,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b117df8a-60e8-4e57-ad21-1f679b0bda34'::uuid,'01990b8a-d417-74a0-9ea5-c548485ccaa1'::uuid,'Bite','Action','Melee','Melee Attack Roll: +6, reach 10 ft. Hit: 11 (2d6 + 4) Piercing damage.',6,4,'d6',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ce9036b9-e7f0-46c1-bb29-48e0e6cbae9d'::uuid,'01990b8a-e16f-7168-b140-c7efc3359d3b'::uuid,'Claw','Action','Melee','Hit: 4 (1d6 + 1) Bludgeoning damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 11) from one of two claws.',3,1,'d6',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5c8a9741-590a-4dbf-986c-270892c27432'::uuid,'01990b8a-f967-7355-b0f1-3d3afd0d9d5d'::uuid,'Tail','Action','None','Tail. Melee Attack Roll: +8, reach 10 ft. Hit: 18 (3d8 + 5) Bludgeoning damage. If the target is a Large or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('9340ee2f-f7ad-49c0-bef5-145a9f40e81a'::uuid,'01990b8a-f967-7355-b0f1-3d3afd0d9d5d'::uuid,'Multiattack','Action','None','Multiattack. The crocodile makes one Bite attack and one Tail attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e12b865d-b0fd-45c1-bf51-51293fd9df33'::uuid,'01990b8a-f967-7355-b0f1-3d3afd0d9d5d'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +8, reach 5 ft. Hit: 21 (3d10 + 5) Piercing damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 15). While Grappled, the target has the Restrained condition and can''t be targeted by the crocodile''s Tail.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a064c49f-830b-4392-8d17-d088de303ce7'::uuid,'01990b8b-09a6-7e92-a00e-524971f92a52'::uuid,'Rend','Action','Melee','Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4 + 3) Slashing damage plus 3 (1d6) Radiant damage.',5,NULL,'d4',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ab78a05b-0cbe-4b00-a060-10a884bc5bb7'::uuid,'01990b8b-09a6-7e92-a00e-524971f92a52'::uuid,'Multiattack','Action','None','The eagle makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('ac909700-72fd-48d0-932a-394d09cd9a19'::uuid,'01990b8b-158b-74f5-b03c-a58e29cf540d'::uuid,'Ram','Action','None','Ram. Melee Attack Roll: +6, reach 10 ft. Hit: 11 (2d6 + 4) Bludgeoning damage plus 5 (2d4) Radiant damage. If the target is a Huge or smaller creature and the elk moved 20+ feet straight toward it immediately before the hit, the target takes an extra 5 (2d4) Bludgeoning damage and has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ab7ef7a1-7303-4c0b-aa46-aaa1c394d70c'::uuid,'01990b8b-2ced-79cb-ae4a-ef2b82e713db'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +1, reach 5 ft. Hit: 1 Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d8c80b1b-398c-431c-903a-f339de8d34e5'::uuid,'01990b8b-51c4-7e64-a091-e018d08d0b1e'::uuid,'Swallow','Action','None','The frog swallows a Small or smaller target it is grappling. While swallowed, the target isn''t Grappled but has the Blinded and Restrained conditions, and it has Total Cover against attacks and other effects outside the frog. While swallowing the target, the frog can''t use Bite, and if the frog dies, the swallowed target is no longer Restrained and can escape from the corpse using 5 feet of movement, exiting with the Prone condition. At the end of the frog''s next turn, the swallowed target takes 5 (2d4) Acid damage. If that damage doesn''t kill it, the frog disgorges it, causing it to exit Prone.',NULL,NULL,'d4',2,'Acid',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('f5131e75-a5d7-4ed5-b773-05c2fee03011'::uuid,'01990b8b-51c4-7e64-a091-e018d08d0b1e'::uuid,'Bite','Action','Melee','Hit: 5 (1d6 + 2) Piercing damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 11).',3,2,'d6',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b0d9dbe0-6e59-4a7c-9432-4b5988b4ee2a'::uuid,'01990b8b-584a-74df-9c8b-b395eb1df1d9'::uuid,'Ram','Action','Melee','Hit: 6 (1d6 + 3) Bludgeoning damage. If the target is a Large or smaller creature and the goat moved 20+ feet straight toward it immediately before the hit, the target takes an extra 5 (2d4) Bludgeoning damage and has the Prone condition.',5,3,'d6',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('890d2c6c-1e20-47f2-a486-815dd7326b32'::uuid,'01990b8b-68c4-75da-bdfd-0e91a3417e93'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a8315cca-22c0-4991-9e16-e048acf40095'::uuid,'01990b8b-68c4-75da-bdfd-0e91a3417e93'::uuid,'Rampage','Bonus','Melee','Immediately after dealing damage to a creature that was already Bloodied, the hyena can move up to half its Speed, and it makes one Bite attack.',NULL,NULL,NULL,NULL,NULL,1,false,NULL,NULL,NULL,NULL,NULL),
	 ('d2c468fe-2f6f-48c6-80ac-ac4cf513c9ae'::uuid,'01990b8b-7739-7ab9-81c0-8544d5f95137'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 6 (1d8 + 2) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('247a95f3-1be6-42f0-b3b4-59dec90b4b12'::uuid,'01990b8b-901f-7c6c-b9c1-81c82f45aeaa'::uuid,'Ink Cloud','Reaction','None','The octopus releases ink that fills a 10-foot Cube centered on itself, and the octopus moves up to its Swim Speed. The Cube is Heavily Obscured for 1 minute or until a strong current or similar effect disperses the ink.',NULL,NULL,NULL,NULL,NULL,1,false,'The octopus takes damage while underwater.',NULL,NULL,NULL,NULL),
	 ('329a506e-a776-4633-852b-3b59ef7ca8cd'::uuid,'01990b8b-901f-7c6c-b9c1-81c82f45aeaa'::uuid,'Tentacles','Action','Melee','Hit: 10 (2d6 + 3) Bludgeoning damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 13) from all eight tentacles. While Grappled, the target has the Restrained condition.',5,3,'d6',2,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL);
