	 ('ee724b28-428f-4d45-8a78-2fdbe08fb451'::uuid,'01990b8b-dc3c-7980-bc5c-85a936c537b6'::uuid,'Sting','Action','None','Sting. Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Piercing damage plus 11 (2d10) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('266e1077-f299-4bbc-a3ec-953c0753c6f3'::uuid,'01990b8c-0720-7c91-a79a-0ee072be9cab'::uuid,'Bubble Dash','Bonus','None','While underwater, the seahorse moves up to half its Swim Speed without provoking Opportunity Attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('af4fb558-faae-45d9-be80-1c274583be91'::uuid,'01990b8c-0720-7c91-a79a-0ee072be9cab'::uuid,'Ram','Action','Melee','Hit: 9 (2d6 + 2) Bludgeoning damage, or 11 (2d8 + 2) Bludgeoning damage if the seahorse moved 20+ feet straight toward the target immediately before the hit.',4,2,'d6',2,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5f9ffec5-d07e-4373-99e8-b5b6dfd4a89d'::uuid,'01990b8c-1a79-70d9-8b44-9ccb1bb8fd2c'::uuid,'Bite','Action','Melee','Melee Attack Roll: +9 (with Advantage if the target doesn''t have all its Hit Points), reach 5 ft. Hit: 22 (3d10 + 6) Piercing damage.',9,6,'d10',3,'Piercing',NULL,false,NULL,'if the target doesn''t have all its Hit Points',NULL,NULL,NULL),
	 ('c80a13a9-1829-468e-b946-ed4f7672656b'::uuid,'01990b8c-1a79-70d9-8b44-9ccb1bb8fd2c'::uuid,'Multiattack','Action','Melee','The shark makes two Bite attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('c5d8b211-12f7-47b9-974f-24b9529784dc'::uuid,'01990b8c-2f60-70e1-b4ff-998cc2f10495'::uuid,'Web (Recharge 5–6)','Action','None','Web (Recharge 5–6). Dexterity Saving Throw: DC 13, one creature the spider can see within 60 feet. Failure: The target has the Restrained condition until the web is destroyed (AC 10; HP 5; Vulnerability to Fire damage; Immunity to Poison and Psychic damage).',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('cd9735ec-33d3-4730-841b-ed51304d8f4e'::uuid,'01990b8c-2f60-70e1-b4ff-998cc2f10495'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Piercing damage plus 7 (2d6) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8eeef346-b4db-4820-93b2-4a05bfafb487'::uuid,'01990b8c-5715-76de-b2d5-89d34398f6ba'::uuid,'Bite','Action','Melee','Melee Attack Roll: +9, reach 5 ft. Hit: 28 (4d10 + 6) Piercing damage.',9,6,'d10',4,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('acf5412f-1ce6-4b6a-9e67-9192931724b8'::uuid,'01990b8c-5715-76de-b2d5-89d34398f6ba'::uuid,'Multiattack','Action','None','The squid makes one Bite attack and one Tentacle attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b3bcf5a1-b180-4566-8f1e-2b028b977b5b'::uuid,'01990b8c-5715-76de-b2d5-89d34398f6ba'::uuid,'Ink Cloud','Reaction','None','The squid releases ink that fills a 15-foot Cube centered on itself, and the squid moves up to its Swim Speed. The Cube is Heavily Obscured for 1 minute or until a strong current or similar effect disperses the ink.',NULL,NULL,NULL,NULL,NULL,1,false,'The squid takes damage while underwater',NULL,NULL,NULL,NULL),
	 ('cd309f8d-2786-4dda-ad41-a74a760aa926'::uuid,'01990b8c-5715-76de-b2d5-89d34398f6ba'::uuid,'Tentacle','Action','Melee','Melee Attack Roll: +9, reach 15 ft. Hit: 19 (3d8 + 6) Bludgeoning damage. If the target is a Huge or smaller creature, it has the Grappled condition (escape DC 16) from one of two tentacles, and the squid can pull the target up to 10 feet straight toward itself.',9,6,'d8',3,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('55655c5d-e2d6-40ec-ad38-38dd45f05b59'::uuid,'01990b8c-7a44-7a0e-97ba-f9010e75710c'::uuid,'Swallow','Action','None','The toad swallows a Medium or smaller target it is grappling. While swallowed, the target isn''t Grappled but has the Blinded and Restrained conditions, and it has Total Cover against attacks and other effects outside the toad. In addition, the target takes 10 (3d6) Acid damage at the end of each of the toad''s turns. The toad can have only one target swallowed at a time, and it can''t use Bite while it has a swallowed target. If the toad dies, a swallowed creature is no longer Restrained and can escape from the corpse using 5 feet of movement, exiting with the Prone condition.',NULL,NULL,'d6',3,'Acid',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c684df7c-7ad6-4d08-b0a5-c358ef5a9e9a'::uuid,'01990b8c-7a44-7a0e-97ba-f9010e75710c'::uuid,'Bite','Action','Melee','Hit: 5 (1d6 + 2) Piercing damage plus 5 (2d4) Poison damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 12).',4,NULL,'d6',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('2983f7e7-f1d7-4891-a935-7feb6c4992f0'::uuid,'01990b8c-839a-776e-8575-09d205af9286'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +6, reach 10 ft. Hit: 6 (1d4 + 4) Piercing damage plus 4 (1d8) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c35bf283-c0ea-4e73-9d8d-41f145245ec6'::uuid,'01990b8c-9651-77ef-b152-5df758ff38b7'::uuid,'Gouge','Action','None','Gouge. Melee Attack Roll: +4, reach 5 ft. Hit: 9 (2d6 + 2) Piercing damage, and the target has the Poisoned condition until the end of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
