	 ('88e5a2a7-c8ac-46c2-9b14-5e3858bdfe74'::uuid,'01990b8c-df73-7037-ab0d-ec4f3bd90684'::uuid,'Bite','Action','Melee','Hit: 7 (2d6) Piercing damage. If the target is a Medium or smaller creature, it has the Prone condition. The target dies if it is reduced to 0 Hit Points by this attack. Its body is then absorbed into the mouther, leaving only equipment behind.',2,NULL,'d6',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c6a4121e-4e64-46b6-918e-8c41d024ce4e'::uuid,'01990b8c-df73-7037-ab0d-ec4f3bd90684'::uuid,'Blinding Spittle','Action','None','Failure: 7 (2d6) Radiant damage, and the target has the Blinded condition until the end of the mouther''s next turn.',NULL,NULL,'d6',2,'Radiant',6,false,NULL,NULL,NULL,NULL,NULL),
	 ('4668214c-5b50-4979-9c74-0af519b0caa9'::uuid,'01990b8d-1930-7da2-acf1-a57bd76f452c'::uuid,'Spellcasting','Action','None','The glabrezu casts one of the following spells, requiring no Material components and using Intelligence as the spellcasting ability (spell save DC 16):',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b3f73efb-0314-4c5b-86e0-0584409fbf6c'::uuid,'01990b8d-1930-7da2-acf1-a57bd76f452c'::uuid,'Multiattack','Action','None','The glabrezu makes two Pincer attacks and uses Pummel or Spellcasting.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
