	 ('59f43cf3-8ba6-41de-bec2-e181200876dc'::uuid,'01990b8d-6d2d-7ba1-b4d8-790c05291d6e'::uuid,'Ram','Action','None','Ram. Melee Attack Roll: +2, reach 5 ft. Hit: 1 Bludgeoning damage, or the goat deals 2 (1d4) Bludgeoning damage if it moved at least 20 feet straight toward the target immediately before the hit.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('278ce572-0c44-46a4-b813-aee56acf796e'::uuid,'01990b8d-92cf-78ce-9f4e-e70b7c13ac31'::uuid,'Multiattack','Action','None','Multiattack. The goblin makes two attacks, using Scimitar or Shortbow in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7defe2c5-992b-422e-aa3b-e67f52c1464c'::uuid,'01990b8d-92cf-78ce-9f4e-e70b7c13ac31'::uuid,'Scimitar','Action','None','Scimitar. Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Slashing damage, plus 2 (1d4) Slashing damage if the attack roll had Advantage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
