	 ('8aa7a3a4-5661-406c-a762-37ff3850be18'::uuid,'01990b8d-d975-7b5c-9783-57cd638e5f74'::uuid,'Weakening Breath','Action','Ranged','Strength Saving Throw: DC 13, each creature that isn''t currently affected by this breath in a 15-foot Cone. Failure: The target has Disadvantage on Strength-based D20 Tests and subtracts 2 (1d4) from its damage rolls. It repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.',NULL,NULL,'d4',1,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('008fe200-47f0-4d7a-845c-8b596c4b6084'::uuid,'01990b8d-ecc4-77f9-88c3-d988fd1b66b7'::uuid,'Petrifying Breath','Action','None','Constitution Saving Throw: DC 15, each creature in a 30-foot Cone. First Failure: The target has the Restrained condition and repeats the save at the end of its next turn if it is still Restrained, ending the effect on itself on a success. Second Failure: The target has the Petrified condition instead of the Restrained condition.',NULL,NULL,NULL,NULL,NULL,5,false,NULL,NULL,NULL,NULL,NULL),
	 ('2b585586-ee94-4180-ab9a-91da2cdd5445'::uuid,'01990b8d-ecc4-77f9-88c3-d988fd1b66b7'::uuid,'Gore','Action','Melee','Hit: 18 (2d12 + 5) Piercing damage. If the target is a Large or smaller creature and the gorgon moved 20+ feet straight toward it immediately before the hit, the target has the Prone condition.',8,5,'d12',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ed303e8d-d2ef-4931-8d52-dd3deb7c8bbe'::uuid,'01990b8d-ecc4-77f9-88c3-d988fd1b66b7'::uuid,'Trample','Bonus','None','Trample. Dexterity Saving Throw: DC 16, one creature within 5 feet that has the Prone condition. Failure: 16 (2d10 + 5) Bludgeoning damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('008e290e-c9dd-4f83-bfb3-7467330d223e'::uuid,'01990b8e-1b92-75b0-8919-3ae08628359b'::uuid,'Pseudopod','Action','Melee','Hit: 10 (2d8 + 1) Acid damage. Nonmagical armor worn by the target takes a -1 penalty to the AC it offers. The armor is destroyed if the penalty reduces its AC to 10. The penalty can be removed by casting the Mending spell on the armor.',3,1,'d8',2,'Acid',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('0b397c50-9709-42e5-a63a-9bdfe0688710'::uuid,'01990b8e-3809-787f-a678-76156f563f91'::uuid,'Rend','Action','Melee','Melee Attack Roll: +4, reach 5 ft. Hit: 7 (1d10 + 2) Slashing damage plus 3 (1d6) Poison damage.',4,NULL,'d10',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('52bf2253-256a-4524-9888-48c85a064517'::uuid,'01990b8e-3809-787f-a678-76156f563f91'::uuid,'Multiattack','Action','None','The dragon makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
