	 ('b55e6e0a-7149-47c4-8e4d-713969b7aed9'::uuid,'01990b8e-c90d-72f1-ba92-d76fdfcad08e'::uuid,'Multiattack','Action','Melee','The naga makes two Bite attacks. It can replace any attack with a use of Poisonous Spittle.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('e0fd5c53-3e1d-4792-9601-3cc8b2aae556'::uuid,'01990b8e-c90d-72f1-ba92-d76fdfcad08e'::uuid,'Poisonous Spittle','Action','None','Constitution Saving Throw: DC 16, one creature the naga can see within 60 feet. Failure: 31 (7d8) Poison damage, and the target has the Blinded condition until the start of the naga''s next turn. Success: Half damage only.',NULL,NULL,'d8',7,'Poison',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('14b7dd70-c15a-4995-ab5d-32b607a193a8'::uuid,'01990b8e-f1c3-7b76-bbaf-2b314565e51c'::uuid,'Claw','Action','Melee','Melee Attack Roll: +7, reach 10 ft. Hit: 6 (1d4 + 4) Slashing damage plus 7 (2d6) damage of the type chosen for the Draconic Origin trait.',7,4,'d4',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3c71cb9b-cc1a-4966-8aa7-98d5e6288b90'::uuid,'01990b8e-f1c3-7b76-bbaf-2b314565e51c'::uuid,'Leap','Bonus','None','The half-dragon jumps up to 30 feet by spending 10 feet of movement.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('9f9ad73f-2ca0-45d6-89dd-e31afd2bde8f'::uuid,'01990b8e-f1c3-7b76-bbaf-2b314565e51c'::uuid,'Multiattack','Action','None','The half-dragon makes two Claw attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('eb975a50-1ea8-4843-975e-7291e84e81aa'::uuid,'01990b8e-f1c3-7b76-bbaf-2b314565e51c'::uuid,'Dragon''s Breath','Action','Ranged','Dexterity Saving Throw: DC 14, each creature in a 30-foot Cone. Failure: 28 (8d6) damage of the type chosen for the Draconic Origin trait. Success: Half damage.',NULL,NULL,'d6',8,NULL,5,false,'Recharge 5-6',NULL,NULL,NULL,NULL),
	 ('182b3678-6a58-4eab-8e60-1ead657d1380'::uuid,'01990b8f-0490-7030-9356-6df675c87d33'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +3, reach 5 ft. Hit: 6 (2d4 + 1) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('4f8b3ee7-914a-4aa7-b617-65558d7b2863'::uuid,'01990b8f-0490-7030-9356-6df675c87d33'::uuid,'Luring Song','Action','None','Luring Song. The harpy sings a magical melody, which lasts until the harpy''s Concentration ends on it. Wisdom Saving Throw: DC 11, each Humanoid and Giant in a 300-foot Emanation originating from the harpy when the song starts. Failure: The target has the Charmed condition until the song ends and repeats the save at the end of each of its turns. While Charmed, the target has the Incapacitated condition and ignores the Luring Song of other harpies. If the target is more than 5 feet from the harpy, the target moves on its turn toward the harpy by the most direct route, trying to get within 5 feet of the harpy. It doesn''t avoid Opportunity Attacks; however, before moving into damaging terrain (such as lava or a pit) and whenever it takes damage from a source other than the harpy, the target repeats the save. Success: The target is immune to this harpy''s Luring Song for 24 hours.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('019d46e8-f447-46c2-83f7-39c566950a63'::uuid,'01990b8f-38a2-7353-b761-9b95700e93d8'::uuid,'Object Slam','Action','None','Melee or Ranged Attack Roll: +9 (with Advantage if the target is inside the revenant''s space), reach 10 ft. or range 30/90 ft. Hit: 27 (5d8+ 5) Bludgeoning damage.',9,5,'d8',5,'Bludgeoning',NULL,false,NULL,'if the target is inside the revenant''s space',NULL,NULL,NULL),
	 ('9dc22c93-227a-49e3-bd11-6a4fbfe908cd'::uuid,'01990b8f-38a2-7353-b761-9b95700e93d8'::uuid,'Invitation','Action','None','Charisma Saving Throw: DC 17, each creature in a 60-foot Cone. Failure: The target is teleported inside the revenant''s space and swallowed. A swallowed creature has Total Cover against attacks and other effects outside the revenant. While the revenant has Hit Points, a swallowed creature can leave the revenant''s space only by using magic that enables planar travel, such as the Plane Shift spell.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('d57f0765-8dfe-40e2-a1a4-0491d895a0fd'::uuid,'01990b8f-38a2-7353-b761-9b95700e93d8'::uuid,'Multiattack','Action','None','The revenant makes two Object Slam attacks and uses Invitation.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c5edc867-8dc5-4ccf-b517-6591b39575f5'::uuid,'01990b8f-41b8-7da7-9b87-10aa240eb011'::uuid,'Talons','Action','None','Talons. Melee Attack Roll: +5, reach 5 ft. Hit: 1 Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('76648ab6-2bd5-4adf-9cdc-88048e6e353e'::uuid,'01990b8f-6a39-7a50-8ab0-cd3c09212d4c'::uuid,'Fire Breath','Action','Ranged','Dexterity Saving Throw: DC 12, each creature in a 15-foot Cone. Failure: 17 (5d6) Fire damage. Success: Half damage.',NULL,NULL,'d6',5,'Fire',5,false,NULL,NULL,NULL,NULL,NULL),
	 ('b5543ec3-0b8d-49c1-9c16-025b4206a730'::uuid,'01990b8f-6a39-7a50-8ab0-cd3c09212d4c'::uuid,'Multiattack','Action','Melee','The hound makes two Bite attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
