	 ('be7bbb06-5848-4cad-b97d-1c6a5deea77e'::uuid,'01990b8f-afd8-7e44-892e-3268312e7d5a'::uuid,'Tree Club','Action','None','Tree Club. Melee Attack Roll: +8, reach 10 ft. Hit: 18 (3d8 + 5) Bludgeoning damage. If the target is a Large or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
