	 ('27f7440a-1cce-4a87-9fa3-e0072484c4db'::uuid,'01990b90-0f52-780e-ad21-d5dfaee219b4'::uuid,'Longbow','Action','None','Longbow. Ranged Attack Roll: +3, range 150/600 ft. Hit: 5 (1d8 + 1) Piercing damage plus 7 (3d4) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('87cec5de-3ec8-4aad-b9eb-2eab931d0e08'::uuid,'01990b90-0f52-780e-ad21-d5dfaee219b4'::uuid,'Longsword','Action','None','Longsword. Melee Attack Roll: +3, reach 5 ft. Hit: 12 (2d10 + 1) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('6d0f568b-b851-48d9-8722-4fbdfda24cf4'::uuid,'01990b90-2183-73d4-bf32-cf424be4cc15'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 1 Piercing damage, and the target is subjected to the following effect. Constitution Saving Throw: DC 12. Failure: The target has the Poisoned condition until the end of the homunculus''s next turn. Failure by 5 or More: The target has the Poisoned condition for 1 minute. While Poisoned, the target has the Unconscious condition, which ends early if the target takes any damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('27fbf944-2737-406a-8d03-004843cbf993'::uuid,'01990b90-433f-72a7-8465-b8b8dc517a80'::uuid,'Searing Fork','Action','None','Searing Fork. Melee Attack Roll: +10, reach 10 ft. Hit: 15 (2d8 + 6) Piercing damage plus 9 (2d8) Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('422bfcd3-aa89-4dea-96be-012824f73fca'::uuid,'01990b90-433f-72a7-8465-b8b8dc517a80'::uuid,'Hurl Flame','Action','None','Hurl Flame. Ranged Attack Roll: +8, range 150 ft. Hit: 26 (5d8 + 4) Fire damage. If the target is a flammable object that isn''t being worn or carried, it starts burning.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a59360ba-7c31-4ceb-afbe-68edd96e29e4'::uuid,'01990b90-433f-72a7-8465-b8b8dc517a80'::uuid,'Multiattack','Action','None','Multiattack. The devil makes three attacks, using Searing Fork or Hurl Flame in any combination. It can replace one attack with a use of Infernal Tail.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d2f57bf2-f480-411f-9849-b19ef218a32f'::uuid,'01990b90-433f-72a7-8465-b8b8dc517a80'::uuid,'Infernal Tail','Action','None','Infernal Tail. Dexterity Saving Throw: DC 17, one creature the devil can see within 10 feet. Failure: 10 (1d8 + 6) Necrotic damage, and the target receives an infernal wound if it doesn''t have one. While wounded, the target loses 10 (3d6) Hit Points at the start of each of its turns. The wound closes after 1 minute, after a spell restores Hit Points to the target, or after the target or a creature within 5 feet of it takes an action to stanch the wound, doing so by succeeding on a DC 17 Wisdom (Medicine) check.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c43ee78d-5b6b-4aa7-94bd-baad0cc992df'::uuid,'01990b90-5108-7ff2-a063-d421e88d7f68'::uuid,'Bite','Action','Melee','Hit: 14 (3d6 + 4) Piercing damage.',6,4,'d6',3,'Piercing',NULL,false,NULL,'if the target doesn''t have all its Hit Points',NULL,NULL,NULL),
	 ('a72f3400-1e09-47f6-9747-79af7fa843d4'::uuid,'01990b90-6e36-777a-941e-d07bae44b83a'::uuid,'Multiattack','Action','None','The hydra makes as many Bite attacks as it has heads.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
