	 ('fe12391c-fc2e-4174-8668-f9abbce44a6f'::uuid,'01990b90-6e36-777a-941e-d07bae44b83a'::uuid,'Bite','Action','Melee','Melee Attack Roll: +8, reach 10 ft. Hit: 10 (1d10 + 5) Piercing damage.',8,5,'d10',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
