	 ('384c5bfb-8204-410f-92c8-cc6d4d4eb9e6'::uuid,'01990b90-a159-734a-96be-817ca0c88f4a'::uuid,'Multiattack','Action','None','Multiattack. The devil makes three Ice Spear attacks. It can replace one attack with a Tail attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7faa1546-1ab0-41c9-bff1-6d8513f4d28a'::uuid,'01990b90-a159-734a-96be-817ca0c88f4a'::uuid,'Ice Wall (Recharge 6)','Action','None','Ice Wall (Recharge 6). The devil casts Wall of Ice (level 8 version), requiring no spell components and using Intelligence as the spellcasting ability (spell save DC 17).',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f2b6f561-93e6-4ace-9ffe-2dea46e62d12'::uuid,'01990b92-f546-7a21-bba5-d5097eb1eacb'::uuid,'Multiattack','Action','None','Multiattack. The mage makes three Arcane Burst attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7c35867e-c3c2-4d69-b1dd-9a69de49f8cb'::uuid,'01990b93-0549-7e38-a8d5-37dbe25e63bf'::uuid,'Arcane Burst','Action','None','Arcane Burst. Melee or Ranged Attack Roll: +5, reach 5 ft. or range 120 ft. Hit: 14 (2d10 + 3) Force damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a413d242-ded8-426b-ab9b-137658403a42'::uuid,'01990b90-a159-734a-96be-817ca0c88f4a'::uuid,'Ice Spear','Action','None','Ice Spear. Melee or Ranged Attack Roll: +10, reach 5 ft. or range 30/120 ft. Hit: 14 (2d8 + 5) Piercing damage plus 10 (3d6) Cold damage. Until the end of its next turn, the target can''t take a Bonus Action or Reaction, its Speed decreases by 10 feet, and it can move or take one action on its turn, not both. Hit or Miss: The spear magically returns to the devil''s hand immediately after a ranged attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('bb3e4e19-beae-4f75-8a9b-3e2436f55549'::uuid,'01990b90-a159-734a-96be-817ca0c88f4a'::uuid,'Tail','Action','None','Tail. Melee Attack Roll: +10, reach 10 ft. Hit: 15 (3d6 + 5) Bludgeoning damage plus 18 (4d8) Cold damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('5d0a9c3f-eeaa-4b40-9c57-9118003ddb93'::uuid,'01990b90-bbd2-7941-9fe5-ba2969848b88'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +3, reach 5 ft. Hit: 3 (1d4 + 1) Slashing damage plus 2 (1d4) Cold damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('67abeec4-555b-4556-b6bf-74e633be2f1c'::uuid,'01990b90-bbd2-7941-9fe5-ba2969848b88'::uuid,'Fog Cloud (1/Day)','Action','None','Fog Cloud (1/Day). The mephit casts Fog Cloud, requiring no spell components and using Charisma as the spellcasting ability.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('96a51001-6e54-4699-a390-ac526975329d'::uuid,'01990b90-bbd2-7941-9fe5-ba2969848b88'::uuid,'Frost Breath (Recharge 6)','Action','None','Frost Breath (Recharge 6). Constitution Saving Throw: DC 10, each creature in a 15-foot Cone. Failure: 7 (3d4) Cold damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('36b11ef8-27e5-4706-931f-f9a8ba353479'::uuid,'01990b90-d6e8-778d-99aa-2acd89ab5f33'::uuid,'Shape-Shift','Action','None','Shape-Shift. The imp shape-shifts to resemble a rat (Speed 20 ft.), a raven (20 ft., Fly 60 ft.), or a spider (20 ft., Climb 20 ft.), or it returns to its true form. Its statistics are the same in each form, except for its Speed. Any equipment it''s wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a97feb0c-a464-4833-aaac-c59a6483682a'::uuid,'01990b90-d6e8-778d-99aa-2acd89ab5f33'::uuid,'Sting','Action','None','Sting. Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage plus 7 (2d6) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ac413860-a7e3-48bd-9587-e8955296a403'::uuid,'01990b90-d6e8-778d-99aa-2acd89ab5f33'::uuid,'Invisibility','Action','None','Invisibility. The imp casts Invisibility on itself, requiring no spell components and using Charisma as the spellcasting ability.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('226a1edc-c382-4435-aa7d-be3085a7aca5'::uuid,'01990b90-fcd2-7f82-95b8-cdb8e91b2d91'::uuid,'Nightmare','Bonus','None','Wisdom Saving Throw: DC 15, one creature the incubus can see within 60 feet. Failure: If the target has 20 Hit Points or fewer, it has the Unconscious condition for 1 hour, until it takes damage, or until a creature within 5 feet of it takes an action to wake it. Otherwise, the target takes 18 (4d8) Psychic damage.',NULL,NULL,'d8',4,'Psychic',6,false,'Recharge 6',NULL,NULL,NULL,NULL),
	 ('5a3ea229-3a37-4eaf-8be4-4913740b5a36'::uuid,'01990b90-fcd2-7f82-95b8-cdb8e91b2d91'::uuid,'Restless Touch','Action','Melee','Melee Attack Roll: +7, reach 5 ft. Hit: 15 (3d6 + 5) Psychic damage, and the target is cursed for 24 hours or until the incubus dies. Until the curse ends, the target gains no benefit from finishing Short Rests.',7,5,'d6',3,'Psychic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('70a7bc43-81c4-42ef-88d5-25396ef26f14'::uuid,'01990b90-fcd2-7f82-95b8-cdb8e91b2d91'::uuid,'Multiattack','Action','None','The incubus makes two Restless Touch attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c8c1a19c-acc7-4cbe-844d-dda0a692931e'::uuid,'01990b90-fcd2-7f82-95b8-cdb8e91b2d91'::uuid,'Spellcasting','Action','None','The incubus casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 15):',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('19824dbb-970d-47bf-9a2b-4896988b334e'::uuid,'01990b91-217f-716b-ac50-5efbfbd0a978'::uuid,'Vortex','Action','None','Constitution Saving Throw: DC 14, one Large or smaller creature in the stalker''s space. Failure: 7 (1d8 + 3) Thunder damage, and the target has the Grappled condition (escape DC 13). Until the grapple ends, the target can''t cast spells with a Verbal component and takes 7 (2d6) Thunder damage at the start of each of the stalker''s turns.',NULL,NULL,'d8',1,'Thunder',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a0c91269-7f8b-4f97-9eac-1ef7ad84c4ba'::uuid,'01990b91-217f-716b-ac50-5efbfbd0a978'::uuid,'Wind Swipe','Action','Melee','Melee Attack Roll: +7, reach 5 ft. Hit: 11 (2d6 + 4) Force damage.',7,4,'d6',2,'Force',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('ad313ca6-87d3-4c39-8250-223f682701c3'::uuid,'01990b91-217f-716b-ac50-5efbfbd0a978'::uuid,'Multiattack','Action','None','The stalker makes three Wind Swipe attacks. It can replace one attack with a use of Vortex.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('41f89389-2a7f-447a-aba5-cc3c97676da0'::uuid,'01990b91-4546-7d53-b9f9-c0071e625c63'::uuid,'Poison Breath (Recharge 6)','Action','None','Poison Breath (Recharge 6). Constitution Saving Throw: DC 18, each creature in a 60-foot Cone. Failure: 55 (10d10) Poison damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('551b0a81-9c2c-4603-8618-d7a9f159561d'::uuid,'01990b91-4546-7d53-b9f9-c0071e625c63'::uuid,'Bladed Arm','Action','None','Bladed Arm. Melee Attack Roll: +12, reach 10 ft. Hit: 20 (3d8 + 7) Slashing damage plus 10 (3d6) Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('88fe38f3-8782-4c4b-b54c-bb79b53fa903'::uuid,'01990b91-4546-7d53-b9f9-c0071e625c63'::uuid,'Fiery Bolt','Action','None','Fiery Bolt. Ranged Attack Roll: +10, range 120 ft. Hit: 36 (8d8) Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e1ac56d6-1c33-455b-b2fd-a626aef9b042'::uuid,'01990b91-4546-7d53-b9f9-c0071e625c63'::uuid,'Multiattack','Action','None','Multiattack. The golem makes two attacks, using Bladed Arm or Fiery Bolt in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d8a60c8d-3196-4627-8843-c32f01ee3613'::uuid,'01990b91-4d4e-7502-a481-53355d321460'::uuid,'Bite','Action','Melee','Hit: 1 (1d4 - 1) Piercing damage.',1,-1,'d4',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('68a8a058-11d8-452a-ad15-d8980bac3365'::uuid,'01990b91-7422-7f7b-ad0c-371cc1f81368'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +6, reach 5 ft. Hit: 21 (5d6 + 4) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('5563fd06-96ff-4d94-94c4-54dbda186deb'::uuid,'01990b91-9150-7fd3-b0f1-3f43fc0ab89a'::uuid,'Multiattack','Action','None','Multiattack. The knight makes two attacks, using Greatsword or Heavy Crossbow in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7333d391-b72b-4c3d-b566-b6960c7944a4'::uuid,'01990b91-9150-7fd3-b0f1-3f43fc0ab89a'::uuid,'Greatsword','Action','None','Greatsword. Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6+ 3) Slashing damage plus 4 (1d8) Radiant damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('b411b4f1-9ca9-4295-99d2-4c9b614ab479'::uuid,'01990b91-9150-7fd3-b0f1-3f43fc0ab89a'::uuid,'Heavy Crossbow','Action','None','Heavy Crossbow. Ranged Attack Roll: +2, range 100/400 ft. Hit: 11 (2d10) Piercing damage plus 4 (1d8) Radiant damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('b705287e-6c0c-419e-9be6-bf4142e980b9'::uuid,'01990b91-9150-7fd3-b0f1-3f43fc0ab89a'::uuid,'Parry','Reaction','Melee','The knight adds 2 to its AC against the triggering attack, possibly causing it to miss.',NULL,NULL,NULL,NULL,NULL,NULL,false,'The knight is hit by a melee attack roll while holding a weapon.',NULL,NULL,NULL,NULL),
	 ('0442140e-4230-4c60-a719-cb8e738f702e'::uuid,'01990b91-a38f-7599-8a56-0270d2412fe2'::uuid,'Dagger','Action','None','Dagger. Melee or Ranged Attack Roll: +4, reach 5 ft. or range 20/60 ft. Hit: 4 (1d4 + 2) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('1b46be5f-ba0c-41cd-b927-496f946cfe94'::uuid,'01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Tentacle','Action','None','Tentacle. Melee Attack Roll: +17, reach 30 ft. Hit: 24 (4d6 + 10) Bludgeoning damage. The target has the Grappled condition (escape DC 20) from one of ten tentacles, and it has the Restrained condition until the grapple ends.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('60f09679-84b3-4a51-b374-d35377265fdf'::uuid,'01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Toxic Ink','Legendary','None','Constitution Saving Throw: DC 23, each creature in a 15-foot Emanation originating from the kraken while it is underwater. Failure: The target has the Blinded and Poisoned conditions until the end of the kraken''s next turn. The kraken then moves up to its Speed. Failure or Success: The kraken can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('acd63b27-4a88-4978-a638-f391f06efc55'::uuid,'01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Storm Bolt','Legendary','Ranged','The kraken uses Lightning Strike.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ff72f028-8301-4a87-bee7-1c242b65418d'::uuid,'01990b93-0549-7e38-a8d5-37dbe25e63bf'::uuid,'Spellcasting','Action','None','Spellcasting. The mage casts one of the following spells, using Intelligence as the spellcasting ability (spell save DC 13, +5 to hit with spell attacks):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('53b8c561-5504-4059-9b60-8e6eb6191706'::uuid,'01990b93-1c54-7090-bb80-392aa9995fa4'::uuid,'Fire Breath','Action','None','Failure: 7 (2d6) Fire damage. Success: Half damage.',NULL,NULL,'d6',2,'Fire',6,false,NULL,NULL,NULL,NULL,NULL),
	 ('a722baeb-6c57-4127-a7ee-22348f705d50'::uuid,'01990b93-1c54-7090-bb80-392aa9995fa4'::uuid,'Claw','Action','Melee','Hit: 3 (1d4 + 1) Slashing damage plus 3 (1d6) Fire damage.',3,NULL,'d4',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b7b3ca59-83f4-4be9-89a8-e7f6eeb5c30c'::uuid,'01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Swallow','Action','None','Swallow. Dexterity Saving Throw: DC 25, one creature Grappled by the kraken (it can have up to four creatures swallowed at a time). Failure: 23 (3d8 + 10) Piercing damage. If the target is Large or smaller, it is swallowed and no longer Grappled. A swallowed creature has the Restrained condition, has Total Cover against attacks and other effects outside the kraken, and takes 24 (7d6) Acid damage at the start of each of its turns. If the kraken takes 50 damage or more on a single turn from a creature inside it, the kraken must succeed on a DC 25 Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, each of which falls in a space within 10 feet of the kraken with the Prone condition. If the kraken dies, any swallowed creature no longer has the Restrained condition and can escape from the corpse using 15 feet of movement, exiting Prone.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('bf71efcd-468a-46c2-9aa7-488a8cc773d7'::uuid,'01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Multiattack','Action','None','Multiattack. The kraken makes two Tentacle attacks and uses Fling, Lightning Strike, or Swallow.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('df504ba8-5977-45f5-8475-5f821974870f'::uuid,'01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Fling','Action','None','Fling. The kraken throws a Large or smaller creature Grappled by it to a space it can see within 60 feet of itself that isn''t in the air. Dexterity Saving Throw: DC 25, the creature thrown and each creature in the destination space. Failure: 18 (4d8) Bludgeoning damage, and the target has the Prone condition. Success: Half damage only.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('eb7d1859-0b7e-4417-a56d-463fae366888'::uuid,'01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Lightning Strike','Action','None','Lightning Strike. Dexterity Saving Throw: DC 23, one creature the kraken can see within 120 feet. Failure: 33 (6d10) Lightning damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('5fff5454-2b55-4466-9743-a98d5201c116'::uuid,'01990b92-0f8a-71ae-a5ff-450bfb8cce38'::uuid,'Sticky Shield','Reaction','None','Trigger: A creature misses the kuo-toa with a melee attack roll using a weapon. Response—Strength Saving Throw: DC 11, the triggering creature. Failure: The attack''s weapon sticks to the kuo-toa''s shield. If the target doesn''t let go of the weapon, the target has the Grappled condition while the weapon is stuck (escape DC 11). While stuck, the weapon can''t be used. The target can take an action to make a DC 11 Strength (Athletics) check, freeing the weapon on a success.',NULL,NULL,NULL,NULL,NULL,NULL,false,'A creature misses the kuo-toa with a melee attack roll using a weapon',NULL,NULL,NULL,NULL),
	 ('b8eb698b-7cef-4a08-9e42-26bd52b982c8'::uuid,'01990b92-0f8a-71ae-a5ff-450bfb8cce38'::uuid,'Sticky Net (1/Day)','Action','None','Sticky Net (1/Day). Dexterity Saving Throw: DC 10, one Large or smaller creature the kuo-toa can see within 15 feet. Failure: The target has the Restrained condition until the net is destroyed (AC 10; HP 5; Immunity to Bludgeoning, Poison, and Psychic damage). A creature can take an action to make a DC 10 Strength (Athletics) check to free itself or another creature in a net within 5 feet, destroying the net on a success.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c2a85741-5839-4a8b-80a8-a55823536377'::uuid,'01990b92-0f8a-71ae-a5ff-450bfb8cce38'::uuid,'Spear','Action','None','Spear. Melee or Ranged Attack Roll: +3, reach 5 ft. or range 20/60 ft. Hit: 5 (1d8 + 1) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('337a4f2f-6f47-4ba7-b6a3-ceb5c7c27819'::uuid,'01990b92-540f-7cb5-b91a-dccd5a002b8c'::uuid,'Spellcasting','Action','None','Spellcasting. The lamia casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 13):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('6d1fb74e-17fb-4ddd-a8b1-b46d67e0a958'::uuid,'01990b92-540f-7cb5-b91a-dccd5a002b8c'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Slashing damage plus 7 (2d6) Psychic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('979b37cf-d76c-416a-b566-f3747118f911'::uuid,'01990b92-540f-7cb5-b91a-dccd5a002b8c'::uuid,'Leap','Bonus','None','The lamia jumps up to 30 feet by spending 10 feet of movement.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('dbb8b438-1756-4c14-992e-d2d538d43fc4'::uuid,'01990b92-540f-7cb5-b91a-dccd5a002b8c'::uuid,'Corrupting Touch','Action','None','Corrupting Touch. Wisdom Saving Throw: DC 13, one creature the lamia can see within 5 feet. Failure: 13 (3d8) Psychic damage, and the target is cursed for 1 hour. Until the curse ends, the target has the Charmed and Poisoned conditions.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f5920d6b-696b-4df6-a80e-2de6b07f53c9'::uuid,'01990b92-540f-7cb5-b91a-dccd5a002b8c'::uuid,'Multiattack','Action','None','Multiattack. The lamia makes two Claw attacks. It can replace one attack with a use of Corrupting Touch.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('065797c1-244f-4de1-8277-0219b82684f1'::uuid,'01990b92-59a1-789c-ad74-c45d936d6354'::uuid,'Bite','Action','Melee','Hit: 1 (1d4 - 1) Necrotic damage.',1,-1,'d4',1,'Necrotic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('8e71d898-c723-42c2-9ecb-c652db25a7c3'::uuid,'01990b92-6735-7466-b1ca-ac2244de89ed'::uuid,'Vile Slime','Action','None','Vile Slime. Melee Attack Roll: +2, reach 5 ft. Hit: 2 (1d4) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0717b3c5-b646-4fac-a69d-19577dcb2532'::uuid,'01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Spellcasting','Action','None','Spellcasting. The lich casts one of the following spells, using Intelligence as the spellcasting ability (spell save DC 20):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('24a3c748-9f36-4b7a-bb64-3cf453fd6a1f'::uuid,'01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Deathly Teleport','Legendary','None','The lich teleports up to 60 feet to an unoccupied space it can see, and each creature within 10 feet of the space it left takes 11 (2d10) Necrotic damage.',NULL,NULL,'d10',2,'Necrotic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('40406744-1c37-4364-a67a-5ed5814c9607'::uuid,'01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Frightening Gaze','Legendary','None','The lich casts Fear, using the same spellcasting ability as Spellcasting. The lich can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('4a5b8e6c-813e-4f38-a9d1-acc278f1cf85'::uuid,'01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Disrupt Life','Legendary','None','Constitution Saving Throw: DC 20, each creature that isn''t an Undead in a 20-foot Emanation originating from the lich. Failure: 31 (9d6) Necrotic damage. Success: Half damage. Failure or Success: The lich can''t take this action again until the start of its next turn.',NULL,NULL,'d6',9,'Necrotic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('51e6a0f7-8e2e-4804-82e5-1f3cf70f7940'::uuid,'01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Eldritch Burst','Action','None','Eldritch Burst. Melee or Ranged Attack Roll: +12, reach 5 ft. or range 120 ft. Hit: 31 (4d12 + 5) Force damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('6281df4b-e054-4d09-814f-19aa735247a1'::uuid,'01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Paralyzing Touch','Action','None','Paralyzing Touch. Melee Attack Roll: +12, reach 5 ft. Hit: 15 (3d6 + 5) Cold damage, and the target has the Paralyzed condition until the start of the lich''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('96a7b862-04f0-4a85-96f0-483e810f335c'::uuid,'01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Multiattack','Action','None','Multiattack. The lich makes three attacks, using Eldritch Burst or Paralyzing Touch in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e567d02c-9848-43c5-86cd-94c4335d85b0'::uuid,'01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Protective Magic','Reaction','None','The lich casts Counterspell or Shield in response to the spell''s trigger, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,NULL,false,'in response to the spell''s trigger',NULL,NULL,NULL,NULL);
