	 ('9ca24ce2-a79b-470d-8493-fc1baf640434'::uuid,'01990b92-bfa9-75a2-a4f2-5a075ff1ac51'::uuid,'Rend','Action','Melee','Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Slashing damage.',5,3,'d8',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a06e98c2-6d5b-46c2-8c96-9d14aed0b5fb'::uuid,'01990b92-bfa9-75a2-a4f2-5a075ff1ac51'::uuid,'Multiattack','Action','None','The lion makes two Rend attacks. It can replace one of these attacks with a use of Roar.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('e978c24a-1bb0-4cbc-b0b9-2dea33825bf4'::uuid,'01990b92-bfa9-75a2-a4f2-5a075ff1ac51'::uuid,'Roar','Action','None','Wisdom Saving Throw: DC 11, one creature within 15 feet. Failure: The target has the Frightened condition until the start of the lion''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3837ca72-5f02-42a1-9413-959e7db44cf8'::uuid,'01990b92-d136-73a4-8e83-5ad5de0d09ec'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +2, reach 5 ft. Hit: 1 Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0ebd45bc-716b-4885-bda2-4dc203f4feb8'::uuid,'01990b92-f546-7a21-bba5-d5097eb1eacb'::uuid,'Protective Magic','Reaction','None','The mage casts Counterspell or Shield in response to the spell''s trigger, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,3,false,'in response to the spell''s trigger',NULL,NULL,NULL,NULL),
	 ('5242fddc-9962-4a42-8efa-1e7d8f9c09f0'::uuid,'01990b92-f546-7a21-bba5-d5097eb1eacb'::uuid,'Spellcasting','Action','None','Spellcasting. The mage casts one of the following spells, using Intelligence as the spellcasting ability (spell save DC 14):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('3ed8d825-5435-47b3-93e0-33c41b3b098b'::uuid,'01990b93-3d83-7a41-847a-f62e5c0b1e9a'::uuid,'Ignited Illumination','Bonus','None','The magmin sets itself ablaze or extinguishes its flames. While ablaze, the magmin sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('666ebf19-86e1-42c7-a73b-d0a1353c9e9e'::uuid,'01990b93-3d83-7a41-847a-f62e5c0b1e9a'::uuid,'Touch','Action','Melee','Hit: 7 (2d4 + 2) Fire damage. If the target is a creature or a flammable object that isn''t being worn or carried, it starts burning.',4,2,'d4',2,'Fire',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('2928ba9a-f09e-452e-ad2a-5de989d8f3e7'::uuid,'01990b93-51e4-7068-99bc-0b107add1ab3'::uuid,'Trample','Bonus','None','Trample. Dexterity Saving Throw: DC 18, one creature within 5 feet that has the Prone condition. Failure: 29 (4d10 + 7) Bludgeoning damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('68aae743-039d-425b-9333-2356c6875933'::uuid,'01990b93-51e4-7068-99bc-0b107add1ab3'::uuid,'Multiattack','Action','None','The mammoth makes two Gore attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('8311e332-94ac-41df-8cde-b31a5e431429'::uuid,'01990b93-51e4-7068-99bc-0b107add1ab3'::uuid,'Gore','Action','Melee','Melee Attack Roll: +10, reach 10 ft. Hit: 18 (2d10 + 7) Piercing damage. If the target is a Huge or smaller creature and the mammoth moved 20+ feet straight toward it immediately before the hit, the target has the Prone condition.',10,7,'d10',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('7b1cb77a-3ea3-43dd-84ca-59a8878b8146'::uuid,'01990b93-6e5f-7c25-a6ec-33e85cf4d37d'::uuid,'Multiattack','Action','None','Multiattack. The manticore makes three attacks, using Rend or Tail Spike in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a630ad04-6411-4e06-9236-867cf7250e7a'::uuid,'01990b93-6e5f-7c25-a6ec-33e85cf4d37d'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f6076de3-72b8-49eb-b779-16fce589a30c'::uuid,'01990b93-6e5f-7c25-a6ec-33e85cf4d37d'::uuid,'Tail Spike','Action','None','Tail Spike. Ranged Attack Roll: +5, range 100/200 ft. Hit: 7 (1d8 + 3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2bf6246f-12c3-495a-aae1-8d077dc2afc6'::uuid,'01990b93-a8ee-75a1-8e8f-a2190e84822c'::uuid,'Pact Blade','Action','Melee','Melee Attack Roll: +10, reach 5 ft. Hit: 10 (1d10 + 5) Slashing damage plus 7 (2d6) Necrotic damage.',10,NULL,'d10',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5a264ff8-83f7-4d0d-9ee0-68fd302700f0'::uuid,'01990b93-a8ee-75a1-8e8f-a2190e84822c'::uuid,'Teleport','Bonus','None','The marilith teleports up to 120 feet to an unoccupied space it can see.',NULL,NULL,NULL,NULL,NULL,6,false,'Recharge 5-6',NULL,NULL,NULL,NULL),
	 ('cb824c4f-3ad7-49d2-bb5d-8e38d41ed4f2'::uuid,'01990b93-a8ee-75a1-8e8f-a2190e84822c'::uuid,'Constrict','Action','Melee','Strength Saving Throw: DC 17, one Medium or smaller creature the marilith can see within 5 feet. Failure: 15 (2d10 + 4) Bludgeoning damage. The target has the Grappled condition (escape DC 14), and it has the Restrained condition until the grapple ends.',NULL,NULL,'d10',2,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('cd729698-3324-4cdf-b453-cd726827269d'::uuid,'01990b93-a8ee-75a1-8e8f-a2190e84822c'::uuid,'Multiattack','Action','Melee','The marilith makes six Pact Blade attacks and uses Constrict.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('cde4a483-8c76-47de-96d8-a7ff0a8c70ce'::uuid,'01990b93-a8ee-75a1-8e8f-a2190e84822c'::uuid,'Parry','Reaction','None','The marilith adds 5 to its AC against the triggering attack, possibly causing it to miss.',NULL,NULL,NULL,NULL,NULL,NULL,false,'The marilith is hit by a melee attack roll while holding a weapon.',NULL,NULL,NULL,NULL),
	 ('cc2c35a8-e3e4-494d-bb34-38e082f6a4c2'::uuid,'01990b93-b352-75fb-8e36-de30d954a3d4'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +3, reach 5 ft. Hit: 4 (1d6 + 1) Piercing damage. If the target is a Medium or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('0221d6b7-8a31-4def-b52f-56af0c9b0b1c'::uuid,'01990b93-d68d-75b6-9126-24e55a0d2ce4'::uuid,'Petrifying Gaze','Bonus','None','Constitution Saving Throw: DC 13, each creature in a 30-foot Cone. If the medusa sees its reflection in the Cone, the medusa must make this save. First Failure: The target has the Restrained condition and repeats the save at the end of its next turn if it is still Restrained, ending the effect on itself on a success. Second Failure: The target has the Petrified condition instead of the Restrained condition.',NULL,NULL,NULL,NULL,NULL,1,false,'Recharge 5–6',NULL,NULL,NULL,NULL),
	 ('091c4419-a15b-4456-9231-c470302c9c47'::uuid,'01990b93-d68d-75b6-9126-24e55a0d2ce4'::uuid,'Poison Ray','Action','None','Poison Ray. Ranged Attack Roll: +5, range 150 ft. Hit: 11 (2d8 + 2) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2647666e-b307-4ad4-8928-52622f6370ea'::uuid,'01990b93-d68d-75b6-9126-24e55a0d2ce4'::uuid,'Multiattack','Action','None','Multiattack. The medusa makes two Claw attacks and one Snake Hair attack, or it makes three Poison Ray attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2758d5e3-86d6-47d0-a615-ef564d976857'::uuid,'01990b93-d68d-75b6-9126-24e55a0d2ce4'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +6, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ac46ab27-986a-40fa-a047-4a8a72e50da6'::uuid,'01990b93-d68d-75b6-9126-24e55a0d2ce4'::uuid,'Snake Hair','Action','None','Snake Hair. Melee Attack Roll: +6, reach 5 ft. Hit: 5 (1d4 + 3) Piercing damage plus 14 (4d6) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('de320772-3826-4fd5-822d-7bb9bcf9c5ae'::uuid,'01990b93-eb07-73c9-8530-4ce0ab69f055'::uuid,'Ocean Spear','Action','None','Ocean Spear. Melee or Ranged Attack Roll: +2, reach 5 ft. or range 20/60 ft. Hit: 3 (1d6) Piercing damage plus 2 (1d4) Cold damage. If the target is a creature, its Speed decreases by 10 feet until the end of its next turn. Hit or Miss: The spear magically returns to the merfolk''s hand immediately after a ranged attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0d5c3e2e-6310-4ef4-915c-f789cde982df'::uuid,'01990b94-15d3-71cb-81c7-4e6e58caf071'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +6, reach 5 ft. Hit: 6 (1d4 + 4) Piercing damage, and the target has the Poisoned condition until the end of the merrow''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2684a9f6-bf52-4634-ab34-c610f3267058'::uuid,'01990b94-15d3-71cb-81c7-4e6e58caf071'::uuid,'Harpoon','Action','None','Harpoon. Melee or Ranged Attack Roll: +6, reach 5 ft. or range 20/60 ft. Hit: 11 (2d6 + 4) Piercing damage. If the target is a Large or smaller creature, the merrow pulls the target up to 15 feet straight toward itself.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('99f0beb7-f4e6-4675-a98c-691cf06fa9aa'::uuid,'01990b94-15d3-71cb-81c7-4e6e58caf071'::uuid,'Multiattack','Action','None','Multiattack. The merrow makes two attacks, using Bite, Claw, or Harpoon in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a21e1a92-6fe0-48b4-9959-6466b291f678'::uuid,'01990b94-15d3-71cb-81c7-4e6e58caf071'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +6, reach 5 ft. Hit: 9 (2d4 + 4) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('11db8b8e-52f7-4c59-8302-5f49a8ddce8c'::uuid,'01990b94-45d0-7aa2-ab46-a2a3d79b665d'::uuid,'Pseudopod','Action','Melee','Hit: 7 (1d8 + 3) Bludgeoning damage plus 4 (1d8) Acid damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 13). Ability checks made to escape this grapple have Disadvantage.',5,NULL,'d8',1,'Bludgeoning',NULL,false,NULL,NULL,'escape DC 13',NULL,NULL),
	 ('11f6e2b1-291d-4348-94db-36669a629a99'::uuid,'01990b94-45d0-7aa2-ab46-a2a3d79b665d'::uuid,'Bite','Action','Melee','Hit: 7 (1d8 + 3) Piercing damage—or 12 (2d8 + 3) Piercing damage if the target is Grappled by the mimic—plus 4 (1d8) Acid damage.',5,NULL,'d8',1,'Piercing',NULL,false,NULL,'if the target is Grappled by the mimic',NULL,NULL,NULL),
	 ('52089165-603c-4058-86d6-923ed9f43c6e'::uuid,'01990b94-45d0-7aa2-ab46-a2a3d79b665d'::uuid,'Shape-Shift','Bonus','None','The mimic shape-shifts to resemble a Medium or Small object while retaining its game statistics, or it returns to its true blob form. Any equipment it is wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('69484f64-9ec9-409f-b640-18aa0df8b370'::uuid,'01990b94-6131-7af1-92d0-c446eb6b7ea7'::uuid,'Extract Brain','Action','None','Extract Brain. Constitution Saving Throw: DC 15, one creature that is Grappled by the mind flayer''s Tentacles. Failure: 55 (10d10) Piercing damage. Success: Half damage. Failure or Success: If this damage reduces the target to 0 Hit Points, the mind flayer kills it and devours its brain.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('69845c63-c600-4a9f-8c00-cec4451198a3'::uuid,'01990b94-6131-7af1-92d0-c446eb6b7ea7'::uuid,'Tentacles','Action','None','Tentacles. Melee Attack Roll: +7, reach 5 ft. Hit: 22 (4d8 + 4) Psychic damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 14) from all the mind flayer''s tentacles, and the target has the Stunned condition until the grapple ends.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8aca2028-11c2-4f9c-9e15-6c39f5aab4f6'::uuid,'01990b94-6131-7af1-92d0-c446eb6b7ea7'::uuid,'Mind Blast (Recharge 5–6)','Action','None','Mind Blast (Recharge 5–6). Intelligence Saving Throw: DC 15, each creature in a 60-foot Cone. Failure: 31 (6d8 + 4) Psychic damage, and the target has the Stunned condition until the end of the mind flayer''s next turn. Success: Half damage only.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a21dbf31-adfc-4349-98c8-c458c69d2d5f'::uuid,'01990b94-6131-7af1-92d0-c446eb6b7ea7'::uuid,'Spellcasting','Action','None','Spellcasting. The mind flayer casts one of the following spells, requiring no spell components and using Intelligence as the spellcasting ability (spell save DC 15):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('13d22c1d-f443-48c8-85f1-712fc89146a3'::uuid,'01990b94-7c16-7710-87c5-2d3ae837a400'::uuid,'Gore (Recharge 5–6)','Action','None','Gore (Recharge 5–6). Melee Attack Roll: +6, reach 5 ft. Hit: 18 (4d6 + 4) Piercing damage. If the target is a Large or smaller creature and the minotaur moved 10+ feet straight toward it immediately before the hit, the target takes an extra 10 (3d6) Piercing damage and has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ff3460c5-449a-4e59-9306-656b39836795'::uuid,'01990b94-7c16-7710-87c5-2d3ae837a400'::uuid,'Abyssal Glaive','Action','None','Abyssal Glaive. Melee Attack Roll: +6, reach 10 ft. Hit: 10 (1d12 + 4) Slashing damage plus 10 (3d6) Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a2b22399-cb54-468f-b981-dacbecef376a'::uuid,'01990b94-8d90-77a3-835d-59cce5963e26'::uuid,'Gore','Action','Melee','Hit: 11 (2d6 + 4) Piercing damage. If the target is a Large or smaller creature and the skeleton moved 20+ feet straight toward it immediately before the hit, the target takes an extra 9 (2d8) Piercing damage and has the Prone condition.',6,4,'d6',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('d7005272-0a74-43a8-a862-13ace5271dc6'::uuid,'01990b94-8d90-77a3-835d-59cce5963e26'::uuid,'Slam','Action','Melee','Hit: 15 (2d10 + 4) Bludgeoning damage.',6,4,'d10',2,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ac463e3e-f195-4d5f-8a0e-ef2b572b44c5'::uuid,'01990b94-9fd5-7d7e-b792-6249f7f5b476'::uuid,'Hooves','Action','Melee','Hit: 4 (1d4 + 2) Bludgeoning damage.',4,2,'d4',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('d65f7612-cedb-4a03-931b-ac4eb121cf9e'::uuid,'01990b94-b2f3-7eca-b9ec-d5d492803078'::uuid,'Rotting Fist','Action','None','Rotting Fist. Melee Attack Roll: +5, reach 5 ft. Hit: 8 (1d10 + 3) Bludgeoning damage plus 10 (3d6) Necrotic damage. If the target is a creature, it is cursed. While cursed, the target can''t regain Hit Points, its Hit Point maximum doesn''t return to normal when finishing a Long Rest, and its Hit Point maximum decreases by 10 (3d6) every 24 hours that elapse. A creature dies and turns to dust if reduced to 0 Hit Points by this attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f2b738bd-0196-405c-a456-647215cb26d6'::uuid,'01990b94-b2f3-7eca-b9ec-d5d492803078'::uuid,'Dreadful Glare','Action','None','Dreadful Glare. Wisdom Saving Throw: DC 11, one creature the mummy can see within 60 feet. Failure: The target has the Frightened condition until the end of the mummy''s next turn. Success: The target is immune to this mummy''s Dreadful Glare for 24 hours.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f7b94ce7-eeea-43ba-965a-0b036cffe155'::uuid,'01990b94-b2f3-7eca-b9ec-d5d492803078'::uuid,'Multiattack','Action','None','Multiattack. The mummy makes two Rotting Fist attacks and uses Dreadful Glare.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('160bb34d-9d23-47b0-9cad-9f2aa95fa915'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Whirlwind of Sand','Reaction','None','The mummy adds 2 to its AC against the attack, possibly causing the attack to miss, and the mummy teleports up to 60 feet to an unoccupied space it can see. Each creature of its choice that it can see within 5 feet of its destination space has the Blinded condition until the end of the mummy''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'The mummy is hit by an attack roll.',NULL,NULL,NULL,NULL),
	 ('26a162b9-9ed5-45a2-b2d4-ec286a0681ea'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Multiattack','Action','None','Multiattack. The mummy makes one Rotting Fist or Channel Negative Energy attack, and it uses Dreadful Glare.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('536dd5cc-0c93-47db-a142-dd6e0d3da4d9'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Rotting Fist','Action','None','Rotting Fist. Melee Attack Roll: +9, reach 5 ft. Hit: 15 (2d10 + 4) Bludgeoning damage plus 10 (3d6) Necrotic damage. If the target is a creature, it is cursed. While cursed, the target can''t regain Hit Points, it gains no benefit from finishing a Long Rest, and its Hit Point maximum decreases by 10 (3d6) every 24 hours that elapse. A creature dies and turns to dust if reduced to 0 Hit Points by this attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('5acc1d85-e7f0-462a-9c65-12b394e85133'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Dread Command','Legendary','None','The mummy casts Command (level 2 version), using the same spellcasting ability as Spellcasting. The mummy can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('9d4cbe15-f1f8-4a5a-bdc4-72f4dcfca1ad'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Spellcasting','Action','None','Spellcasting. The mummy casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 17, +9 to hit with spell attacks):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('b8b227e5-b772-43e2-a176-0d70c72e5c71'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Dreadful Glare','Action','None','Dreadful Glare. Wisdom Saving Throw: DC 17, one creature the mummy can see within 60 feet. Failure: 25 (6d6 + 4) Psychic damage, and the target has the Paralyzed condition until the end of the mummy''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('cb473035-1ed7-43b4-94be-addf38fa9014'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Channel Negative Energy','Action','None','Channel Negative Energy. Ranged Attack Roll: +9, range 60 ft. Hit: 25 (6d6 + 4) Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d8fe664d-3b42-4897-846d-ce6da9bd20ce'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Necrotic Strike','Legendary','Melee','The mummy makes one Rotting Fist or Channel Negative Energy attack',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ef5abf28-95d9-4ec3-b126-28c483b3e614'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Glare','Legendary','None','The mummy uses Dreadful Glare. The mummy can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('03c11a20-c5fa-45b5-b0a6-a78ecf7fe87c'::uuid,'01990b95-4ced-7982-a41f-3907042c6c55'::uuid,'Multiattack','Action','None','The nalfeshnee makes three Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('69ca667e-206e-4e89-92a0-78df6edc8784'::uuid,'01990b95-4ced-7982-a41f-3907042c6c55'::uuid,'Rend','Action','Melee','Melee Attack Roll: +10, reach 10 ft. Hit: 16 (2d10 + 5) Slashing damage plus 11 (2d10) Force damage.',10,NULL,'d10',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('7316d2c8-9f39-40a6-bca4-5eaa23dee172'::uuid,'01990b95-4ced-7982-a41f-3907042c6c55'::uuid,'Horror Nimbus','Bonus','None','Wisdom Saving Throw: DC 15, each creature in a 15-foot Emanation originating from the nalfeshnee. Failure: 28 (8d6) Psychic damage, and the target has the Frightened condition for 1 minute, until it takes damage, or until it ends its turn with the nalfeshnee out of line of sight. Success: The target is immune to this nalfeshnee''s Horror Nimbus for 24 hours.',NULL,NULL,'d6',8,'Psychic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ca3a4cd5-8a96-42dc-8f21-b265978f914a'::uuid,'01990b95-4ced-7982-a41f-3907042c6c55'::uuid,'Teleport','Action','None','The nalfeshnee teleports up to 120 feet to an unoccupied space it can see.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('e7a4435f-0211-475a-be88-668af5cd1b1d'::uuid,'01990b95-4ced-7982-a41f-3907042c6c55'::uuid,'Pursuit','Reaction','None','Trigger: Another creature the nalfeshnee can see ends its move within 120 feet of the nalfeshnee. Response: The nalfeshnee uses Teleport, but its destination space must be within 10 feet of the triggering creature.',NULL,NULL,NULL,NULL,NULL,NULL,false,'Another creature the nalfeshnee can see ends its move within 120 feet of the nalfeshnee',NULL,NULL,NULL,NULL),
	 ('2ba495fb-f68f-4bc6-b3cf-6264522b8513'::uuid,'01990b95-7fd5-7405-8962-c8e839033bb7'::uuid,'Claw','Action','Melee','Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8 + 4) Slashing damage.',7,4,'d8',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('35cafde2-9a50-4d5d-9ee8-14ca051edff6'::uuid,'01990b95-7fd5-7405-8962-c8e839033bb7'::uuid,'Spellcasting','Action','None','The hag casts one of the following spells, requiring no Material components and using Intelligence as the spellcasting ability (spell save DC 14):',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('555921a8-ac06-400d-b1d1-f7e16be573bb'::uuid,'01990b95-7fd5-7405-8962-c8e839033bb7'::uuid,'Multiattack','Action','Melee','The hag makes two Claw attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a9b81f9f-549b-41b1-8cbc-02e6bfd2bbfb'::uuid,'01990b95-7fd5-7405-8962-c8e839033bb7'::uuid,'Nightmare Haunting','Action','None','While on the Ethereal Plane, the hag casts Dream, using the same spellcasting ability as Spellcasting. Only the hag can serve as the spell''s messenger, and the target must be a creature the hag can see on the Material Plane. The spell fails and is wasted if the target is under the effect of the Protection from Evil and Good spell or within a Magic Circle spell. If the target takes damage from the Dream spell, the target''s Hit Point maximum decreases by an amount equal to that damage. If the spell kills the target, its soul is trapped in the hag''s soul bag, and the target can''t be raised from the dead until its soul is released.',NULL,NULL,NULL,NULL,NULL,1,false,'Requires Soul Bag',NULL,NULL,NULL,NULL),
	 ('bada421c-f172-461c-ba79-dd3bc936ac36'::uuid,'01990b95-9841-7349-990c-db209e9d786e'::uuid,'Hooves','Action','None','Hooves. Melee Attack Roll: +6, reach 5 ft. Hit: 13 (2d8 + 4) Bludgeoning damage plus 10 (3d6) Fire damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f9203d6d-14d0-448f-9436-c62c4af6fc3e'::uuid,'01990b95-9841-7349-990c-db209e9d786e'::uuid,'Ethereal Stride','Action','None','Ethereal Stride. The nightmare and up to three willing creatures within 5 feet of it teleport to the Ethereal Plane from the Material Plane or vice versa.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('6f54cec9-206d-4611-ab13-3c42b7973265'::uuid,'01990b95-a6d5-74fd-8c6a-a63625a64b8f'::uuid,'Rapier','Action','Melee','Hit: 5 (1d8 + 1) Piercing damage.',3,1,'d8',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('d72b0161-5226-4107-a893-84af1214ee37'::uuid,'01990b95-a6d5-74fd-8c6a-a63625a64b8f'::uuid,'Parry','Reaction','Melee','The noble adds 2 to its AC against that attack, possibly causing it to miss.',NULL,NULL,NULL,NULL,NULL,NULL,false,'The noble is hit by a melee attack roll while holding a weapon.',NULL,NULL,NULL,NULL),
	 ('0645ff53-0dd6-4e4b-84f2-28ab0e0f7b3d'::uuid,'01990b95-c060-7c25-96b4-5c0e8c77b13a'::uuid,'Weird Insight','Bonus','None','Wisdom Saving Throw: DC 14, one creature the nothic can see within 120 feet. Failure: The nothic magically learns one fact or secret about the target.',NULL,NULL,NULL,NULL,NULL,6,false,NULL,NULL,NULL,NULL,NULL),
	 ('b80fbb24-6ef3-48e8-a1b1-63267c59abe3'::uuid,'01990b95-c060-7c25-96b4-5c0e8c77b13a'::uuid,'Rotting Gaze','Action','None','Constitution Saving Throw: DC 13, one creature the nothic can see within 120 feet. Failure: 17 (5d6) Necrotic damage. Success: Half damage.',NULL,NULL,'d6',5,'Necrotic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c4d660fc-be86-46c0-b3c8-5f8045b17a7c'::uuid,'01990b95-c060-7c25-96b4-5c0e8c77b13a'::uuid,'Claw','Action','Melee','Melee Attack Roll: +5, reach 5 ft. Hit: 8 (1d10 + 3) Slashing damage.',5,3,'d10',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('d1d14c34-98f9-4c8e-9659-d8032edebf96'::uuid,'01990b95-c060-7c25-96b4-5c0e8c77b13a'::uuid,'Multiattack','Action','Melee','The nothic makes two Claw attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('0b37202c-0275-4be0-b675-9eb8ba328d1b'::uuid,'01990b95-e4af-73f2-b801-4adb75f30777'::uuid,'Split','Reaction','None','While the jelly is Large or Medium and has 10+ Hit Points, it becomes Bloodied or is subjected to Lightning or Slashing damage. The jelly splits into two new Ochre Jellies. Each new jelly is one size smaller than the original jelly and acts on its Initiative. The original jelly''s Hit Points are divided evenly between the new jellies (round down).',NULL,NULL,NULL,NULL,NULL,NULL,false,'While the jelly is Large or Medium and has 10+ Hit Points, it becomes Bloodied or is subjected to Lightning or Slashing damage.',NULL,NULL,NULL,NULL),
	 ('d175a2bf-66a1-41b2-b474-3c0d98944ff1'::uuid,'01990b95-e4af-73f2-b801-4adb75f30777'::uuid,'Pseudopod','Action','None','Pseudopod. Melee Attack Roll: +4, reach 5 ft. Hit: 12 (3d6 + 2) Acid damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0b65347b-3597-483c-89e7-b4e01a8bddc4'::uuid,'01990b96-141a-7c8e-a5ac-ebc1d7950b47'::uuid,'Ink Cloud','Reaction','None','The octopus releases ink that fills a 5-foot Cube centered on itself, and the octopus moves up to its Swim Speed. The Cube is Heavily Obscured for 1 minute or until a strong current or similar effect disperses the ink.',NULL,NULL,NULL,NULL,NULL,1,false,'A creature ends its turn within 5 feet of the octopus while underwater.',NULL,NULL,NULL,NULL),
	 ('2fc39b98-dcd0-46b7-9f5f-6b945ffef925'::uuid,'01990b96-141a-7c8e-a5ac-ebc1d7950b47'::uuid,'Tentacles','Action','None','Tentacles. Melee Attack Roll: +4, reach 5 ft. Hit: 1 Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('5ca59401-c47e-4760-af1f-a6087a9a650f'::uuid,'01990b96-2d76-75a0-8de7-dd29eb59c7c2'::uuid,'Greatclub','Action','None','Greatclub. Melee Attack Roll: +6, reach 5 ft. Hit: 13 (2d8+4) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('93987de6-0304-486f-a678-8e84a62940fa'::uuid,'01990b96-2d76-75a0-8de7-dd29eb59c7c2'::uuid,'Javelin','Action','None','Javelin. Melee or Ranged Attack Roll: +6, reach 5 ft. or range 30/120 ft. Hit: 11 (2d6+4) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d78d4b81-37c9-478a-a4eb-ed470f0fa478'::uuid,'01990b96-40d7-77e8-800f-70598f4d229f'::uuid,'Slam','Action','None','Slam. Melee Attack Roll: +6, reach 5 ft. Hit: 13 (2d8 + 4) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('50cac6c6-ce11-4e33-a710-6de24d2a3d02'::uuid,'01990b96-6e90-76e8-b678-74bb26715be0'::uuid,'Spellcasting','Action','None','Spellcasting. The oni casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 13):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('50cbfbf1-3c97-4df8-bb20-c911a5bf38a0'::uuid,'01990b96-6e90-76e8-b678-74bb26715be0'::uuid,'Shape-Shift','Action','None','Shape-Shift. The oni shape-shifts into a Small or Medium Humanoid or a Large Giant, or it returns to its true form. Other than its size, its game statistics are the same in each form. Any equipment it is wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('806e2346-307d-4993-8515-e4b25b95ffef'::uuid,'01990b96-6e90-76e8-b678-74bb26715be0'::uuid,'Multiattack','Action','None','Multiattack. The oni makes two Claw or Nightmare Ray attacks. It can replace one attack with a use of Spellcasting.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('879ab768-23fe-4bcd-8446-3e185f4bf465'::uuid,'01990b96-6e90-76e8-b678-74bb26715be0'::uuid,'Nightmare Ray','Action','None','Nightmare Ray. Ranged Attack Roll: +5, range 60 ft. Hit: 9 (2d6 + 2) Psychic damage, and the target has the Frightened condition until the start of the oni''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('937f6475-6601-42e5-846f-7c53a26ff488'::uuid,'01990b96-6e90-76e8-b678-74bb26715be0'::uuid,'Invisibility','Bonus','None','The oni casts Invisibility on itself, requiring no spell components and using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('af28af60-2d2c-4943-9b54-533198312f43'::uuid,'01990b96-6e90-76e8-b678-74bb26715be0'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +7, reach 10 ft. Hit: 10 (1d12 + 4) Slashing damage plus 9 (2d8) Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('639f9b63-82ea-4bb3-bf6c-d284b2b5445e'::uuid,'01990b96-8ea6-7451-93c7-c16bef0e1a08'::uuid,'Tentacle Slam','Action','None','Tentacle Slam. Constitution Saving Throw: DC 14, each creature Grappled by the otyugh. Failure: 16 (3d8 + 3) Bludgeoning damage, and the target has the Stunned condition until the start of the otyugh''s next turn. Success: Half damage only.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('90857d59-12b9-48dd-8b1c-87acce857c38'::uuid,'01990b96-8ea6-7451-93c7-c16bef0e1a08'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +6, reach 5 ft. Hit: 12 (2d8 + 3) Piercing damage, and the target has the Poisoned condition. Whenever the Poisoned target finishes a Long Rest, it is subjected to the following effect. Constitution Saving Throw: DC 15. Failure: The target''s Hit Point maximum decreases by 5 (1d10) and doesn''t return to normal until the Poisoned condition ends on the target. Success: The Poisoned condition ends.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('dd77930d-7b00-4fc5-a0f9-aba2387d12dc'::uuid,'01990b96-8ea6-7451-93c7-c16bef0e1a08'::uuid,'Tentacle','Action','None','Tentacle. Melee Attack Roll: +6, reach 10 ft. Hit: 12 (2d8 + 3) Piercing damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 13) from one of two tentacles.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('faeaf662-1a2e-4d99-8c30-77841aa57d09'::uuid,'01990b96-8ea6-7451-93c7-c16bef0e1a08'::uuid,'Multiattack','Action','None','Multiattack. The otyugh makes one Bite attack and two Tentacle attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2c6a7bf7-e2a4-43b7-9d6b-d71f8c387259'::uuid,'01990b96-ae8b-741f-9bf9-785e774fecbf'::uuid,'Talons','Action','None','Talons. Melee Attack Roll: +3, reach 5 ft. Hit: 1 Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('013b4487-cadd-4d47-ac0f-745a14e6fc6f'::uuid,'01990b96-b9bc-7d03-bf0d-cf239c826eb2'::uuid,'Multiattack','Action','None','Multiattack. The owlbear makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
