	 ('3ab6d5f0-d380-4795-ba2b-09f8577fb7eb'::uuid,'01990b97-2583-7b20-a7dc-0ef5472878c6'::uuid,'Multiattack','Action','None','Multiattack. The spider makes two Bite attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f299375b-180b-48c4-887a-0995e6e75ce7'::uuid,'01990b97-2583-7b20-a7dc-0ef5472878c6'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +5, reach 5 ft. Hit: 8 (1d10 + 3) Piercing damage plus 9 (2d8) Poison damage. If this damage reduces the target to 0 Hit Points, the target becomes Stable, and it has the Poisoned condition for 1 hour. While Poisoned, the target also has the Paralyzed condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2e5d67b9-7b4f-4f32-9748-f30b4477ad7b'::uuid,'01990b97-3aae-71fe-99a0-563abef3843b'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +5 (with Advantage if the target doesn''t have all its Hit Points), reach 5 ft. Hit: 1 Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0ccb4ad3-0a11-45f8-b6fa-4b0e87e4bd50'::uuid,'01990b97-4bb7-76fc-af4f-8cda264da267'::uuid,'Enthralling Panache','Action','None','Wisdom Saving Throw: DC 12, one creature the pirate can see within 30 feet. Failure: The target has the Charmed condition until the start of the pirate''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('6d5ed0af-7f91-4dc3-8407-ea3be1877bd0'::uuid,'01990b97-4bb7-76fc-af4f-8cda264da267'::uuid,'Dagger','Action','Melee','Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4 + 3) Piercing damage.',5,3,'d4',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('feb907ee-e00c-425a-bf62-d4f1aed4163e'::uuid,'01990b97-4bb7-76fc-af4f-8cda264da267'::uuid,'Multiattack','Action','Melee','The pirate makes two Dagger attacks. It can replace one of these attacks with a use of Enthralling Panache.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3d499409-c0df-4ba4-982d-728959d9a337'::uuid,'01990b97-7467-78e1-9bde-38e3da78c417'::uuid,'Multiattack','Action','None','Multiattack. The pirate makes three attacks, using Rapier or Pistol in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('69e4b374-c150-4cce-9681-3f052b0084e2'::uuid,'01990b97-7467-78e1-9bde-38e3da78c417'::uuid,'Rapier','Action','None','Rapier. Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8+4) Piercing damage, and the pirate has Advantage on the next attack roll it makes before the end of this turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
