	 ('e19f92c9-1627-45e0-9ead-8918de79c78a'::uuid,'01990b97-7467-78e1-9bde-38e3da78c417'::uuid,'Pistol','Action','None','Pistol. Ranged Attack Roll: +7, range 30/90 ft. Hit: 15 (2d10+ 4) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('f687b202-ccef-49b0-9ed9-09b3e1591542'::uuid,'01990b97-7467-78e1-9bde-38e3da78c417'::uuid,'Riposte','Reaction','None','The pirate adds 3 to its AC against the triggering attack. On a miss, the pirate makes one Rapier attack against the triggering creature if within range.',NULL,NULL,NULL,NULL,NULL,NULL,false,'The pirate is hit by a melee attack roll while holding a weapon.',NULL,NULL,NULL,NULL),
	 ('1e294a54-f592-4bd6-be58-242524ae4d43'::uuid,'01990b97-aa44-7ab6-bef5-4beac1312331'::uuid,'Fiery Mace','Action','Melee','Hit: 22 (4d6 + 8) Force damage plus 21 (6d6) Fire damage.',14,8,'d6',4,'Force',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5f2e6d1c-dbdd-48b1-9f26-d840c6835481'::uuid,'01990b97-aa44-7ab6-bef5-4beac1312331'::uuid,'Hellfire Spellcasting','Action','None','The pit fiend casts Fireball (level 5 version) twice, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 21). It can replace one Fireball with Hold Monster (level 7 version) or Wall of Fire.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('de6c07dc-503f-4933-8a3d-2016013f10f5'::uuid,'01990b97-aa44-7ab6-bef5-4beac1312331'::uuid,'Multiattack','Action','None','The pit fiend makes one Bite attack, two Devilish Claw attacks, and one Fiery Mace attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('e578e5b6-64c4-4cba-a80b-ecf2b2563dd6'::uuid,'01990b97-aa44-7ab6-bef5-4beac1312331'::uuid,'Devilish Claw','Action','Melee','Hit: 26 (4d8 + 8) Necrotic damage.',14,8,'d8',4,'Necrotic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ea4b08a4-5d3c-40aa-a13d-d8c0a642dd74'::uuid,'01990b97-aa44-7ab6-bef5-4beac1312331'::uuid,'Bite','Action','Melee','Hit: 18 (3d6 + 8) Piercing damage. If the target is a creature, it must make the following saving throw. Constitution Saving Throw: DC 21. Failure: The target has the Poisoned condition. While Poisoned, the target can''t regain Hit Points and takes 21 (6d6) Poison damage at the start of each of its turns, and it repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.',14,8,'d6',3,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('15a6d88b-49d2-4bbb-b169-c5e97281eb15'::uuid,'01990b97-fc76-72a6-afa9-1b7baa7356e7'::uuid,'Holy Burst','Action','None','Dexterity Saving Throw: DC 20, each enemy in a 20-foot-radius Sphere centered on a point the planetar can see within 120 feet. Failure: 24 (7d6) Radiant damage. Success: Half damage.',NULL,NULL,'d6',7,'Radiant',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('36be0816-ca6a-48c8-bd77-772dc0fd50ad'::uuid,'01990b97-fc76-72a6-afa9-1b7baa7356e7'::uuid,'Radiant Sword','Action','Melee','Melee Attack Roll: +12, reach 10 ft. Hit: 14 (2d6 + 7) Slashing damage plus 18 (4d8) Radiant damage.',12,7,'d6',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5c74e8e4-f91c-49ad-8961-9833fdfa4a02'::uuid,'01990b97-fc76-72a6-afa9-1b7baa7356e7'::uuid,'Spellcasting','Action','None','The planetar casts one of the following spells, requiring no Material components and using Charisma as spellcasting ability (spell save DC 20):',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('7c6de67c-b32a-489a-92ab-f89e100fc0ff'::uuid,'01990b97-fc76-72a6-afa9-1b7baa7356e7'::uuid,'Divine Aid','Bonus','None','The planetar casts Cure Wounds, Invisibility, Lesser Restoration, or Remove Curse, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,2,false,NULL,NULL,NULL,NULL,NULL);
