	 ('764b9e53-1068-4658-a2ae-3dd22191870d'::uuid,'01990b98-537e-771e-9e74-036bc64ccefc'::uuid,'Spellcasting','Action','None','Spellcasting. The priest casts one of the following spells, using Wisdom as the spellcasting ability:',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('bf318333-7788-4f69-8e70-673cfa041261'::uuid,'01990b98-537e-771e-9e74-036bc64ccefc'::uuid,'Mace','Action','None','Mace. Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Bludgeoning damage plus 5 (2d4) Radiant damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
