	 ('a1bb4c75-fe25-407f-9fec-756dfa0f8923'::uuid,'01990b98-66d1-7646-a214-1590f4d6401b'::uuid,'Spellcasting','Action','None','Spellcasting. The priest casts one of the following spells, using Wisdom as the spellcasting ability:',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a77d2bdb-2f98-49b2-b2ee-f150f4810bb2'::uuid,'01990b98-66d1-7646-a214-1590f4d6401b'::uuid,'Divine Aid','Bonus','None','The priest casts Bless, Healing Word, or Sanctuary, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,1,false,NULL,NULL,NULL,NULL,NULL),
	 ('acb033b6-cdcb-4ec1-8cc1-37d4d3b05f17'::uuid,'01990b98-66d1-7646-a214-1590f4d6401b'::uuid,'Radiant Flame','Action','None','Radiant Flame. Ranged Attack Roll: +4, range 60 ft. Hit: 7 (2d6) Radiant damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('1fe652fb-6bc6-40e9-b69d-abf4df259213'::uuid,'01990b98-8592-7920-935d-97867b9345cb'::uuid,'Sting','Action','None','Constitution Saving Throw: DC 12, one creature the pseudodragon can see within 5 feet. Failure: 5 (2d4) Poison damage, and the target has the Poisoned condition for 1 hour. While Poisoned, the target also has the Unconscious condition, which ends early if the target takes damage or a creature within 5 feet of it takes an action to wake it.',NULL,NULL,'d4',2,'Poison',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3fa07b4d-5fdc-452e-8739-4de80ec3b1e3'::uuid,'01990b98-8592-7920-935d-97867b9345cb'::uuid,'Bite','Action','Melee','Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Piercing damage.',4,2,'d4',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b649f258-3142-4b7a-adc1-57ccd8cd511f'::uuid,'01990b98-8592-7920-935d-97867b9345cb'::uuid,'Multiattack','Action','None','The pseudodragon makes two Bite attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ee3d4e5b-94dd-43c6-a29a-e85b326c1a26'::uuid,'01990b98-9e5a-72db-b8ca-65afee882069'::uuid,'Bite','Action','Melee','Hit: 6 (1d8 + 2) Piercing damage.',4,2,'d8',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('0d286fb8-dfcd-444e-a898-203c7675dd31'::uuid,'01990b98-c8c2-770c-a59a-a85a42827d1e'::uuid,'Multiattack','Action','None','The worm makes one Bite attack and one Tail Stinger attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('4893ff06-c81b-4f07-8e79-649708ff9cb3'::uuid,'01990b98-c8c2-770c-a59a-a85a42827d1e'::uuid,'Tail Stinger','Action','Melee','Hit: 16 (2d6 + 9) Piercing damage plus 35 (10d6) Poison damage.',14,9,'d6',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('65c67d17-d4ab-4303-9901-27288af94756'::uuid,'01990b98-c8c2-770c-a59a-a85a42827d1e'::uuid,'Bite','Action','Melee','Hit: 22 (3d8 + 9) Piercing damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 19), and it has the Restrained condition until the grapple ends.',14,9,'d8',3,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('8838b936-dfd3-4dc6-a880-203753f04406'::uuid,'01990b98-c8c2-770c-a59a-a85a42827d1e'::uuid,'Swallow','Bonus','None','Strength Saving Throw: DC 19, one Large or smaller creature Grappled by the worm (it can have up to three creatures swallowed at a time). Failure: The target is swallowed by the worm, and the Grappled condition ends. A swallowed creature has the Blinded and Restrained conditions, has Total Cover against attacks and other effects outside the worm, and takes 17 (5d6) Acid damage at the start of each of the worm''s turns. If the worm takes 30 damage or more on a single turn from a creature inside it, the worm must succeed on a DC 21 Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, each of which falls in a space within 5 feet of the worm and has the Prone condition. If the worm dies, any swallowed creature no longer has the Restrained condition and can escape from the corpse using 20 feet of movement, exiting Prone.',NULL,NULL,'d6',5,'Acid',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3aa5b7a1-f140-4bbf-a75b-39dfcd0f861b'::uuid,'01990b99-0193-7ff5-af07-4e6b690c14ab'::uuid,'Scare','Action','None','Failure: The target has the Frightened condition. At the end of each of its turns, the target repeats the save, ending the effect on itself on a success. After 1 minute, it succeeds automatically.',NULL,NULL,NULL,NULL,NULL,1,false,NULL,NULL,NULL,NULL,NULL),
	 ('7f849b87-e8f2-430c-b0b1-78279e886aa9'::uuid,'01990b99-0193-7ff5-af07-4e6b690c14ab'::uuid,'Rend','Action','Melee','Hit: 5 (1d4 + 3) Slashing damage, and the target has the Poisoned condition until the start of the quasit''s next turn.',5,3,'d4',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('dca52256-9fd8-4627-b691-5a8f2d6051e7'::uuid,'01990b99-0193-7ff5-af07-4e6b690c14ab'::uuid,'Shape-Shift','Action','None','The quasit shape-shifts to resemble a bat (Speed 10 ft., Fly 40 ft.), a centipede (40 ft., Climb 40 ft.), or a toad (40 ft., Swim 40 ft.), or it returns to its true form. Its statistics are the same in each form, except for its Speed. Any equipment it''s wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('f95f78c5-24bb-41e6-8ff2-467a1c52f56a'::uuid,'01990b99-0193-7ff5-af07-4e6b690c14ab'::uuid,'Invisibility','Action','None','The quasit casts Invisibility on itself, requiring no spell components and using Charisma as the spellcasting ability.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('1bdea25e-e3c5-4fed-9a06-a4da5fc8d277'::uuid,'01990b99-2af4-77f3-a870-49c221aed164'::uuid,'Spellcasting','Action','None','The rakshasa casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 18):',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('85546931-fbaa-448f-8d3a-a2a9879c90a8'::uuid,'01990b99-2af4-77f3-a870-49c221aed164'::uuid,'Cursed Touch','Action','Melee','Melee Attack Roll: +10, reach 5 ft. Hit: 12 (2d6 + 5) Slashing damage plus 19 (3d12) Necrotic damage. If the target is a creature, it is cursed. While cursed, the target gains no benefit from finishing a Short or Long Rest.',10,NULL,'d6',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('98ff6910-fc1a-4b85-81de-163b3df1d6ca'::uuid,'01990b99-2af4-77f3-a870-49c221aed164'::uuid,'Multiattack','Action','None','The rakshasa makes three Cursed Touch attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('d808f157-b152-4e36-92b9-1d2fe32dd73e'::uuid,'01990b99-2af4-77f3-a870-49c221aed164'::uuid,'Baleful Command','Action','None','Wisdom Saving Throw: DC 18, each enemy in a 30-foot Emanation originating from the rakshasa. Failure: 28 (8d6) Psychic damage, and the target has the Frightened and Incapacitated conditions until the start of the rakshasa''s next turn.',NULL,NULL,'d6',8,'Psychic',5,false,NULL,NULL,NULL,NULL,NULL);
