	 ('efc606c6-7bbf-4161-8230-7d5a9f5d1fb1'::uuid,'01990b99-44b3-76cb-a0a5-43abbb88098f'::uuid,'Beak','Action','None','Beak. Melee Attack Roll: +4, reach 5 ft. Hit: 1 Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('65d9c758-b345-4494-b89c-1df6955b5895'::uuid,'01990b99-5457-70dc-9bff-14b8eed31fd4'::uuid,'Multiattack','Action','None','The dragon makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('7009444b-627a-4247-bef1-9e9d6eb56f11'::uuid,'01990b99-5457-70dc-9bff-14b8eed31fd4'::uuid,'Rend','Action','Melee','Melee Attack Roll: +6, reach 5 ft. Hit: 9 (1d10 + 4) Slashing damage plus 3 (1d6) Fire damage.',6,4,'d10',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('9d531a6e-4318-4f5e-ad24-75da45bebcff'::uuid,'01990b99-5457-70dc-9bff-14b8eed31fd4'::uuid,'Fire Breath','Action','Ranged','Dexterity Saving Throw: DC 13, each creature in a 15-foot Cone. Failure: 24 (7d6) Fire damage. Success: Half damage.',NULL,NULL,'d6',7,'Fire',5,false,NULL,NULL,NULL,NULL,NULL),
	 ('1df292da-c3f0-40db-a1d4-4ba333a9cf7d'::uuid,'01990b99-7329-775d-9640-522d26f93c52'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 7 (2d4 + 2) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('17b3b63d-04f0-4438-9612-a09a5840003d'::uuid,'01990b99-96a5-73c1-81f5-9cc648ade295'::uuid,'Bite','Action','Melee','Hit: 18 (2d10 + 7) Piercing damage plus 14 (4d6) Fire damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 17), and it has the Restrained condition until the grapple ends.',11,NULL,'d10',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a043a400-b991-4019-85ac-7e38777ee194'::uuid,'01990b99-96a5-73c1-81f5-9cc648ade295'::uuid,'Swallow','Bonus','None','Strength Saving Throw: DC 19, one Large or smaller creature Grappled by the remorhaz (it can have up to two creatures swallowed at a time). Failure: The target is swallowed by the remorhaz, and the Grappled condition ends. A swallowed creature has the Blinded and Restrained conditions, it has Total Cover against attacks and other effects outside the remorhaz, and it takes 10 (3d6) Acid damage plus 10 (3d6) Fire damage at the start of each of the remorhaz''s turns. If the remorhaz takes 30 damage or more on a single turn from a creature inside it, the remorhaz must succeed on a DC 15 Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, each of which falls in a space within 5 feet of the remorhaz and has the Prone condition. If the remorhaz dies, any swallowed creature no longer has the Restrained condition and can escape from the corpse by using 15 feet of movement, exiting Prone.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c795cc8b-2267-4260-97ae-7c3177c96ca1'::uuid,'01990b9a-f057-7ac2-ba2f-cf5e1d6c5a52'::uuid,'Shortsword','Action','None','Shortsword. Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage, plus 10 (3d6) Piercing damage if the attack was made with Advantage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('1a04377a-ae1e-4476-9096-14f9a59aeafd'::uuid,'01990b99-a99b-747a-9d7b-c3e2111acdd8'::uuid,'Gore','Action','Melee','Hit: 14 (2d8 + 5) Piercing damage. If target is a Large or smaller creature and the rhinoceros moved 20+ feet straight toward it immediately before the hit, the target takes an extra 9 (2d8) Piercing damage and has the Prone condition.',7,5,'d8',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('89a80a31-aee9-4fe7-868b-f6f4b91d79bf'::uuid,'01990b99-b3b1-76b2-a0d0-e154e8b8d0cf'::uuid,'Hooves','Action','None','Hooves. Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('6ba6a24f-7c4b-4c11-a302-4db531afdfb0'::uuid,'01990b99-ca6e-7ce5-a6ce-b0499dd693ea'::uuid,'Swoop (Recharge 5–6)','Bonus','None','Swoop (Recharge 5–6). If the roc has a creature Grappled, the roc flies up to half its Fly Speed without provoking Opportunity Attacks and drops that creature.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8bfb1610-9fc3-4921-99a7-d6972ca1babe'::uuid,'01990b99-ca6e-7ce5-a6ce-b0499dd693ea'::uuid,'Multiattack','Action','None','The roc makes two Beak attacks. It can replace one attack with a Talons attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('9a590d97-1b71-471f-bec1-987f64779e38'::uuid,'01990b99-ca6e-7ce5-a6ce-b0499dd693ea'::uuid,'Talons','Action','Melee','Melee Attack Roll: +13, reach 5 ft. Hit: 23 (4d6 + 9) Slashing damage. If the target is a Huge or smaller creature, it has the Grappled condition (escape DC 19) from both talons, and it has the Restrained condition until the grapple ends.',13,9,'d6',4,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('cec09416-fdc2-43f0-82fd-8b4da49d0141'::uuid,'01990b99-ca6e-7ce5-a6ce-b0499dd693ea'::uuid,'Beak','Action','Melee','Melee Attack Roll: +13, reach 10 ft. Hit: 28 (3d12 + 9) Piercing damage.',13,9,'d12',3,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('396bdb4b-c2c5-4a6b-8048-fd5fb4af0819'::uuid,'01990b99-eb5a-7bff-a763-04c86a9ca761'::uuid,'Multiattack','Action','None','Multiattack. The roper makes two Tentacle attacks, uses Reel, and makes two Bite attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('47a237e6-c317-4cf9-b998-92ceffff1ad7'::uuid,'01990b99-eb5a-7bff-a763-04c86a9ca761'::uuid,'Tentacle','Action','None','Tentacle. Melee Attack Roll: +7, reach 60 ft. Hit: The target has the Grappled condition (escape DC 14) from one of six tentacles, and the target has the Poisoned condition until the grapple ends. The tentacle can be damaged, freeing a creature it has Grappled when destroyed (AC 20, HP 10, Immunity to Poison and Psychic damage). Damaging the tentacle deals no damage to the roper, and a destroyed tentacle regrows at the start of the roper''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('80b752cc-a557-4f94-9bf2-406466282318'::uuid,'01990b99-eb5a-7bff-a763-04c86a9ca761'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +7, reach 5 ft. Hit: 17 (3d8 + 4) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f523c3e9-5928-4c72-9d44-97e35da65822'::uuid,'01990b99-eb5a-7bff-a763-04c86a9ca761'::uuid,'Reel','Action','None','Reel. The roper pulls each creature Grappled by it up to 30 feet straight toward it.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2b8b9431-39e3-41ff-a049-10ae541f9ae1'::uuid,'01990b9a-0d53-779a-9bee-d3b2886d72d1'::uuid,'Destroy Metal','Action','None','The rust monster touches a nonmagical metal object within 5 feet of itself that isn''t being worn or carried. The touch destroys a 1-foot Cube of the object.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('3035d4ce-ef77-44b0-9938-6570c665cb06'::uuid,'01990b9a-0d53-779a-9bee-d3b2886d72d1'::uuid,'Multiattack','Action','None','The rust monster makes one Bite attack and uses Antennae twice.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('e869604e-c2eb-4c80-82c8-ff69f43d745d'::uuid,'01990b9a-0d53-779a-9bee-d3b2886d72d1'::uuid,'Antennae','Action','None','The rust monster targets one nonmagical metal object—armor or a weapon—worn or carried by a creature within 5 feet of itself. Dexterity Saving Throw: DC 11, the creature with the object. Failure: The object takes a -1 penalty to the AC it offers (armor) or to its attack rolls (weapon). Armor is destroyed if the penalty reduces its AC to 10, and a weapon is destroyed if its penalty reaches -5. The penalty can be removed by casting the Mending spell on the armor or weapon.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('e9a2714e-31bd-4ab0-90f0-12297b875603'::uuid,'01990b9a-0d53-779a-9bee-d3b2886d72d1'::uuid,'Reflexive Antennae','Reaction','None','Trigger: An attack roll hits the rust monster. Response: The rust monster uses Antennae.',NULL,NULL,NULL,NULL,NULL,NULL,false,'An attack roll hits the rust monster',NULL,NULL,NULL,NULL),
	 ('ffe8f2d0-c76b-41ed-9f65-88b8ea94576b'::uuid,'01990b9a-0d53-779a-9bee-d3b2886d72d1'::uuid,'Bite','Action','Melee','Melee Attack Roll: +3, reach 5 ft. Hit: 5 (1d8 + 1) Piercing damage.',3,1,'d8',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('146e7d0b-755b-43bf-9ad3-923155643d62'::uuid,'01990b9a-283f-7289-9843-8c0eab8e2103'::uuid,'Nimble Escape','Bonus','None','The tiger takes the Disengage or Hide action.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('32e1098b-5abb-4f1b-9bf6-075b4988677f'::uuid,'01990b9a-283f-7289-9843-8c0eab8e2103'::uuid,'Multiattack','Action','None','Multiattack. The tiger makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('63faf883-e015-4b6b-a03f-7ec0ebd0b8ea'::uuid,'01990b9a-283f-7289-9843-8c0eab8e2103'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +6, reach 5 ft. Hit: 11 (2d6 + 4) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('ac2bebf2-ccbe-48e3-9a67-905e66b82cd5'::uuid,'01990b9a-68a7-7a84-a4e0-ea7d9ad79cdc'::uuid,'Claw','Action','Melee','Melee Attack Roll: +3, reach 5 ft. Hit: 4 (1d6 + 1) Slashing damage.',3,1,'d6',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c4c642a7-eca3-4a43-8394-f374e652c7b9'::uuid,'01990b9a-68a7-7a84-a4e0-ea7d9ad79cdc'::uuid,'Aquatic Charge','Bonus','None','The sahuagin swims up to its Swim Speed straight toward an enemy it can see.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('f4fb5b42-8dba-4b73-ac64-cec6385add9f'::uuid,'01990b9a-68a7-7a84-a4e0-ea7d9ad79cdc'::uuid,'Multiattack','Action','None','The sahuagin makes two Claw attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('02a5499a-c15d-44a6-8cf4-ec42cd17d803'::uuid,'01990b9a-8758-7f95-a445-be36736917cf'::uuid,'Multiattack','Action','None','Multiattack. The salamander makes two Flame Spear attacks. It can replace one attack with a use of Constrict.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f17f1b10-8705-429c-ad86-307898ab60f9'::uuid,'01990b9a-8758-7f95-a445-be36736917cf'::uuid,'Constrict','Action','None','Constrict. Strength Saving Throw: DC 15, one Large or smaller creature the salamander can see within 10 feet. Failure: 11 (2d6 + 4) Bludgeoning damage plus 7 (2d6) Fire damage. The target has the Grappled condition (escape DC 14), and it has the Restrained condition until the grapple ends.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f2adcef3-53cc-417f-b7a6-76e6b561d84a'::uuid,'01990b9a-8758-7f95-a445-be36736917cf'::uuid,'Flame Spear','Action','None','Flame Spear. Melee or Ranged Attack Roll: +7, reach 5 ft. or range 20/60 ft. Hit: 13 (2d8 + 4) Piercing damage plus 7 (2d6) Fire damage. Hit or Miss: The spear magically returns to the salamander''s hand immediately after a ranged attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('07748d4e-7f70-4439-96e4-13c9b28089ad'::uuid,'01990b9a-af9d-7b43-9798-39e69b39e965'::uuid,'Mockery','Action','None','Mockery. Wisdom Saving Throw: DC 12, one creature the satyr can see within 90 feet. Failure: 5 (1d6 + 2) Psychic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f965a10d-ffba-4e1f-917f-00344eea7bd0'::uuid,'01990b9a-af9d-7b43-9798-39e69b39e965'::uuid,'Hooves','Action','None','Hooves. Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4 + 3) Bludgeoning damage. If the target is a Medium or smaller creature, the satyr pushes the target up to 10 feet straight away from itself.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f1aea69a-4af0-4c57-b649-56f832bb3ef3'::uuid,'01990b9a-bf98-79ad-ae27-379d3f9b57ed'::uuid,'Sting','Action','None','Sting. Melee Attack Roll: +2, reach 5 ft. Hit: 1 Piercing damage plus 3 (1d6) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('08555acc-a5f0-445c-a4e8-385194cdce0a'::uuid,'01990b9a-d1d6-7283-83d9-68dca445683a'::uuid,'Longbow','Action','Ranged','Ranged Attack Roll: +4, range 150/600 ft. Hit: 6 (1d8 + 2) Piercing damage.',4,2,'d8',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5ee3840b-8827-4d91-b6c4-d290596a3027'::uuid,'01990b9a-d1d6-7283-83d9-68dca445683a'::uuid,'Shortsword','Action','Melee','Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage.',4,2,'d6',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a74b566e-d330-4782-a98f-23e0dd8f9e41'::uuid,'01990b9a-d1d6-7283-83d9-68dca445683a'::uuid,'Multiattack','Action','None','The scout makes two attacks, using Shortsword and Longbow in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('1f317533-c324-4d30-8d3f-a59a7d99b951'::uuid,'01990b9a-f057-7ac2-ba2f-cf5e1d6c5a52'::uuid,'Multiattack','Action','None','Multiattack. The scout makes two attacks, using Shortsword or Longbow in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('594a9d42-4d01-44a7-aca2-525287355b4f'::uuid,'01990b9a-f057-7ac2-ba2f-cf5e1d6c5a52'::uuid,'Longbow','Action','None','Longbow. Ranged Attack Roll: +5, range 150/600 ft. Hit: 7 (1d8 + 3) Piercing damage, plus 10 (3d6) Piercing damage if the attack was made with Advantage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('819372a7-c842-40ea-86dd-a16383d9690d'::uuid,'01990b9a-f057-7ac2-ba2f-cf5e1d6c5a52'::uuid,'Uncanny Dodge','Reaction','None','The scout halves the damage (round down) it takes from that attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'The scout is hit by an attack roll.',NULL,NULL,NULL,NULL),
	 ('c47174a6-e01b-42f2-8db9-e982a2a27c60'::uuid,'01990b9a-f057-7ac2-ba2f-cf5e1d6c5a52'::uuid,'Aim','Bonus','None','The scout has Advantage on the next attack roll it makes during the current turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ac159c80-9724-4670-b74c-380e032ab9b5'::uuid,'01990b9b-1034-7f2b-8d19-80002f454224'::uuid,'Death Glare','Action','None','Wisdom Saving Throw: DC 11, one Frightened creature the hag can see within 30 feet. Failure: If the target has 20 Hit Points or fewer, it drops to 0 Hit Points. Otherwise, the target takes 13 (3d8) Psychic damage.',NULL,NULL,'d8',3,'Psychic',6,false,NULL,NULL,NULL,NULL,NULL),
	 ('aca67401-ceec-4a4f-93cb-a5014f02fcf6'::uuid,'01990b9b-1034-7f2b-8d19-80002f454224'::uuid,'Illusory Appearance','Action','None','The hag casts Disguise Self, using Constitution as the spellcasting ability (spell save DC 13). The spell''s duration is 24 hours.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('d767f697-f9a2-4535-b299-55880c8ec849'::uuid,'01990b9b-1034-7f2b-8d19-80002f454224'::uuid,'Claw','Action','Melee','Hit: 10 (2d6 + 3) Slashing damage.',5,3,'d6',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('76c52051-e13e-4dea-9af1-a4f02903f505'::uuid,'01990b9b-1e93-7b5b-a424-19eba0ef381e'::uuid,'Bubble Dash','Action','None','While underwater, the seahorse moves up to its Swim Speed without provoking Opportunity Attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a5f4beda-7e16-46f1-9cca-295e1220d4a8'::uuid,'01990b9b-3785-7e2b-af68-7fe6fce62bb8'::uuid,'Draining Swipe','Action','Melee','Hit: 5 (1d6 + 2) Necrotic damage, and the target''s Strength score decreases by 1d4. The target dies if this reduces that score to 0. If a Humanoid is slain by this attack, a Shadow rises from the corpse 1d4 hours later.',4,2,'d6',1,'Necrotic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b17623d4-b4e7-4415-bf60-5e9d81eab03f'::uuid,'01990b9b-3785-7e2b-af68-7fe6fce62bb8'::uuid,'Shadow Stealth','Bonus','None','While in Dim Light or Darkness, the shadow takes the Hide action.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('7f288996-bcc4-496c-862d-684f89e7b6a4'::uuid,'01990b9b-6338-7573-8ffc-68f87abc8781'::uuid,'Engulf','Action','None','Engulf. Strength Saving Throw: DC 15, one Medium or smaller creature within 5 feet. Failure: The target is pulled into the shambling mound''s space and has the Grappled condition (escape DC 14). Until the grapple ends, the target has the Blinded and Restrained conditions, and it takes 10 (3d6) Lightning damage at the start of each of its turns. When the shambling mound moves, the Grappled target moves with it, costing it no extra movement. The shambling mound can have only one creature Grappled by this action at a time.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('95ec99a8-5786-4195-9989-9123259cc279'::uuid,'01990b9b-6338-7573-8ffc-68f87abc8781'::uuid,'Charged Tendril','Action','None','Charged Tendril. Melee Attack Roll: +7, reach 10 ft. Hit: 7 (1d6 + 4) Bludgeoning damage plus 5 (2d4) Lightning damage. If the target is a Medium or smaller creature, the shambling mound pulls the target 5 feet straight toward itself.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f27180e6-29e0-4ce0-b30b-588e0f70cfde'::uuid,'01990b9b-6338-7573-8ffc-68f87abc8781'::uuid,'Multiattack','Action','None','Multiattack. The shambling mound makes three Charged Tendril attacks. It can replace one attack with a use of Engulf.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('32751f10-9776-4fea-92fc-339f71f41eed'::uuid,'01990b9b-84af-7d50-8cd0-8e0a87af88e7'::uuid,'Multiattack','Action','Melee','The guardian makes two Fist attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('4a7a7189-7efe-4ec7-9ba5-9771db9292de'::uuid,'01990b9b-84af-7d50-8cd0-8e0a87af88e7'::uuid,'Fist','Action','Melee','Melee Attack Roll: +7, reach 10 ft. Hit: 11 (2d6 + 4) Bludgeoning damage plus 7 (2d6) Force damage.',7,NULL,'d6',2,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a7138906-94c4-4163-8182-7d584f28c6e3'::uuid,'01990b9b-84af-7d50-8cd0-8e0a87af88e7'::uuid,'Protection','Reaction','None','The wearer gains a +5 bonus to AC, including against the triggering attack and possibly causing it to miss, until the start of the guardian''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'An attack roll hits the wearer of the guardian''s amulet while the wearer is within 5 feet of the guardian.',NULL,NULL,NULL,NULL),
	 ('33b8fc82-8bf8-4afa-a5f6-0082d6f15baf'::uuid,'01990b9b-8bc5-776b-9797-b3230e576d96'::uuid,'Shriek','Reaction','None','The shrieker emits a shriek audible within 300 feet of itself for 1 minute or until the shrieker dies.',NULL,NULL,NULL,NULL,NULL,NULL,false,'A creature or a source of Bright Light moves within 30 feet of the shrieker',NULL,NULL,NULL,NULL),
	 ('0bb0f022-254d-4dbd-a3cb-9e996d29f196'::uuid,'01990b9b-a79e-70ca-95fe-ea7cd246cd45'::uuid,'Cold Breath','Action','Ranged','Constitution Saving Throw: DC 13, each creature in a 15-foot Cone. Failure: 18 (4d8) Cold damage. Success: Half damage.',NULL,NULL,'d8',4,'Cold',5,false,NULL,NULL,NULL,NULL,NULL),
	 ('337a5b23-92cd-4a14-a2ca-529c593877d9'::uuid,'01990b9b-a79e-70ca-95fe-ea7cd246cd45'::uuid,'Multiattack','Action','None','The dragon makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('4bb3d0b3-f558-4164-bcd8-37fdbaf93caf'::uuid,'01990b9b-a79e-70ca-95fe-ea7cd246cd45'::uuid,'Paralyzing Breath','Action','Ranged','Constitution Saving Throw: DC 13, each creature in a 15-foot Cone. First Failure: The target has the Incapacitated condition until the end of its next turn, when it repeats the save. Second Failure: The target has the Paralyzed condition, and it repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a8c15375-17de-426c-b4bd-bb7defa45e84'::uuid,'01990b9b-a79e-70ca-95fe-ea7cd246cd45'::uuid,'Rend','Action','Melee','Melee Attack Roll: +6, reach 5 ft. Hit: 9 (1d10 + 4) Piercing damage.',6,4,'d10',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL);
