	 ('970d706f-fa90-421a-920f-071a873398ae'::uuid,'01990b9b-b26a-7327-8441-d4f66f09bca3'::uuid,'Shortbow','Action','None','Shortbow. Ranged Attack Roll: +5, range 80/320 ft. Hit: 6 (1d6 + 3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('b37ec5b8-4c68-4946-9655-df3eaffdfc5f'::uuid,'01990b9b-b26a-7327-8441-d4f66f09bca3'::uuid,'Shortsword','Action','None','Shortsword. Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('29f6a475-8435-447a-87c8-c54c1b6e4035'::uuid,'01990b9b-be81-714c-8a96-1504fc180739'::uuid,'Bite','Action','Melee','Hit: 5 (1d6 + 2) Piercing damage.',4,2,'d6',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('04a17674-099c-4d8a-ad4d-384c2372e655'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Spellcasting','Action','None','Spellcasting. The solar casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 25):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('24064824-a05e-4b94-83de-b0897b61dacb'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Divine Aid','Bonus','None','The solar casts Cure Wounds (level 2 version), Lesser Restoration, or Remove Curse, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,3,false,NULL,NULL,NULL,NULL,NULL),
	 ('98ab0fbc-109c-4b0d-ab2b-ce5027151bc9'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Blinding Gaze','Legendary','None','Constitution Saving Throw: DC 25, one creature the solar can see within 120 feet. Failure: The target has the Blinded condition for 1 minute. Failure or Success: The solar can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a48934e5-4d41-481b-8873-60191dacbf8d'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Flying Sword','Action','None','Flying Sword. Melee or Ranged Attack Roll: +15, reach 10 ft. or range 120 ft. Hit: 22 (4d6 + 8) Slashing damage plus 36 (8d8) Radiant damage. Hit or Miss: The sword magically returns to the solar''s hand or hovers within 5 feet of the solar immediately after a ranged attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('af95b1f4-2e05-42cd-9b24-166f8aaa293a'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Slaying Bow','Action','None','Slaying Bow. Dexterity Saving Throw: DC 21, one creature the solar can see within 600 feet. Failure: If the creature has 100 Hit Points or fewer, it dies. It otherwise takes 24 (4d8 + 6) Piercing damage plus 36 (8d8) Radiant damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d438688c-0a91-45f1-a03f-5beaa0cbd050'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Radiant Teleport','Legendary','None','The solar teleports up to 60 feet to an unoccupied space it can see. Dexterity Saving Throw: DC 25, each creature in a 10-foot Emanation originating from the solar at its destination space. Failure: 11 (2d10) Radiant damage. Success: Half damage.',NULL,NULL,'d10',2,'Radiant',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('e2919181-f2a5-41be-be9a-a0cd4096b8c2'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Multiattack','Action','None','Multiattack. The solar makes two Flying Sword attacks. It can replace one attack with a use of Slaying Bow.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
