	 ('ffb9f8ee-0f7f-4578-8c65-0d2cc338f220'::uuid,'01990b9c-12de-79f6-83bc-a27b1119d392'::uuid,'Life Drain','Action','None','Life Drain. Melee Attack Roll: +4, reach 5 ft. Hit: 7 (2d6) Necrotic damage. If the target is a creature, its Hit Point maximum decreases by an amount equal to the damage taken.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('52697c31-f8fe-4ccc-937e-85043849ff0c'::uuid,'01990b9c-448b-766b-b406-884f0c13df26'::uuid,'Arcane Prowl','Legendary','Melee','The sphinx can teleport up to 30 feet to an unoccupied space it can see, and it makes one Claw attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('fc6069a7-99af-4c30-8650-076f891ecd4b'::uuid,'01990b9d-4396-7f0b-8c80-ccd708213be2'::uuid,'Cunning Action','Bonus','None','The spy takes the Dash, Disengage, or Hide action.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('0a032bab-567b-4686-9330-2ecf33687021'::uuid,'01990b9d-5f81-7d10-ba9f-0e4240a48ed5'::uuid,'Claw','Action','Melee','Hit: 2 (1d4) Slashing damage plus 2 (1d4) Fire damage.',2,NULL,'d4',1,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('7c90b582-0286-4b52-a70e-39bbebf8c957'::uuid,'01990b9c-448b-766b-b406-884f0c13df26'::uuid,'Weight of Years','Legendary','None','Constitution Saving Throw: DC 16, one creature the sphinx can see within 120 feet. Failure: The target gains 1 Exhaustion level. While the target has any Exhaustion levels, it appears 3d10 years older. Failure or Success: The sphinx can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('97b2192d-53e6-44dc-baa2-38f49ccf8fca'::uuid,'01990b9c-448b-766b-b406-884f0c13df26'::uuid,'Claw','Action','Melee','Melee Attack Roll: +8, reach 5 ft. Hit: 14 (3d6 + 4) Slashing damage.',8,4,'d6',3,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('9bbecbf4-e7c5-47a5-9b05-5ce29b6573bd'::uuid,'01990b9c-448b-766b-b406-884f0c13df26'::uuid,'Spellcasting','Action','None','The sphinx casts one of the following spells, requiring no Material components and using Intelligence as the spellcasting ability (spell save DC 16):',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('db56e360-23df-46d3-af27-dbd2fc847c8d'::uuid,'01990b9c-448b-766b-b406-884f0c13df26'::uuid,'Mind-Rending Roar','Action','None','Wisdom Saving Throw: DC 16, each enemy in a 300-foot Emanation originating from the sphinx. Failure: 35 (10d6) Psychic damage, and the target has the Incapacitated condition until the start of the sphinx''s next turn.',NULL,NULL,'d6',10,'Psychic',6,false,NULL,NULL,NULL,NULL,NULL),
	 ('e0722ef3-e587-4c88-8759-d17c8a73c898'::uuid,'01990b9c-448b-766b-b406-884f0c13df26'::uuid,'Multiattack','Action','None','The sphinx makes three Claw attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('1086d927-015f-49b5-a2dc-1ff7b89834e3'::uuid,'01990b9c-8dc7-70a2-825f-e4e7f1eb7123'::uuid,'Roar (3/Day)','Action','None','Roar (3/Day). The sphinx emits a magical roar. Whenever it roars, the roar has a different effect, as detailed below (the sequence resets when it takes a Long Rest):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
