	 ('680010e2-5e0b-4e9b-9df4-eb2ccad0407f'::uuid,'01990b9c-8dc7-70a2-825f-e4e7f1eb7123'::uuid,'Weight of Years','Legendary','None','Constitution Saving Throw: DC 16, one creature the sphinx can see within 120 feet. Failure: The target gains 1 Exhaustion level. While the target has any Exhaustion levels, it appears 3d10 years older. Failure or Success: The sphinx can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('81692d9e-f27b-4441-a0d7-a6b9b04e4774'::uuid,'01990b9c-8dc7-70a2-825f-e4e7f1eb7123'::uuid,'Spellcasting','Action','None','Spellcasting. The sphinx casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 20):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8211ecca-ffde-4e5f-905d-af0ddd9809e8'::uuid,'01990b9c-8dc7-70a2-825f-e4e7f1eb7123'::uuid,'Multiattack','Action','None','Multiattack. The sphinx makes two Claw attacks and uses Roar.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('cf1f2153-ba64-4633-b257-270d5336662d'::uuid,'01990b9c-8dc7-70a2-825f-e4e7f1eb7123'::uuid,'Second Roar','Action','None','Second Roar. Wisdom Saving Throw: DC 20, each enemy in a 500-foot Emanation originating from the sphinx. Failure: The target has the Paralyzed condition, and it repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e234bc64-c4af-46a5-aff4-e15bafb79f6d'::uuid,'01990b9c-8dc7-70a2-825f-e4e7f1eb7123'::uuid,'Arcane Prowl','Legendary','Melee','The sphinx can teleport up to 30 feet to an unoccupied space it can see, and it makes one Claw attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('37055eae-12e3-44d0-8817-b6389a9a85f2'::uuid,'01990b9c-a5b6-7f0b-8041-2f75b72eeb76'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4 + 3) Slashing damage plus 7 (2d6) Radiant damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7c8ff683-d887-4fc9-94f6-aa6ea5a26740'::uuid,'01990b9c-a5b6-7f0b-8041-2f75b72eeb76'::uuid,'Burst of Ingenuity','Reaction','None','Trigger: The sphinx or another creature within 30 feet makes an ability check or a saving throw. Response: The sphinx adds 2 to the roll.',NULL,NULL,NULL,NULL,NULL,2,false,'The sphinx or another creature within 30 feet makes an ability check or a saving throw.',NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('f01862fd-3b17-4a0a-89e0-1a3029daf560'::uuid,'01990b9c-bd39-7ff6-b85d-02672802e040'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 1 Piercing damage plus 2 (1d4) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('00dc44b4-2242-4361-b579-27ed6d1707f9'::uuid,'01990b9c-e45d-7819-b628-3351feb49fdc'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +7, reach 10 ft. Hit: 7 (1d6 + 4) Piercing damage plus 14 (4d6) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('097fe917-c18f-4bde-9e9e-a3ad4853652c'::uuid,'01990b9c-e45d-7819-b628-3351feb49fdc'::uuid,'Multiattack','Action','None','Multiattack. The naga makes three attacks, using Bite or Necrotic Ray in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('659a10a7-5f92-4558-8c30-c23d66e2ebf7'::uuid,'01990b9c-e45d-7819-b628-3351feb49fdc'::uuid,'Spellcasting','Action','None','Spellcasting. The naga casts one of the following spells, requiring no Somatic or Material components and using Intelligence as the spellcasting ability (spell save DC 14):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('720047ad-ea21-4ff3-8a10-de70f35d7b92'::uuid,'01990b9c-e45d-7819-b628-3351feb49fdc'::uuid,'Necrotic Ray','Action','None','Necrotic Ray. Ranged Attack Roll: +6, range 60 ft. Hit: 21 (6d6) Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('02d938bf-ff04-4dae-9fa1-5619beadda03'::uuid,'01990b9c-f5cd-7d93-88b1-727940aba349'::uuid,'Invisibility','Action','None','Invisibility. The sprite casts Invisibility on itself, requiring no spell components and using Charisma as the spellcasting ability.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('69deafe5-1e38-4c7f-ba2b-b208796a880b'::uuid,'01990b9c-f5cd-7d93-88b1-727940aba349'::uuid,'Enchanting Bow','Action','None','Enchanting Bow. Ranged Attack Roll: +6, range 40/160 ft. Hit: 1 Piercing damage, and the target has the Charmed condition until the start of the sprite''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('909ecaed-7352-43be-a07c-1511df7686ef'::uuid,'01990b9c-f5cd-7d93-88b1-727940aba349'::uuid,'Heart Sight','Action','None','Heart Sight. Charisma Saving Throw: DC 10, one creature within 5 feet the sprite can see (Celestials, Fiends, and Undead automatically fail the save). Failure: The sprite knows the target''s emotions and alignment.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f5bfc08e-9872-4e09-a5ea-b53b0743e09c'::uuid,'01990b9c-f5cd-7d93-88b1-727940aba349'::uuid,'Needle Sword','Action','None','Needle Sword. Melee Attack Roll: +6, reach 5 ft. Hit: 6 (1d4 + 4) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('1e1732d2-1ede-418d-8efd-c803d614ae2e'::uuid,'01990b9d-1b49-74b8-9cc5-ac0fa4bc67b6'::uuid,'Hand Crossbow','Action','None','Hand Crossbow. Ranged Attack Roll: +4, range 30/120 ft. Hit: 5 (1d6 + 2) Piercing damage plus 7 (2d6) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('32153298-121b-498c-843a-a381f801f366'::uuid,'01990b9d-1b49-74b8-9cc5-ac0fa4bc67b6'::uuid,'Cunning Action','Bonus','None','The spy takes the Dash, Disengage, or Hide action.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('da6824d1-88c3-433f-b1b7-a13c0f74daee'::uuid,'01990b9d-1b49-74b8-9cc5-ac0fa4bc67b6'::uuid,'Shortsword','Action','None','Shortsword. Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage plus 7 (2d6) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('43d1bee9-f4d2-4ef6-b5a1-bb66b775e7f0'::uuid,'01990b9d-4396-7f0b-8c80-ccd708213be2'::uuid,'Smoke Bomb (1/Day)','Action','None','Smoke Bomb (1/Day). The spy throws a bomb to a point it can see within 30 feet of itself. Constitution Saving Throw: DC 16, each creature in a 20-foot-radius Sphere centered on that point. Failure: 28 (8d6) Poison damage, and the target has the Blinded condition until the end of the spy''s next turn. Success: Half damage only.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('6e3462cf-d4d3-49e5-9ef4-ecb06949d20f'::uuid,'01990b9d-4396-7f0b-8c80-ccd708213be2'::uuid,'Hand Crossbow','Action','None','Hand Crossbow. Ranged Attack Roll: +9, range 30/120 ft. Hit: 12 (2d6 + 5) Piercing damage plus 9 (2d8) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c26fe2dc-ab6f-41fe-9688-d78fb291769b'::uuid,'01990b9d-4396-7f0b-8c80-ccd708213be2'::uuid,'Rapier','Action','None','Rapier. Melee Attack Roll: +9, reach 5 ft. Hit: 14 (2d8 + 5) Piercing damage plus 7 (2d6) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d746858b-674d-4f11-878f-2d26ead889dd'::uuid,'01990b9d-4396-7f0b-8c80-ccd708213be2'::uuid,'Multiattack','Action','None','Multiattack. The spy makes three attacks, using Rapier or Hand Crossbow in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('b7bb0664-3082-450f-be7a-f290e972c09a'::uuid,'01990b9d-5f81-7d10-ba9f-0e4240a48ed5'::uuid,'Steam Breath','Action','None','Failure: 5 (2d4) Fire damage, and the target''s Speed decreases by 10 feet until the end of the mephit''s next turn. Success: Half damage only. Failure or Success: Being underwater doesn''t grant Resistance to this Fire damage.',NULL,NULL,'d4',2,'Fire',6,false,NULL,NULL,NULL,NULL,NULL),
	 ('6e1dcca6-e74b-4c05-8e83-42f3e44c6ae0'::uuid,'01990b9d-6859-7c01-ad19-4c968eca4e64'::uuid,'Proboscis','Action','None','Proboscis. Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage, and the stirge attaches to the target. While attached, the stirge can''t make Proboscis attacks, and the target takes 5 (2d4) Necrotic damage at the start of each of the stirge''s turns. The stirge can detach itself by spending 5 feet of its movement. The target or a creature within 5 feet of it can detach the stirge as an action.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0575495c-4f46-4990-a3c5-ac5396792982'::uuid,'01990b9d-8198-7d90-8f18-a8afea090c40'::uuid,'Boulder','Action','None','Boulder. Ranged Attack Roll: +9, range 60/240 ft. Hit: 15 (2d8 + 6) Bludgeoning damage. If the target is a Large or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('3df69b62-325c-4851-9d0d-729e09fb69e6'::uuid,'01990b9d-8198-7d90-8f18-a8afea090c40'::uuid,'Multiattack','Action','None','Multiattack. The giant makes two attacks, using Stone Club or Boulder in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('516220f0-494b-4075-96d5-10e58207a167'::uuid,'01990b9d-8198-7d90-8f18-a8afea090c40'::uuid,'Deflect Missile','Reaction','None','The giant reduces the damage it takes from the attack by 11 (1d10 + 6), and if that damage is reduced to 0, the giant can redirect some of the attack''s force. Dexterity Saving Throw: DC 17, one creature the giant can see within 60 feet. Failure: 11 (1d10 + 6) Force damage.',NULL,NULL,'d10',1,'Force',1,false,'The giant is hit by a ranged attack roll and takes Bludgeoning, Piercing, or Slashing damage from it.',NULL,NULL,NULL,NULL),
	 ('b1284f98-a4e4-4553-a20b-21220ed1ca2d'::uuid,'01990b9d-8198-7d90-8f18-a8afea090c40'::uuid,'Stone Club','Action','None','Stone Club. Melee Attack Roll: +9, reach 15 ft. Hit: 22 (3d10 + 6) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('1fb08d37-e6de-454c-a088-5f382e529d3a'::uuid,'01990b9d-c819-752c-a16b-d7c5bed6ab33'::uuid,'Force Bolt','Action','None','Force Bolt. Ranged Attack Roll: +9, range 90 ft. Hit: 26 (4d12) Force damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2fe5565a-3aed-405a-aa10-345a05e9b400'::uuid,'01990b9d-c819-752c-a16b-d7c5bed6ab33'::uuid,'Slow','Bonus','None','The golem casts the Slow spell, requiring no spell components and using Constitution as the spellcasting ability (spell save DC 17).',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('80879688-898e-4bee-885a-e6dcbf8a6914'::uuid,'01990b9d-c819-752c-a16b-d7c5bed6ab33'::uuid,'Multiattack','Action','None','Multiattack. The golem makes two attacks, using Slam or Force Bolt in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('dd8858d8-721c-42ca-b200-6662ef1edd67'::uuid,'01990b9d-c819-752c-a16b-d7c5bed6ab33'::uuid,'Slam','Action','None','Slam. Melee Attack Roll: +10, reach 5 ft. Hit: 15 (2d8+6) Bludgeoning damage plus 9 (2d8) Force damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('378659f2-1e8e-46cb-9615-6d7ab1251b6d'::uuid,'01990b9d-f6bb-733d-a315-5547bf7fad88'::uuid,'Lightning Storm (Recharge 5–6)','Action','None','Lightning Storm (Recharge 5–6). Dexterity Saving Throw: DC 18, each creature in a 10-foot-radius, 40-foot-high Cylinder originating from a point the giant can see within 500 feet. Failure: 55 (10d10) Lightning damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('76eafced-74cc-40c4-9920-ddbd05b72c53'::uuid,'01990b9d-f6bb-733d-a315-5547bf7fad88'::uuid,'Thunderbolt','Action','None','Thunderbolt. Ranged Attack Roll: +14, range 500 ft. Hit: 22 (2d12 + 9) Lightning damage, and the target has the Blinded and Deafened conditions until the start of the giant''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7920b7fd-e838-4f43-b559-46a4c8be15f5'::uuid,'01990b9d-f6bb-733d-a315-5547bf7fad88'::uuid,'Spellcasting','Action','None','Spellcasting. The giant casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 18):',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('dad9c23d-b3ff-48dc-8afd-42628855cdc4'::uuid,'01990b9d-f6bb-733d-a315-5547bf7fad88'::uuid,'Multiattack','Action','None','Multiattack. The giant makes two attacks, using Storm Sword or Thunderbolt in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('f9a4ee80-42ed-44ea-a26a-fb73db7ac02c'::uuid,'01990b9d-f6bb-733d-a315-5547bf7fad88'::uuid,'Storm Sword','Action','None','Storm Sword. Melee Attack Roll: +14, reach 10 ft. Hit: 23 (4d6 + 9) Slashing damage plus 13 (3d8) Lightning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('152b9442-a8ae-473f-9b5a-a699120d4e8b'::uuid,'01990b9e-1f47-7736-b2c9-33a8b0d9c7c6'::uuid,'Shape-Shift','Bonus','None','The succubus shape-shifts into a Medium or Small Humanoid, or it returns to its true form. Its game statistics are the same in each form, except its Fly Speed is available only in its true form. Any equipment it is wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('54b25e09-bee6-4303-a21d-714223e349af'::uuid,'01990b9e-1f47-7736-b2c9-33a8b0d9c7c6'::uuid,'Fiendish Touch','Action','Melee','Melee Attack Roll: +7, reach 5 ft. Hit: 16 (2d10 + 5) Psychic damage.',7,5,'d10',2,'Psychic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('80613424-e376-4fb4-823d-bbe48b31f250'::uuid,'01990b9e-1f47-7736-b2c9-33a8b0d9c7c6'::uuid,'Draining Kiss','Action','None','Constitution Saving Throw: DC 15, one creature Charmed by the succubus within 5 feet. Failure: 13 (3d8) Psychic damage. Success: Half damage. Failure or Success: The target''s Hit Point maximum decreases by an amount equal to the damage taken.',NULL,NULL,'d8',3,'Psychic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c4c9c44d-21fa-4c9a-b4e9-cd2200f44e54'::uuid,'01990b9e-1f47-7736-b2c9-33a8b0d9c7c6'::uuid,'Multiattack','Action','None','The succubus makes one Fiendish Touch attack and uses Charm or Draining Kiss.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('e067a983-26ee-4023-966c-3aea50496f3e'::uuid,'01990b9e-1f47-7736-b2c9-33a8b0d9c7c6'::uuid,'Charm','Action','None','The succubus casts Dominate Person (level 8 version), requiring no spell components and using Charisma as the spellcasting ability (spell save DC 15).',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a3b75ea3-70a7-440e-812c-024f12e4415f'::uuid,'01990b9e-2eb1-7e96-9c4d-dca36a8a937c'::uuid,'Bites','Action','Melee','Hit: 5 (2d4) Piercing damage, or 2 (1d4) Piercing damage if the swarm is Bloodied.',4,NULL,'d4',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('13112c26-e9df-462f-ac5f-bf26ede98acd'::uuid,'01990b9e-3e10-79e7-bfdc-99463f610607'::uuid,'Swarm of Grasping Hands','Action','Melee','Hit: 20 (4d8 + 2) Necrotic damage, or 11 (2d8 + 2) Necrotic damage if the swarm is Bloodied. If the target is a Medium or smaller creature, it has the Prone condition.',4,2,'d8',4,'Necrotic',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c7f9c65b-838a-4b8e-97b1-cc6b16267ead'::uuid,'01990b9e-594b-7099-a5c8-4206f1043f75'::uuid,'Bites','Action','Melee','Hit: 6 (2d4 + 1) Poison damage, or 3 (1d4 + 1) Poison damage if the swarm is Bloodied.',3,NULL,'d4',2,'Poison',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('36f58f63-43b0-4a0d-b954-6eeeb9a4687f'::uuid,'01990b9e-7d90-7c8c-bc33-c191c3d55828'::uuid,'Bites','Action','Melee','Hit: 8 (2d4 + 3) Piercing damage, or 5 (1d4 + 3) Piercing damage if the swarm is Bloodied.',5,3,'d4',2,'Piercing',NULL,false,NULL,'if the target doesn''t have all its Hit Points',NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('65a578ce-1dc2-4961-a533-b60abdcee35b'::uuid,'01990b9e-89ef-7d2f-8b2b-fb832e11eab9'::uuid,'Bites','Action','Melee','Hit: 5 (2d4) Piercing damage, or 2 (1d4) Piercing damage if the swarm is Bloodied.',2,NULL,'d4',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('549e1c6b-e468-47b4-ad78-ad719d7a5e94'::uuid,'01990b9e-9b5e-7a25-9ba7-e257b3e5d813'::uuid,'Cacophony','Action','None','Failure: The target has the Deafened condition until the start of the swarm''s next turn. While Deafened, the target also has Disadvantage on ability checks and attack rolls.',NULL,NULL,NULL,NULL,NULL,NULL,false,'Recharge 6',NULL,NULL,NULL,NULL),
	 ('ab3de314-ce70-46b2-b17a-16193bfb45a6'::uuid,'01990b9e-9b5e-7a25-9ba7-e257b3e5d813'::uuid,'Beaks','Action','Melee','Hit: 5 (1d6 + 2) Piercing damage, or 2 (1d4) Piercing damage if the swarm is Bloodied.',4,NULL,'d6',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('525a68d9-8e90-4f56-be0c-a51cb0244ce3'::uuid,'01990b9e-b0c3-7a4d-aff3-04c5c23964c5'::uuid,'Bites','Action','Melee','Hit: 8 (1d8 + 4) Piercing damage—or 6 (1d4 + 4) Piercing damage if the swarm is Bloodied—plus 10 (3d6) Poison damage.',6,4,'d8',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('01ddf118-d4b9-40e2-a3ec-c6602c16fdd2'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +19, reach 15 ft. Hit: 28 (4d8 + 10) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0c4a08d9-2c1e-42bf-9eac-650a25ca7868'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +19, reach 15 ft. Hit: 36 (4d12 + 10) Piercing damage, and the target has the Grappled condition (escape DC 20). Until the grapple ends, the target has the Restrained condition and can''t teleport.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('1170cb74-497f-4168-990d-27bc544ee91e'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Onslaught','Legendary','Melee','The tarrasque moves up to half its Speed, and it makes one Claw or Tail attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('4b0d05b0-600f-4bad-b4f9-473b67af1bad'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Thunderous Bellow (Recharge 5–6)','Action','None','Thunderous Bellow (Recharge 5–6). Constitution Saving Throw: DC 27, each creature and each object that isn''t being worn or carried in a 150-foot Cone. Failure: 78 (12d12) Thunder damage, and the target has the Deafened and Frightened conditions until the end of its next turn. Success: Half damage only.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('502adc5c-f699-4493-ab12-a1f140e925df'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Multiattack','Action','None','Multiattack. The tarrasque makes one Bite attack and three other attacks, using Claw or Tail in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('641f5744-f919-4fb3-867e-f77810172e32'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Tail','Action','None','Tail. Melee Attack Roll: +19, reach 30 ft. Hit: 23 (3d8 + 10) Bludgeoning damage. If the target is a Huge or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('824db3f3-f9e3-4763-a9f0-d075538e90e0'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Swallow','Bonus','None','Strength Saving Throw: DC 27, one Large or smaller creature Grappled by the tarrasque (it can have up to six creatures swallowed at a time). Failure: The target is swallowed, and the Grappled condition ends. A swallowed creature has the Blinded and Restrained conditions and can''t teleport, it has Total Cover against attacks and other effects outside the tarrasque, and it takes 56 (16d6) Acid damage at the start of each of the tarrasque''s turns. If the tarrasque takes 60 damage or more on a single turn from a creature inside it, the tarrasque must succeed on a DC 20 Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, each of which falls in a space within 10 feet of the tarrasque and has the Prone condition. If the tarrasque dies, any swallowed creature no longer has the Restrained condition and can escape from the corpse using 20 feet of movement, exiting Prone.',NULL,NULL,'d6',16,'Acid',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('bbd7d092-d5b4-4a1c-b86d-4a2967a23b2f'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'World-Shaking Movement','Legendary','None','The tarrasque moves up to its Speed. At the end of this movement, the tarrasque creates an instantaneous shock wave in a 60-foot Emanation originating from itself. Creatures in that area lose Concentration and, if Medium or smaller, have the Prone condition. The tarrasque can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a0a83a3f-738c-4d71-a16e-1faec0b49c6a'::uuid,'01990b9f-1a86-73ff-8e8e-db9b3e0dd5df'::uuid,'Nimble Escape','Bonus','None','The tiger takes the Disengage or Hide action.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('d7ff8fc9-299e-4162-a5ad-e06fb22513c5'::uuid,'01990b9f-1a86-73ff-8e8e-db9b3e0dd5df'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage. If the target is a Large or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('714dd56a-4db5-49ad-9732-0beadfa95986'::uuid,'01990b9f-2d29-79c5-9dfe-686f0a8a1fa4'::uuid,'Mace','Action','None','Mace. Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('88e477e7-a4a8-47b2-8d2a-914faee57fa5'::uuid,'01990b9f-2d29-79c5-9dfe-686f0a8a1fa4'::uuid,'Heavy Crossbow','Action','None','Heavy Crossbow. Ranged Attack Roll: +3, range 100/400 ft. Hit: 6 (1d10 + 1) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('01224d53-59bd-4ccb-9a5d-37b8f3ee6538'::uuid,'01990b9f-4c44-74ba-92d8-529597b5b534'::uuid,'Multiattack','Action','None','Multiattack. The tough makes two attacks, using Warhammer or Heavy Crossbow in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('9424f176-b77f-42be-9920-cc03c56b3787'::uuid,'01990b9f-4c44-74ba-92d8-529597b5b534'::uuid,'Warhammer','Action','None','Warhammer. Melee Attack Roll: +5, reach 5 ft. Hit: 12 (2d8 + 3) Bludgeoning damage, and if the target is Large or smaller, the tough can push the target up to 10 feet straight away from itself.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c1771917-9388-4656-8b9a-af5edf9ac9e7'::uuid,'01990b9f-4c44-74ba-92d8-529597b5b534'::uuid,'Heavy Crossbow','Action','None','Heavy Crossbow. Ranged Attack Roll: +4, range 100/400 ft. Hit: 13 (2d10+2) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('235a553e-7c66-4280-998d-a985022a656d'::uuid,'01990b9f-729c-7293-b789-1eec243b8314'::uuid,'Multiattack','Action','None','Multiattack. The treant makes two Slam attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('4776a6a7-3cab-4050-8816-5da6d634a374'::uuid,'01990b9f-729c-7293-b789-1eec243b8314'::uuid,'Hail of Bark','Action','None','Hail of Bark. Ranged Attack Roll: +10, range 180 ft. Hit: 28 (4d10 + 6) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7f5db5ed-3db5-4c14-83f9-09a73523bd76'::uuid,'01990b9f-729c-7293-b789-1eec243b8314'::uuid,'Slam','Action','None','Slam. Melee Attack Roll: +10, reach 5 ft. Hit: 16 (3d6 + 6) Bludgeoning damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('cbb82502-4f13-4716-a59e-85194c49fe8c'::uuid,'01990b9f-729c-7293-b789-1eec243b8314'::uuid,'Animate Trees (1/Day)','Action','None','Animate Trees (1/Day). The treant magically animates up to two trees it can see within 60 feet of itself. Each tree uses the Treant stat block, except it has Intelligence and Charisma scores of 1, it can''t speak, and it lacks this action. The tree takes its turn immediately after the treant on the same Initiative count, and it obeys the treant. A tree remains animate for 1 day or until it dies, the treant dies, or it is more than 120 feet from the treant. The tree then takes root if possible.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('b1da5761-778a-4e3e-a412-0990cbdfd755'::uuid,'01990b9f-825a-7862-a84b-cd7bcdaaa2fb'::uuid,'Gore','Action','None','Gore. Melee Attack Roll: +9, reach 5 ft. Hit: 19 (2d12 + 6) Piercing damage. If the target is Huge or smaller and the triceratops moved 20+ feet straight toward it immediately before the hit, the target takes an extra 9 (2d8) Piercing damage and has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f04226de-89ff-481f-98a7-ff857cef9bbd'::uuid,'01990b9f-825a-7862-a84b-cd7bcdaaa2fb'::uuid,'Multiattack','Action','None','Multiattack. The triceratops makes two Gore attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('3714880f-4939-48a4-8e9d-99710f991aac'::uuid,'01990b9f-adbc-79b0-950a-332d7bb3236e'::uuid,'Charge','Bonus','None','The troll moves up to half its Speed straight toward an enemy it can see.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('a6087a3c-7fcd-4182-9385-f38ddecc9e1d'::uuid,'01990b9f-adbc-79b0-950a-332d7bb3236e'::uuid,'Multiattack','Action','None','The troll makes three Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('fa32b317-0ee0-47a0-96f8-0d8992140270'::uuid,'01990b9f-adbc-79b0-950a-332d7bb3236e'::uuid,'Rend','Action','Melee','Melee Attack Roll: +7, reach 10 ft. Hit: 11 (2d6 + 4) Slashing damage.',7,4,'d6',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('afd52501-bf21-45d5-8669-19bf34ec6741'::uuid,'01990b9f-c19e-7b96-a3e5-c802b8ab3ccf'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +6, reach 5 ft. Hit: 9 (2d4 + 4) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('945a21ea-53f8-400e-8ae8-ea6bf3369ffd'::uuid,'01990b9f-dbe6-7112-90ab-5976d959b6e8'::uuid,'Bite','Action','Melee','Melee Attack Roll: +10, reach 10 ft. Hit: 33 (4d12 + 7) Piercing damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 17). While Grappled, the target has the Restrained condition and can''t be targeted by the tyrannosaurus''s Tail.',10,7,'d12',4,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL);
