	 ('bd84f2a6-2ba8-4615-9820-5758a32dff31'::uuid,'01990b9f-dbe6-7112-90ab-5976d959b6e8'::uuid,'Tail','Action','Melee','Melee Attack Roll: +10, reach 15 ft. Hit: 25 (4d8 + 7) Bludgeoning damage. If the target is a Huge or smaller creature, it has the Prone condition.',10,7,'d8',4,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('cdbb8dca-1844-4b60-95f0-b3913858922a'::uuid,'01990b9f-dbe6-7112-90ab-5976d959b6e8'::uuid,'Multiattack','Action','None','The tyrannosaurus makes one Bite attack and one Tail attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('0d6a60e8-0dd6-4d5b-9730-c1622b4c9476'::uuid,'01990ba0-06f1-7c9c-93d2-d4295bd1b34d'::uuid,'Rend','Action','Melee','Melee Attack Roll: +8, reach 10 ft. Hit: 12 (2d6 + 5) Slashing damage.',8,5,'d6',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('bd94b4d2-22a3-41fa-91eb-f442972cee82'::uuid,'01990ba0-06f1-7c9c-93d2-d4295bd1b34d'::uuid,'Multiattack','Action','Melee','The umber hulk makes three Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('d987d837-4dc6-4693-b275-d20319fc80f8'::uuid,'01990ba0-06f1-7c9c-93d2-d4295bd1b34d'::uuid,'Confusing Gaze','Bonus','None','Wisdom Saving Throw: DC 14, each creature in a 30-foot Cone. Failure: The target can''t take Reactions until the start of the umber hulk''s next turn, and the target rolls 1d8 to determine what it does on its next turn:',NULL,NULL,'d8',1,NULL,5,false,'Recharge 5-6',NULL,NULL,NULL,NULL),
	 ('055adda7-e1a6-4956-afd8-5550a40398b8'::uuid,'01990ba0-3ed3-7d1b-9f46-aba91aedab20'::uuid,'Multiattack','Action','None','The unicorn makes one Hooves attack and one Radiant Horn attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('10affac1-07f6-4850-935c-ce6bd4658eaa'::uuid,'01990ba0-3ed3-7d1b-9f46-aba91aedab20'::uuid,'Hooves','Action','Melee','Melee Attack Roll: +7, reach 5 ft. Hit: 11 (2d6 + 4) Bludgeoning damage.',7,4,'d6',2,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('5d5aba67-9bd5-4d21-ade5-14d462fb86ca'::uuid,'01990ba1-42e6-7a3d-a034-77b0db3aefe7'::uuid,'Multiattack','Action','None','The necrohulk makes two Rotting Slam attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('11980a28-4f27-41e5-8bd5-76939f9ff4ec'::uuid,'01990ba0-3ed3-7d1b-9f46-aba91aedab20'::uuid,'Radiant Horn','Action','Melee','Melee Attack Roll: +7, reach 5 ft. Hit: 9 (1d10 + 4) Radiant damage.',7,4,'d10',1,'Radiant',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('2ec4fa29-c55d-4b2c-9938-dc8372cd9602'::uuid,'01990ba0-3ed3-7d1b-9f46-aba91aedab20'::uuid,'Spellcasting','Action','None','The unicorn casts one of the following spells, requiring no spell components and using Charisma as the spellcasting ability (spell save DC 14):',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('534825c7-3e80-45e0-bd95-94d7a9822da0'::uuid,'01990ba0-3ed3-7d1b-9f46-aba91aedab20'::uuid,'Shimmering Shield','Legendary','None','The unicorn targets itself or one creature it can see within 60 feet of itself. The target gains 10 (3d6) Temporary Hit Points, and its AC increases by 2 until the end of the unicorn''s next turn. The unicorn can''t take this action again until the start of its next turn.',NULL,NULL,'d6',3,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('664d7441-53d3-42aa-884a-aa4dff51292b'::uuid,'01990ba0-3ed3-7d1b-9f46-aba91aedab20'::uuid,'Charging Horn','Legendary','Melee','The unicorn moves up to half its Speed without provoking Opportunity Attacks, and it makes one Radiant Horn attack.',NULL,NULL,NULL,NULL,'Radiant',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('f29f0f45-c3a2-46ed-9d02-91805debec36'::uuid,'01990ba0-3ed3-7d1b-9f46-aba91aedab20'::uuid,'Unicorn''s Blessing','Bonus','None','The unicorn touches another creature with its horn and casts Cure Wounds or Lesser Restoration on that creature, using the same spellcasting ability as Spellcasting.',NULL,NULL,NULL,NULL,NULL,3,false,NULL,NULL,NULL,NULL,NULL),
	 ('394628e5-7dd8-4c9d-8233-b420bae513ff'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Deathless Strike','Legendary','Melee','The vampire moves up to half its Speed, and it makes one Grave Strike attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('64fb8297-c65e-42b5-8221-3dd2de1a1257'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Beguile','Legendary','None','The vampire casts Command, requiring no spell components and using Charisma as the spellcasting ability (spell save DC 17). The vampire can''t take this action again until the start of its next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('79c81e32-1917-46bc-8be4-29255b463b81'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Grave Strike','Action','Melee','Melee Attack Roll: +9, reach 5 ft. Hit: 8 (1d8 + 4) Bludgeoning damage plus 7 (2d6) Necrotic damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from one of two hands.',9,NULL,'d8',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('7bf79567-2d75-43f3-9769-815b171a95ee'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Bite','Action','Melee','Constitution Saving Throw: DC 17, one creature within 5 feet that is willing or that has the Grappled, Incapacitated, or Restrained condition. Failure: 6 (1d4 + 4) Piercing damage plus 13 (3d8) Necrotic damage. The target''s Hit Point maximum decreases by an amount equal to the Necrotic damage taken, and the vampire regains Hit Points equal to that amount. A Humanoid reduced to 0 Hit Points by this damage and then buried rises the following sunset as a Vampire Spawn under the vampire''s control.',NULL,NULL,'d4',1,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ad2db7f7-f372-4319-a192-ac3cb2c202ed'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Multiattack','Action','None','The vampire makes two Grave Strike attacks and uses Bite.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b2cc756f-df44-4ff1-b5fa-8366f5b23e4d'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Charm','Bonus','None','The vampire casts Charm Person, requiring no spell components and using Charisma as the spellcasting ability (spell save DC 17), and the duration is 24 hours. The Charmed target is a willing recipient of the vampire''s Bite, the damage of which doesn''t end the spell. When the spell ends, the target is unaware it was Charmed by the vampire.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('c41d2ea8-ec7f-43cd-9607-16eaf51d97c2'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Shape-Shift','Bonus','None','If the vampire isn''t in sunlight or running water, it shape-shifts into a Tiny bat (Speed 5 ft., Fly Speed 30 ft.) or a Medium cloud of mist (Speed 5 ft., Fly Speed 20 ft. [hover]), or it returns to its vampire form. Anything it is wearing transforms with it. While in bat form, the vampire can''t speak. Its game statistics, other than its size and Speed, are unchanged. While in mist form, the vampire can''t take any actions, speak, or manipulate objects. It is weightless and can enter an enemy''s space and stop there. If air can pass through a space, the mist can do so, but it can''t pass through liquid. It has Resistance to all damage, except the damage it takes from sunlight.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('2f70a0c6-c5ec-4f88-bafc-d4cba9211d64'::uuid,'01990ba0-b815-75b3-9f30-91a807c062a9'::uuid,'Umbral Dagger','Action','None','Umbral Dagger. Melee or Ranged Attack Roll: +5, reach 5 ft. or range 20/60 ft. Hit: 5 (1d4+3) Piercing damage plus 7 (3d4) Necrotic damage. If the target is reduced to 0 Hit Points by this attack, the target becomes Stable but has the Poisoned condition for 1 hour. While it has the Poisoned condition, the target has the Paralyzed condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('3da87c5f-6e33-42ee-9408-c1a8c6e7cce5'::uuid,'01990ba0-b815-75b3-9f30-91a807c062a9'::uuid,'Deathless Agility','Bonus','None','The familiar takes the Dash or Disengage action.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('b2a00d10-4160-4c4e-8e10-ad30d46a3569'::uuid,'01990ba0-b815-75b3-9f30-91a807c062a9'::uuid,'Multiattack','Action','None','Multiattack. The familiar makes two Umbral Dagger attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('1a06bc17-e689-4f3a-b387-878eb15d3c8f'::uuid,'01990ba1-056f-79ba-8588-c0862f05a8e4'::uuid,'Bite','Action','None','Bite. Constitution Saving Throw: DC 14, one creature within 5 feet that is willing or that has the Grappled, Incapacitated, or Restrained condition. Failure: 5 (1d4 + 3) Piercing damage plus 10 (3d6) Necrotic damage. The target''s Hit Point maximum decreases by an amount equal to the Necrotic damage taken, and the vampire regains Hit Points equal to that amount.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('a1196d16-dc48-4e42-9c19-9d4bf4302280'::uuid,'01990ba1-056f-79ba-8588-c0862f05a8e4'::uuid,'Multiattack','Action','None','Multiattack. The vampire makes two Claw attacks and uses Bite.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('eff92cbe-9aec-4be6-a468-8aa5557d5ff7'::uuid,'01990ba1-056f-79ba-8588-c0862f05a8e4'::uuid,'Deathless Agility','Bonus','None','The vampire takes the Dash or Disengage action.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('f395eff8-653a-4648-adde-247aba76d27d'::uuid,'01990ba1-056f-79ba-8588-c0862f05a8e4'::uuid,'Claw','Action','None','Claw. Melee Attack Roll: +6, reach 5 ft. Hit: 8 (2d4 + 3) Slashing damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 13) from one of two claws.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2bbcf16f-efa8-4dec-a42b-20d1e167e139'::uuid,'01990ba1-172c-73f6-890c-ab578abcad67'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Piercing damage plus 3 (1d6) Poison damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('cd582359-4a8a-4de3-b61e-269b6d592255'::uuid,'01990ba1-22fe-7fe4-9f2b-90b2a58a9466'::uuid,'Multiattack','Action','Melee','The fungus makes two Rotting Touch attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('f5b777f4-1b61-48e7-8b82-c5eac33975c9'::uuid,'01990ba1-22fe-7fe4-9f2b-90b2a58a9466'::uuid,'Rotting Touch','Action','Melee','Melee Attack Roll: +2, reach 10 ft. Hit: 4 (1d8) Necrotic damage.',2,NULL,'d8',1,'Necrotic',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('31638549-af71-411f-a485-d636b1396c45'::uuid,'01990ba1-42e6-7a3d-a034-77b0db3aefe7'::uuid,'Absorb Body','Bonus','None','Strength Saving Throw: DC 15, one Medium or Small creature the necrohulk can see within 5 feet. Failure: The target is pulled into the necrohulk''s space and becomes grafted to its body. The necrohulk can have only one target grafted at a time. While grafted, the target has the Restrained condition and Disadvantage on Constitution saving throws. When the necrohulk moves, the grafted target moves with it. If the target dies while grafted, its body is destroyed, and the necrohulk regains 10 Hit Points. The grafted target or a creature within 5 feet of the necrohulk can take an action to make a DC 15 Strength (Athletics) check. On a successful check, the target is no longer grafted and moves to an unoccupied space within 5 feet of the necrohulk.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('479a0ee2-51dd-471a-a69e-65457d3acbae'::uuid,'01990ba1-42e6-7a3d-a034-77b0db3aefe7'::uuid,'Rotting Slam','Action','Melee','Melee Attack Roll: +7, reach 10 ft. Hit: 9 (1d10+ 4) Bludgeoning damage plus 7 (2d6) Necrotic damage.',7,4,'d10',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('59946077-023e-484c-84a6-412939512384'::uuid,'01990ba1-42e6-7a3d-a034-77b0db3aefe7'::uuid,'Spore Bomb','Action','None','Constitution Saving Throw: DC 15, each creature in a 20-foot-radius Sphere centered on a point the necrohulk can see within 60 feet. Failure: 28 (8d6) Necrotic damage, and the target has the Poisoned condition until the start of the necrohulk''s next turn. While Poisoned, the target can''t regain Hit Points. Success: Half damage only.',NULL,NULL,'d6',8,'Necrotic',NULL,false,'Recharge 5-6',NULL,NULL,NULL,NULL),
	 ('0d294a7c-cad4-4b1e-ab3e-201caaeeab4c'::uuid,'01990ba1-65b6-7a75-a157-ead1d511ef35'::uuid,'Spores','Action','None','Constitution Saving Throw: DC 15, each creature in a 20-foot Emanation originating from the vrock. Failure: The target has the Poisoned condition and repeats the save at the end of each of its turns, ending the effect on itself on a success. While Poisoned, the target takes 5 (1d10) Poison damage at the start of each of its turns. Emptying a flask of Holy Water on the target ends the effect early.',NULL,NULL,'d10',1,'Poison',6,false,NULL,NULL,NULL,NULL,NULL),
	 ('cf48ebd4-6705-4f24-86e4-00f153389d9e'::uuid,'01990ba1-65b6-7a75-a157-ead1d511ef35'::uuid,'Shred','Action','Melee','Melee Attack Roll: +6, reach 5 ft. Hit: 10 (2d6 + 3) Piercing damage plus 10 (3d6) Poison damage.',6,NULL,'d6',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('e1077dfe-24ff-4bf6-867b-a8a21597fc2a'::uuid,'01990ba1-65b6-7a75-a157-ead1d511ef35'::uuid,'Stunning Screech','Action','None','Constitution Saving Throw: DC 15, each creature in a 20-foot Emanation originating from the vrock (demons succeed automatically). Failure: 10 (3d6) Thunder damage, and the target has the Stunned condition until the end of the vrock''s next turn.',NULL,NULL,'d6',3,'Thunder',1,false,NULL,NULL,NULL,NULL,NULL),
	 ('ec910c45-3db6-4efe-80ef-a17a0344da47'::uuid,'01990ba1-65b6-7a75-a157-ead1d511ef35'::uuid,'Multiattack','Action','None','The vrock makes two Shred attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('13832d6b-2479-4df2-a90a-edbb8ead22a2'::uuid,'01990ba1-747c-7190-af9c-d8e426c92d24'::uuid,'Beak','Action','None','Beak. Melee Attack Roll: +2, reach 5 ft. Hit: 2 (1d4) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('bef101f8-0616-4ddf-a4cc-d19fb979b65f'::uuid,'01990ba1-7b48-7294-8e7f-7728b1132bd5'::uuid,'Hooves','Action','None','Hooves. Melee Attack Roll: +6, reach 5 ft. Hit: 9 (2d4 + 4) Bludgeoning damage. If the horse moved at least 20 feet straight toward the target immediately before the hit, the target takes an extra 5 (2d4) Bludgeoning damage and, if it is Huge or smaller, has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2ea18c0a-3834-479a-9b0d-00fec34da5a1'::uuid,'01990ba1-86e4-7bd4-8d38-75830e163557'::uuid,'Hooves','Action','Melee','Hit: 7 (1d6 + 4) Bludgeoning damage. If the target is a Large or smaller creature and the skeleton moved 20+ feet straight toward it immediately before the hit, the target has the Prone condition.',6,4,'d6',1,'Bludgeoning',NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('2ff561f2-7305-47ac-bee7-02bb47c865ee'::uuid,'01990ba1-c083-784c-b3c0-e5467b244e32'::uuid,'Multiattack','Action','None','Multiattack. The warrior makes three attacks, using Greatsword or Longbow in any combination.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('3754ba66-950d-464f-b7ac-bbdc9ad3bce7'::uuid,'01990ba1-c083-784c-b3c0-e5467b244e32'::uuid,'Sap','Action','None','Sap. The target has Disadvantage on its next attack roll before the start of the warrior''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('5496497f-6562-44c6-a1c7-1c76dea624af'::uuid,'01990ba1-c083-784c-b3c0-e5467b244e32'::uuid,'Maneuver','Action','None','Maneuver. One ally who can see or hear the warrior can take a Reaction to move up to half the ally''s Speed without provoking Opportunity Attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('62960439-552a-4fb1-859b-9c4cadd07eda'::uuid,'01990ba1-c083-784c-b3c0-e5467b244e32'::uuid,'Counterattack','Reaction','None','The warrior adds 4 to its AC against the triggering attack. On a miss, the warrior can make one Greatsword or Longbow attack against the attacker.',NULL,NULL,NULL,NULL,NULL,NULL,false,'The warrior is hit by an attack roll.',NULL,NULL,NULL,NULL),
	 ('6dacc9fc-6cf6-46c2-8a64-e7ccdd2fd428'::uuid,'01990ba1-c083-784c-b3c0-e5467b244e32'::uuid,'Longbow','Action','None','Longbow. Ranged Attack Roll: +9, range 150/600 ft. Hit: 18 (3d8 + 5) Piercing damage, and the target''s Speed decreases by 10 feet until the end of the target''s next turn.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c20c535d-eed2-4175-94fd-3ea9a0dd6c2c'::uuid,'01990ba1-c083-784c-b3c0-e5467b244e32'::uuid,'Greatsword','Action','None','Greatsword. Melee Attack Roll: +9, reach 5 ft. Hit: 19 (4d6 + 5) Slashing damage. The warrior also creates one of the following effects:',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('f708d679-2f77-436a-a341-fe2278416975'::uuid,'01990ba1-c083-784c-b3c0-e5467b244e32'::uuid,'Tactical Charge','Bonus','None','The warrior moves up to half its Speed straight toward an enemy it can see without provoking Opportunity Attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('47544765-725e-4fa3-9551-dcf932ff0cfa'::uuid,'01990ba1-cf18-7896-b425-2cf5a117af2c'::uuid,'Spear','Action','None','Spear. Melee or Ranged Attack Roll: +3, reach 5 ft. or range 20/60 ft. Hit: 4 (1d6 + 1) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('05d2aea5-89df-47b4-b0b0-345298635a4a'::uuid,'01990ba1-f9a3-7a38-b354-a999f5fa4e47'::uuid,'Parry','Reaction','None','The warrior adds 2 to its AC against the triggering attack, possibly causing it to miss.',NULL,NULL,NULL,NULL,NULL,NULL,false,'The warrior is hit by a melee attack roll while holding a weapon.',NULL,NULL,NULL,NULL),
	 ('2e1ec5d3-f683-4c71-9f03-38e301e8f21b'::uuid,'01990ba1-f9a3-7a38-b354-a999f5fa4e47'::uuid,'Multiattack','Action','None','The warrior makes two Greatsword or Heavy Crossbow attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('ca6410e6-b2a2-4d34-8d60-518af51770bd'::uuid,'01990ba1-f9a3-7a38-b354-a999f5fa4e47'::uuid,'Heavy Crossbow','Action','Ranged','Ranged Attack Roll: +3, range 100/400 ft. Hit: 12 (2d10 + 1) Piercing damage.',3,1,'d10',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('ec1365e4-f0ce-4201-a4ca-fca56e1eb9e0'::uuid,'01990ba1-f9a3-7a38-b354-a999f5fa4e47'::uuid,'Greatsword','Action','Melee','Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage.',5,3,'d6',2,'Slashing',NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('7b5b7fd2-2618-4e67-baf5-5131965d5f5d'::uuid,'01990ba2-0c06-7e3c-9734-4195cb02aafa'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +5, reach 5 ft. Hit: 1 Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('543a2994-7d7c-4d06-9079-a28157fa2c19'::uuid,'01990ba2-397a-7509-a669-39a4d196f52a'::uuid,'Rend (Bear or Hybrid Form Only)','Action','None','Rend (Bear or Hybrid Form Only). Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8 + 4) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('78f5c8be-b130-47e6-a8de-6ee56daa6e4b'::uuid,'01990ba2-397a-7509-a669-39a4d196f52a'::uuid,'Bite (Bear or Hybrid Form Only)','Action','None','Bite (Bear or Hybrid Form Only). Melee Attack Roll: +7, reach 5 ft. Hit: 17 (2d12 + 4) Piercing damage. If the target is a Humanoid, it is subjected to the following effect. Constitution Saving Throw: DC 14. Failure: The target is cursed. If the cursed target drops to 0 Hit Points, it instead becomes a Werebear under the DM''s control and has 10 Hit Points. Success: The target is immune to this werebear''s curse for 24 hours.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('8ee3e866-63f8-4ef1-ad5b-8f144c80e1f5'::uuid,'01990ba2-397a-7509-a669-39a4d196f52a'::uuid,'Shape-Shift','Bonus','None','The werebear shape-shifts into a Large bear-humanoid hybrid form or a Large bear, or it returns to its true humanoid form. Its game statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('9d0b910e-f534-42c4-b827-6975356ad3ca'::uuid,'01990ba2-397a-7509-a669-39a4d196f52a'::uuid,'Multiattack','Action','None','Multiattack. The werebear makes two attacks, using Handaxe or Rend in any combination. It can replace one attack with a Bite attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c9f330e2-0439-4083-a48a-44f094fd6752'::uuid,'01990ba2-397a-7509-a669-39a4d196f52a'::uuid,'Handaxe (Humanoid or Hybrid Form Only)','Action','None','Handaxe (Humanoid or Hybrid Form Only). Melee or Ranged Attack Roll: +7, reach 5 ft or range 20/60 ft. Hit: 14 (3d6 + 4) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('352f1320-a6dc-4499-b7e4-5d11c6bb2762'::uuid,'01990ba2-6114-7177-8fb4-2818a044b6e2'::uuid,'Shape-Shift','Bonus','None','The wereboar shape-shifts into a Medium boar-humanoid hybrid or a Small boar, or it returns to its true humanoid form. Its game statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('4be3ed57-6c72-45f6-a9a1-040a7fe86936'::uuid,'01990ba2-6114-7177-8fb4-2818a044b6e2'::uuid,'Tusk (Boar or Hybrid Form Only)','Action','None','Tusk (Boar or Hybrid Form Only). Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Piercing damage. If the target is a Medium or smaller creature and the wereboar moved 20+ feet straight toward it immediately before the hit, the target takes an extra 7 (2d6) Piercing damage and has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('6e76be9e-725f-448f-a46a-21e226adbc22'::uuid,'01990ba2-6114-7177-8fb4-2818a044b6e2'::uuid,'Javelin (Humanoid or Hybrid Form Only)','Action','None','Javelin (Humanoid or Hybrid Form Only). Melee or Ranged Attack Roll: +5, reach 5 ft. or range 30/120 ft. Hit: 13 (3d6 + 3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7e29ef95-a32e-4fab-abc0-940089eb1851'::uuid,'01990ba2-6114-7177-8fb4-2818a044b6e2'::uuid,'Multiattack','Action','None','Multiattack. The wereboar makes two attacks, using Javelin or Tusk in any combination. It can replace one attack with a Gore attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('5f1d69fd-0f93-4ed7-ade2-b44c4a275b35'::uuid,'01990ba4-c421-75bc-a07e-40fec710eb31'::uuid,'Fire Breath','Action','Ranged','Dexterity Saving Throw: DC 17, each creature in a 30-foot Cone. Failure: 55 (10d10) Fire damage. Success: Half damage.',NULL,NULL,'d10',10,'Fire',5,false,NULL,NULL,NULL,NULL,NULL),
	 ('a6be3973-db91-4c16-a39d-e379ffe7110d'::uuid,'01990ba2-6114-7177-8fb4-2818a044b6e2'::uuid,'Gore (Boar or Hybrid Form Only)','Action','None','Gore (Boar or Hybrid Form Only). Melee Attack Roll: +5, reach 5 ft. Hit: 12 (2d8 + 3) Piercing damage. If the target is a Humanoid, it is subjected to the following effect. Constitution Saving Throw: DC 12. Failure: The target is cursed. If the cursed target drops to 0 Hit Points, it instead becomes a Wereboar under the DM''s control and has 10 Hit Points. Success: The target is immune to this wereboar''s curse for 24 hours.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('2008a44c-4813-4d65-959a-c79a12c37776'::uuid,'01990ba2-81d0-730e-b70b-bb07b1769bdb'::uuid,'Scratch','Action','None','Scratch. Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('305d850d-f029-4875-9ead-bb3156b4e0ec'::uuid,'01990ba2-81d0-730e-b70b-bb07b1769bdb'::uuid,'Bite (Rat or Hybrid Form Only)','Action','None','Bite (Rat or Hybrid Form Only). Melee Attack Roll: +5, reach 5 ft. Hit: 8 (2d4 + 3) Piercing damage. If the target is a Humanoid, it is subjected to the following effect. Constitution Saving Throw: DC 11. Failure: The target is cursed. If the cursed target drops to 0 Hit Points, it instead becomes a Wererat under the DM''s control and has 10 Hit Points. Success: The target is immune to this wererat''s curse for 24 hours.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('af14da5c-289d-422d-a942-33512620f83d'::uuid,'01990ba2-81d0-730e-b70b-bb07b1769bdb'::uuid,'Multiattack','Action','None','Multiattack. The wererat makes two attacks, using Scratch or Hand Crossbow in any combination. It can replace one attack with a Bite attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('b491b544-b0bc-463c-9309-1ecfdb591696'::uuid,'01990ba2-81d0-730e-b70b-bb07b1769bdb'::uuid,'Hand Crossbow (Humanoid or Hybrid Form Only)','Action','None','Hand Crossbow (Humanoid or Hybrid Form Only). Ranged Attack Roll: +5, range 30/120 ft. Hit: 6 (1d6 + 3) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e0bde2c6-f82d-4b55-a1e9-f21940a54213'::uuid,'01990ba2-81d0-730e-b70b-bb07b1769bdb'::uuid,'Shape-Shift','Bonus','None','The wererat shape-shifts into a Medium rat-humanoid hybrid or a Small rat, or it returns to its true humanoid form. Its game statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('263e23ca-f65f-449c-b1d0-1d968dc7a971'::uuid,'01990ba2-adea-76b2-95a6-c217f23fb54c'::uuid,'Bite (Tiger or Hybrid Form Only)','Action','None','Bite (Tiger or Hybrid Form Only). Melee Attack Roll: +5, reach 5 ft. Hit: 12 (2d8 + 3) Piercing damage. If the target is a Humanoid, it is subjected to the following effect. Constitution Saving Throw: DC 13. Failure: The target is cursed. If the cursed target drops to 0 Hit Points, it instead becomes a Weretiger under the DM''s control and has 10 Hit Points. Success: The target is immune to this weretiger''s curse for 24 hours.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('329c2e74-1d11-48c0-9593-78407f444a1e'::uuid,'01990ba2-adea-76b2-95a6-c217f23fb54c'::uuid,'Shape-Shift','Bonus','None','The weretiger shape-shifts into a Large tiger-humanoid hybrid or a Large tiger, or it returns to its true humanoid form. Its game statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('3f15b411-0018-4339-bf93-f4945a191550'::uuid,'01990ba2-adea-76b2-95a6-c217f23fb54c'::uuid,'Multiattack','Action','None','Multiattack. The weretiger makes two attacks, using Scratch or Longbow in any combination. It can replace one attack with a Bite attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('60b4585d-043e-4a57-ae09-a8e2f41fd848'::uuid,'01990ba2-adea-76b2-95a6-c217f23fb54c'::uuid,'Scratch','Action','None','Scratch. Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7af457bb-b7ea-493b-a390-925b72632113'::uuid,'01990ba2-adea-76b2-95a6-c217f23fb54c'::uuid,'Longbow (Humanoid or Hybrid Form Only)','Action','None','Longbow (Humanoid or Hybrid Form Only). Ranged Attack Roll: +4, range 150/600 ft. Hit: 11 (2d8 + 2) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('d98425e2-8ad5-47dc-b996-e3bdca35d287'::uuid,'01990ba2-adea-76b2-95a6-c217f23fb54c'::uuid,'Prowl','Bonus','None','The weretiger moves up to its Speed without provoking Opportunity Attacks. At the end of this movement, the weretiger can take the Hide action.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('551f62d2-2c5e-41a0-9354-04dc31b5cd57'::uuid,'01990ba2-e045-7df6-864d-b0a83c748250'::uuid,'Shape-Shift','Bonus','None','The werewolf shape-shifts into a Large wolf-humanoid hybrid or a Medium wolf, or it returns to its true humanoid form. Its game statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn''t transformed.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
	 ('635e9c42-9c81-4e1f-903b-6004fb0aa4d8'::uuid,'01990ba2-e045-7df6-864d-b0a83c748250'::uuid,'Scratch','Action','None','Scratch. Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('6cd57207-1b9a-4a63-b308-756b05656396'::uuid,'01990ba2-e045-7df6-864d-b0a83c748250'::uuid,'Bite (Wolf or Hybrid Form Only)','Action','None','Bite (Wolf or Hybrid Form Only). Melee Attack Roll: +5, reach 5 ft. Hit: 12 (2d8 + 3) Piercing damage. If the target is a Humanoid, it is subjected to the following effect. Constitution Saving Throw: DC 12. Failure: The target is cursed. If the cursed target drops to 0 Hit Points, it instead becomes a Werewolf under the DM''s control and has 10 Hit Points. Success: The target is immune to this werewolf''s curse for 24 hours.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('766eea29-9aa4-4c86-8f1e-81390de372ef'::uuid,'01990ba2-e045-7df6-864d-b0a83c748250'::uuid,'Longbow (Humanoid or Hybrid Form Only)','Action','None','Longbow (Humanoid or Hybrid Form Only). Ranged Attack Roll: +4, range 150/600 ft. Hit: 11 (2d8 + 2) Piercing damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('c21d0334-15ad-4747-8338-1ba276616342'::uuid,'01990ba2-e045-7df6-864d-b0a83c748250'::uuid,'Multiattack','Action','None','Multiattack. The werewolf makes two attacks, using Scratch or Longbow in any combination. It can replace one attack with a Bite attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
INSERT INTO public.actions (id,monster_id,"name","type",attack_type,description,attack_bonus,damage_bonus,damage_dice,number_damage_dice,damage_type,limit_per_day,is_prohibited_for_minion,action_trigger,advantage_condition,disadvantage_condition,long_range,short_range) VALUES
	 ('0a45349d-dd52-40b1-9650-b0a748fc8267'::uuid,'01990ba3-3ff6-7d5c-8664-486a196fb755'::uuid,'Multiattack','Action','None','Multiattack. The dragon makes two Rend attacks.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('50600144-df86-4375-885e-733fc93894f3'::uuid,'01990ba3-3ff6-7d5c-8664-486a196fb755'::uuid,'Rend','Action','None','Rend. Melee Attack Roll: +4, reach 5 ft. Hit: 6 (1d8 + 2) Slashing damage plus 2 (1d4) Cold damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('dc32246e-413a-42c7-8108-41c9afdc45a7'::uuid,'01990ba3-3ff6-7d5c-8664-486a196fb755'::uuid,'Cold Breath (Recharge 5–6)','Action','None','Cold Breath (Recharge 5–6). Constitution Saving Throw: DC 12, each creature in a 15-foot Cone. Failure: 22 (5d8) Cold damage. Success: Half damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('16631c86-82d8-4e50-8b0b-a3c62ce79afb'::uuid,'01990ba3-5aed-79e1-ae68-bd05dcb45c94'::uuid,'Multiattack','Action','None','Multiattack. The wight makes two attacks, using Necrotic Sword or Necrotic Bow in any combination. It can replace one attack with a use of Life Drain.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('7692a27b-3a85-4e82-8ff2-dc63a926c6d3'::uuid,'01990ba3-5aed-79e1-ae68-bd05dcb45c94'::uuid,'Life Drain','Action','None','Life Drain. Constitution Saving Throw: DC 13, one creature within 5 feet. Failure: 6 (1d8 + 2) Necrotic damage, and the target''s Hit Point maximum decreases by an amount equal to the damage taken. A Humanoid slain by this attack rises 24 hours later as a Zombie under the wight''s control, unless the Humanoid is restored to life or its body is destroyed. The wight can have no more than twelve zombies under its control at a time.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('98f42703-a587-4172-956f-b738befdf56c'::uuid,'01990ba3-5aed-79e1-ae68-bd05dcb45c94'::uuid,'Necrotic Bow','Action','None','Necrotic Bow. Ranged Attack Roll: +4, range 150/600 ft. Hit: 6 (1d8 + 2) Piercing damage plus 4 (1d8) Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('e4bc0b0b-a9a7-4b9a-9aa8-5479ccbe3394'::uuid,'01990ba3-5aed-79e1-ae68-bd05dcb45c94'::uuid,'Necrotic Sword','Action','None','Necrotic Sword. Melee Attack Roll: +4, reach 5 ft. Hit: 6 (1d8 + 2) Slashing damage plus 4 (1d8) Necrotic damage.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('0c14903e-ae9f-45cc-a7bc-f78e11961a71'::uuid,'01990ba3-7008-7efe-b3a4-73087f811671'::uuid,'Bite','Action','Melee','Hit: 11 (2d6 + 4) Piercing damage. If the target is a Large or smaller creature, it has the Prone condition.',6,4,'d6',2,'Piercing',NULL,false,NULL,NULL,NULL,NULL,NULL),
