	 ('3e2878ee-6032-45b8-9d07-cf56f4244e76'::uuid,'01990ba3-8ef5-7f92-9108-2a6e7eb361a0'::uuid,'Bite','Action','None','Bite. Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage. If the target is a Medium or smaller creature, it has the Prone condition.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','','');
