	 ('57732aba-8590-459e-88ee-a7ff3ec527bd'::uuid,'01990ba3-9645-73c0-9c3a-7435da06e06c'::uuid,'Bite','Action','Melee','Hit: 7 (1d8 + 3) Piercing damage, and the next attack roll made against the target before the start of the worg''s next turn has Advantage.',5,3,'d8',1,'Piercing',NULL,false,NULL,'the next attack roll made against the target before the start of the worg''s next turn',NULL,NULL,NULL),
	 ('4339682d-c766-46d3-9720-1f2f6d3c2a6e'::uuid,'01990ba3-a9eb-7e67-bd83-7158f0741ba0'::uuid,'Life Drain','Action','None','Life Drain. Melee Attack Roll: +6, reach 5 ft. Hit: 21 (4d8 + 3) Necrotic damage. If the target is a creature, its Hit Point maximum decreases by an amount equal to the damage taken.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('fe23041c-9fff-4a10-8a42-026fb96fcffd'::uuid,'01990ba3-a9eb-7e67-bd83-7158f0741ba0'::uuid,'Create Specter','Action','None','Create Specter. The wraith targets a Humanoid corpse within 10 feet of itself that has been dead for no longer than 1 minute. The target''s spirit rises as a Specter in the space of its corpse or in the nearest unoccupied space. The specter is under the wraith''s control. The wraith can have no more than seven specters under its control at a time.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
	 ('1dc84c25-2c88-44a1-8dbf-fc6dbd55e8d2'::uuid,'01990ba3-b839-7a29-a74b-7d028cc297cb'::uuid,'Multiattack','Action','None','The wyvern makes one Bite attack and one Sting attack.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
