	 ('14c77f9c-8b28-4047-95f5-b518c62d359a'::uuid,'01990ba3-de82-7b6d-aa69-e8c531983283'::uuid,'Charge','Bonus','None','The xorn moves up to its Speed or Burrow Speed straight toward an enemy it can sense.',NULL,NULL,NULL,NULL,NULL,NULL,false,NULL,NULL,NULL,NULL,NULL),
