	 ('26c0edd4-80bf-4532-b311-91546caf5798'::uuid,'01990ba4-0775-7c93-a9c9-7f5a06bb764b'::uuid,'Chilling Gaze','Action','None','Chilling Gaze. Constitution Saving Throw: DC 13, one creature the yeti can see within 30 feet. Failure: 5 (2d4) Cold damage, and the target has the Paralyzed condition until the start of the yeti''s next turn unless the target has Immunity to Cold damage. Success: The target is immune to the Chilling Gaze of all yetis (but not abominable yetis) for 1 hour.',NULL,NULL,NULL,NULL,NULL,NULL,false,'','','','',''),
